(window.GIM_TS=window.GIM_TS||{})["Yoma.4"]={"from":96,"a":[["\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יצחק נפחא\u0004 \u0005[הנפח]\u0006 \u0003לר' אמי:\u0004 והרי נאמר: \u0003\"והוציא את כל הפר\u0004 אל מחוץ למחנה\u0003\"\u0004 (ויקרא ד, יב) ושם מדובר בפר לאחר שנשחט ולאחר שהקטירו את חלביו ואימוריו, משמע שאף לאחר שחיטה עדיין הוא קרוי פר! ענה לו ר' אמי: שם הכוונה היא לומר \u0003שיוציא את כולו,\u0004 כלומר: את כל הנותר מן הפר.","ועוד מקשים: הלא נאמר: \u0003\"ואת פר החטאת ואת שעיר החטאת\u0004 אשר הובא את דמם לכפר בקודש יוציא אל מחוץ למחנה\u0003\"\u0004 (ויקרא טז, כז). הרי שאף לאחר שחיטה, בשלב של הכנסת הדם לקודש הקדשים עדיין הוא קרוי פר! \u0003אמר רב פפא: בעור ובשר ופרש דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שאף זה קרוי פר, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה בענין \u0003דם. מר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 \u0003סבר; דם איקרי\u0004 \u0005[נקרא]\u0006 \u0003פר, ומר\u0004 \u0005[וחכם\u0006 זה\u0005]\u0006 \u0003סבר; דם\u0004 בלבד \u0003לא איקרי\u0004 \u0005[נקרא]\u0006 \u0003פר.\u0004","\u0003אמר רב אשי: מסתברא\u0004 \u0005[מסתבר]\u0006 \u0003כמאן דאמר\u0004 \u0005[\u0006כדעת \u0005מי שאמר]\u0006 כי \u0003דם איקרי\u0004 \u0005[נקרא]\u0006 \u0003פר, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בזאת יבא אהרן אל הקדש בפר בן בקר\"\u0004 (ויקרא טז, ג), \u0003אטו בקרניה מעייל ליה\u0004 \u0005[וכי בקרניו\u0006 הוא \u0005מכניס אותו]\u0006 לקודש הקדשים?! \u0003אלא בדמו\u0004 הוא נכנס, \u0003וקרי ליה\u0004 \u0005[והוא קורא לו]\u0006 \u0003\"פר\",\u0004 משמע שאף הדם בלבד קרוי פר.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 הסבור שדם אינו קרוי פר, כיצד מבין הוא פסוק זה? ומשיבים: כי לשיטה זו יש לומר: \u0003במה הוכשר אהרן לבא אל הקדש — בפר בן בקר לחטאת\u0004 ודרך הבאתו לפנים — ענין לעצמו הוא.","על בעיה זו אם נכנס כהן בדמו של פר ראשון, שואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 תשובה לבעיה זו ש\u0003חטאת שמתו בעליה היא,\u0004 שהרי פרו של הכהן הגדול פר חטאת הוא, ומתו בעליו, ולפי הכלל: \u0003חטאת שמתו בעליה — למיתה אזלא\u0004 \u0005[היא הולכת],\u0006 ואם כן אין מקום לשאלה זו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבין בר רב אדא לרבא: אמרי תלמידיך\u0004 \u0005[אומרים תלמידיך];\u0006 \u0003אמר רב עמרם:\u0004 פר החטאת של הכהן הגדול \u0003חטאת צבור היא,\u0004 שהרי היא מביאה הכהן הגדול עליו ועל אחיו הכהנים, וחטאת ציבור הרי \u0003לא למיתה אזלא\u0004 \u0005[\u0006היא \u0005הולכת].\u0006","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת תמורה (יד, א), שנחלקו תנאים מה הם הקרבנות הדוחים את השבת ואת הטומאה. ובענין זה \u0003אמר לו ר' מאיר: והלא פר יום הכפורים וחביתי\u0004 (מנחת המחבת המיוחדת של) \u0003כהן גדול, ופסח,\u0004 ש\u0003קרבן יחיד הוא ודוחה את השבת ואת הטומאה.\u0004 וכיון שר' מאיר אומר שקרבן יחיד הוא, \u0003לאו מכלל דאיכא למאן דאמר\u0004 \u0005[האם לא\u0006 תבין \u0005מכלל\u0006 הדברים \u0005שיש מי שאומר]\u0006 שכל אלה קרבנות \u0003צבור\u0004 הם? ותהא זו הוכחה למה שאמרנו.","את ההוכחה הזו דוחים: \u0003ולטעמיך, דקתני\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005, מה שלמדנו]\u0006 שם: \u0003אמר לו ר' יעקב: והלא פר העלם דבר של צבור, ושעירי עבודה זרה,\u0004 וקרבן \u0003חגיגה,\u0004 ש\u0003קרבן צבור\u0004 הם \u0003ואין דוחין לא את השבת ולא את הטומאה!\u0004 ולפי שיטת ההסבר הזו צריך לומר \u0003מכלל דאיכא למאן דאמר\u0004 \u0005[מכלל\u0006 הדברים תלמד \u0005שיש מי שאומר]\u0006 שאלה קרבנות \u0003יחיד\u0004 הם, והרי דבר זה ודאי איננו נכון!","\u0003אלא,\u0004 כך עליך להבין: ר' מאיר \u0003לתנא קמא קא מהדר ליה\u0004 \u0005[הוא עונה לו]\u0006 \u0003דשמעיה דקאמר\u0004 \u0005[שהוא שמע אותו שהוא אומר]\u0006 וקובע כלל: \u0003קרבן צבור דוחה את השבת ואת הטומאה, וקרבן יחיד אינו דוחה לא את השבת ולא את הטומאה. אמר לו ר' מאיר:\u0004 וכי קביעה זו ביחס ל\u0003קרבן יחיד כללא\u0004 \u0005[כלל\u0006 גמור\u0005]\u0006 \u0003הוא? והלא פר יום הכפורים, וחביתי כהן גדול, ופסח,\u0004 ש\u0003קרבן יחיד הוא ודוחין את השבת ואת הטומאה!\u0004","\u0003ואמר לו ר' יעקב\u0004 לתנא הראשון מצד אחר: וכי \u0003קרבן צבור כללא\u0004 \u0005[כלל\u0006 גמור\u0005]\u0006 \u0003הוא\u0004 שהוא דוחה? \u0003והלא פר העלם דבר של צבור ושעירי עבודה זרה, וחגיגה\u0004 ש\u0003קרבן צבור הוא ואין דוחין לא את השבת ולא את הטומאה!\u0004","\u0003אלא, נקוט האי כללא בידך\u0004 \u0005[החזק כלל זה בידך]:\u0006 \u0003כל\u0004 קרבן \u0003שזמנו קבוע — דוחה את השבת ואת הטומאה אפילו\u0004 הוא קרבן \u0003יחיד, וכל שאין זמנו קבוע — אינו דוחה לא את השבת ולא את הטומאה ואפילו בצבור.\u0004 ולפי הסבר זה יש עדיין לומר כי פר כהן גדול קרבן יחיד הוא.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 לרבא: וכי פר כהן גדול קרבן יחיד הוא? והלא שנינו: \u0003פר ושעיר של יום הכפורים שאבדו, והפריש אחרים תחתיהן,\u0004 ונמצאו הראשונים — \u0003כולם\u0004 כל המופרשים השניים \u0003ימותו, וכן שעירי עבודה זרה שאבדו, והפריש אחרים תחתיהן — כולם ימותו,\u0004 אלו \u0003דברי ר' יהודה. ר' אלעזר ור' שמעון אומרים: ירעו עד שיסתאבו\u0004 (שיפול בהם מום) ואז \u0003ימכרו, ויפלו דמיהן\u0004 לקרבן \u0003נדבה, שאין חטאת צבור מתה.\u0004 והרי הוכחה שפר יום הכיפורים קרוי חטאת ציבור!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לאביי: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003פר\u0004 זה המוזכר כאן — \u0003פר העלם דבר של צבור.\u0004 חזר והקשה לו אביי: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"של יום הכפורים\" קתני\u0004 \u0005[שנה]\u0006 שם, משמע שמדובר בפר של יום הכיפורים! ושוב דחאו רבא: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 \"של יום הכיפורים\" כוונתו היתה \u0003לשעיר,\u0004 וכך יש להבין את המשנה: פר של ציבור, וכן שעיר של יום הכיפורים, שאף הוא קרבן הציבור.","הקשה לו: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פר של יום הכפורים, ושעיר של יום הכפורים שאבדו והפריש אחרים תחתיהן\u0004 ונמצאו — \u0003כולם ימותו,\u0004 אלו \u0003דברי ר' יהודה, ר' אלעזר ור' שמעון אומרים: ירעו עד שיסתאבו\u0004 (שיפול בהם מום) \u0003וימכרו ויפלו דמיהן\u0004 לקרבן \u0003נדבה, שאין חטאת צבור מתה.\u0004 הרי ששנינו במפורש שהיא נחשבת כקרבן ציבור!","ענה לו: \u0003לא תימא\u0004 \u0005[תאמר],\u0006 כלומר: אל תדקדק בלשון \u0003\"שאין חטאת צבור מתה\", אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003\"שאין חטאת השותפין מתה\"\u0004 שכיון שנשארו אחדים מן השותפין בחיים — אין החטאת מתה. ופר כהן גדול ביום הכיפורים, כיון שלא הוא לבדו אלא גם אחיו הכהנים מתכפרים בו, כקרבן השותפין הוא. ושואלים: מאחר וסוף סוף אין הפר הולך למיתה, אם כן \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא ממנה],\u0006 מה ההבדל אם קורים אנו לפרו של כהן גדול חטאת ציבור או חטאת השותפין, ומדוע הקפיד לכנותו בשם חטאת השותפין?","ומשיבים: כי על פי דין, אם הורה בית דין לציבור שלם (כגון שבט) הוראה מוטעית ועשו בני הציבור לפי הוראה זו, על בית הדין להביא (לפי כמה דעות) פר העלם דבר של ציבור. ולכן הקפיד לכנות פר זה כחטאת השותפים ולא כחטאת הציבור שאם קרבן שותפים הוא, הרי אם הורה בית דין של כהנים הוראה מוטעית ועשו הכהנים על פיהם ש\u0003לא מייתו\u0004 \u0005[מביאים]\u0006 ה\u0003כהנים פר בהוראה\u0004 זו, משום שהכהנים אינם קרויים ציבור לעצמם, ואינם אלא כשותפין מרובים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון נוסף לשאלה זו, \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003ר' אלעזר\u0004 את השאלה הבאה:"],["\u0003לדברי\u0004 ר' מאיר \u0003האומר\u0004 כי \u0003פר יום הכפורים קרבן יחיד\u0004 הוא האם \u0003עושה תמורה?\u0004 אם עבר הכהן הגדול על האיסור לעשות תמורה, ואמר שפר זה יומר באחר, האם חלה תמורה זו, \u0003או אינו עושה תמורה?\u0004 ומלשון השאלה, \u0003לאו\u0004 \u0005[האם לא]\u0006 תלמד \u0003מכלל\u0004 הדברים \u0003דאיכא למאן דאמר\u0004 \u0005[שיש מי שאומר]\u0006 שפר יום הכיפורים קרבן \u0003צבור\u0004 הוא?","ודוחים: \u0003לא,\u0004 אין זו הוכחה, אלא \u0003מכלל\u0004 הדברים נלמד \u0003דאיכא למאן דאמר\u0004 \u0005[שיש מי שאומר]\u0006 שהוא קרבן \u0003השותפין.\u0004 ואין ראיה חותכת שהוא נחשב לקרבן ציבור. ובכל אופן, הבעיה מפני מה אין הפר נפסל במיתת הכהן הגדול נפתרה, בין מפני שהוא קרבן ציבור, בין מפני שהוא של שותפים.","כיון שהוזכרה בעייתו זו של ר' אלעזר דנים בה ל\u0003גופא\u0004 (לגופה). \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר: לדברי\u0004 ר' מאיר \u0003האומר\u0004 כי \u0003פר יום הכפורים קרבן יחיד\u0004 הוא, האם \u0003עושה תמורה או אינו עושה תמורה?\u0004 ושואלים: \u0003מאי קא מיבעיא ליה\u0004 \u0005[מה נסתפק לו]\u0006 מהו עיקרה של הבעיה?","\u0003אי בתר\u0004 \u0005[האם אחר]\u0006 ה\u0003מקדיש אזלינן\u0004 \u0005[אנו הולכים]\u0006 וכיון ש\"המקדיש\" הוא הכהן הגדול שהרי פר זה בא מרכושו הפרטי, הריהו נחשב כקרבן יחיד ותמורתו תמורה, \u0003אי בתר\u0004 \u0005[או אחר]\u0006 ה\u0003מתכפר אזלינן\u0004 \u0005[אנו הולכים]\u0006 וכיון שבקרבן זה מכפר הכהן הגדול על ציבור אחיו הכהנים, הרי זה נחשב כקרבן ציבור ואין תמורתו תמורה. והשאלה היא אחרי מי הולכים במקרה כזה לענין תמורה.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 \u0003דבתר\u0004 \u0005[שאחר]\u0006 ה\u0003מתכפר אזלינן\u0004 \u0005[אנו הולכים],\u0006 שכבר \u0003אמר ר' אבהו אמר ר' יוחנן: המקדיש\u0004 את בהמתו לקרבן בכוונה שיתכפר בו אדם אחר, אם פודה אותו \u0003מוסיף חומש\u0004 עליו כדין כל הפודה הקדש שהוא עצמו מקדיש ולעומת זאת אם פדאה המתכפר, אינו צריך להוסיף עליה חומש. \u0003והמתכפר,\u0004 שעבורו הוקדש הקרבן הזה — \u0003עושה בה תמורה\u0004 ואילו המקדיש אינו יכול לעשותה תמורה, שלענין תמורה אינו נחשב כבעליה.","וכן \u0003התורם\u0004 מתבואתו \u0003שלו על\u0004 תבואתו \u0003של חבירו\u0004 כדי שלא יצטרך חבירו להפריש תרומה ממנה. אף שנתקנה תבואת חבירו והריהו נפטר מחובת תרומה, מכל מקום \u0003טובת הנאה שלו\u0004 — של התורם היא והוא זה שרשאי להחליט לאיזה כהן לתת את התרומה ואף שנתקנו פירות חבירו, אין זכות זו עומדת לזכותו של החבר אלא לזכות התורם. ומכן הוכחה שאף שנעשית המצוה לטובת אחרים, עדיין היא נחשבת ועומדת לזכותו של זה שהוציא הוצאות משלו עבורה. ואם כן, אין מקום לשאלת ר' אלעזר!","ודוחים: \u0003לעולם פשיטא ליה דבתר\u0004 \u0005[\u0006תאמר \u0005שברור לו שאחר]\u0006 ה\u0003מתכפר אזלינן\u0004 \u0005[הולכים אנו]\u0006 \u0003והכי קא מיבעיא ליה\u0004 \u0005[וכך נסתפק לו]:\u0006 \u0003אחיו הכהנים בקביעותא מתכפרי\u0004 \u0005[בקביעות,\u0006 בעיקרו של הקרבן הם \u0005מתכפרים]\u0006 וחלק מן הקרבן נעשה כשלהם ובשל כך הריהם נעשים כשותפים ולכך אף הם נחשבים כ\"מתכפר\" בקרבן זה, \u0003או דילמא בקופיא מתכפרי\u0004 \u0005[שמא בדרך אגב מתכפרים],\u0006 ועיקר הכפרה הוא לכהן הגדול, והוא הוא המתכפר האמיתי, ואם כן יש עדיין מקום לשאלה אם הכהן הגדול יכול לעשות בפר זה תמורה.","ומציעים: \u0003תא שמע\u0004 \u0005[בא ושמע]\u0006 פתרון לשאלה זו, ממה ששנינו: \u0003חומר בזבח\u0004 (בקרבן הראשון שהוקדש) \u0003מבתמורה\u0004 שעשו בו, \u0003וחומר בתמורה מבזבח.\u0004 והסבר הדברים: \u0003חומר בזבח\u0004 שקדושת \u0003הזבח נוהג ביחיד כבצבור,\u0004 והזבח \u0003דוחה את השבת ואת הטומאה,\u0004 והוא \u0003עושה תמורה — מה שאין כן בתמורה\u0004 שאין בה את כל אלה.","ולעומת זאת: \u0003חומר בתמורה מבזבח\u0004 — שקדושת ה\u0003תמורה חלה\u0004 בשעת תמורתה אפילו \u0003על בעל מום קבוע\u0004 ואם בא לחללה — \u0003אינה יוצאה לחולין\u0004 אלא לענין זביחה ואכילה בלבד אבל אינה מותרת בשום אופן שתוכל \u0003ליגזז\u0004 מצמרה \u0003וליעבד,\u0004 שאסורה בה עבודה לעולם, מפני שאין התרה לקדושתה, \u0003מה שאין כן בזבח\u0004 שיש אופנים שונים לפדיונו.","ומעתה נברר, \u0003האי זבח היכי דמי\u0004 \u0005[זבח זה\u0006 שהוזכר כאן \u0005כיצד\u0006 בדיוק \u0005הוא],\u0006 מה הוא זבח זה שדובר בו כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהוא זבח של \u0003יחיד, מי דחי\u0004 \u0005[האם דוחה]\u0006 קרבן יחיד את ה\u0003שבת\u0004 ואת \u0003הטומאה? אלא\u0004 תאמר שמדובר בזבח של \u0003צבור — מי\u0004 \u0005[האם]\u0006 \u0003עושה\u0004 קרבן ציבור \u0003תמורה? אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן במקרה מיוחד ב\u0003פר\u0004 של יום הכיפורים, שהוא \u0003דוחה את השבת ואת הטומאה\u0004 משום \u0003דקביע ליה\u0004 \u0005[שקבוע לו]\u0006 \u0003זמן,\u0004 וכפי שאמרנו כל קרבן שזמנו קבוע דוחה שבת וטומאה, \u0003ו\u0004בכל זאת הריהי \u0003עושה תמורה,\u0004 מפני שהוא \u0003קרבן יחיד,\u0004 ומכאן ראיה איפוא לשאלת ר' אליעזר.","ודוחים: \u0003אמר רב ששת: לא,\u0004 אין להוכיח מכאן, כי אפשר לומר שזבח זה שדובר בו הוא \u0003אילו של אהרן\u0004 שמקריב הכהן הגדול ביום הכיפורים לעולה (\"בזאת יבוא אהרן אל הקודש בפר בן בקר לחטאת ואיל לעולה\". ויקרא טז, ג) וקרבן זה הוא בודאי שלו בלבד ונחשב כקרבן יחיד.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם מסתבר],\u0006 \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שמדובר כאן \u0003בפרו\u0004 של הכהן הגדול, וכי \u0003תמורה\u0004 של \u0003פר\u0004 זה רק \u0003שבת וטומאה הוא\u0004 ש\u0003לא דחיא\u0004 \u0005[דוחה]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בחול מקריב קרבה\u0004 \u0005[מוקרבת היא\u0006 לקרבן\u0005]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 תמורה זו \u0003תמורת חטאת היא,\u0004 וידוע לנו כי \u0003תמורת חטאת למיתה אזלא\u0004 \u0005[הולכת]\u0006 ואין לה כל תקנה. אלא ודאי מדובר כאן באיל העולה, ותמורת עולה יכולים להקריב.","את הסיוע הזה דוחים: \u0003לא,\u0004 לעולם אפשר לפרש שזבח זה הוא \u0003פרו\u0004 של הכהן הגדול ביום הכיפורים, \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003תמורה\u0004 זו שנאמרה בו — אין הכוונה לתמורתו של פר זה, אלא ברייתא זו מדברת רק מענין \u0003שם תמורה,\u0004 כלומר: שמושג התמורה בכללו כולל דברים שאינם קיימים בזבח.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אמור כי \u0003זבח נמי\u0004 \u0005[גם כן]\u0006 שהוזכר בברייתא \u0003שם זבח,\u0004 שאין הכוונה לזבח מסויים אחד אלא למושג הזבח בכללו, טענה זו דוחים: \u0003שם זבח לא קתני\u0004 \u0005[שונה],\u0006 שודאי אין ברייתא זו מדברת על זבח כמהות כוללת לגבי כל הקרבנות,","\u0003ממאי\u0004 \u0005[ממה]\u0006 יודע אתה שכך הוא — \u0003מדקתני\u0004 \u0005[ממה ששנינו]:\u0006 \u0003חומר בתמורה — שהתמורה חלה על בעל מום קבוע, ואינה יוצאה לחולין ליגזז וליעבד\u0004 מה שאין כן בזבח. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה בדעתך]\u0006 לומר כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003זבח — שם זבח,\u0004 מושג הזבח בכללותו, \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 דוגמה לזבחים שגם בהם קיים דין זה,"],["\u0003בכור ומעשר\u0004 ש\u0003חלין\u0004 קדושתן גם \u0003על בעל מום קבוע, ואין יוצאין לחולין ליגזז וליעבד. אלא\u0004 על כרחך \u0003שם זבח לא קתני\u0004 \u0005[שנה]\u0006 וכשהוא אומר זבח, כוונתו לזבח מסויים אחד.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]?\u0006 כלומר: מדוע בדבר אחד מתכוון התנא לקרבן מיוחד ובדבר שני הריהו מדבר על מושג כללי? \u0003תמורה — שם תמורה אחת היא\u0004 שמושג התמורה אחד הוא, ואין הבדל איפוא בין תמורה לתמורה. ואילו \u0003בזבח איכא\u0004 \u0005[יש]\u0006 \u0003בכור ואיכא\u0004 \u0005[ויש]\u0006 \u0003מעשר,\u0004 שדיניהם שונים משאר זבחים, ולכן אין לקבוע בהם כלל אחד ולכן ודאי היתה הכוונה לזבח מסויים.","בהמשך למשא והמתן הקודם שואלים: ולדעת \u0003רב ששת,\u0004 שמפרש שזבח זה אינו פר כהן גדול אלא הכוונה לאילו של אהרן, \u0003אדמוקים לה\u0004 \u0005[עד שהוא מעמיד,\u0006 מפרש, את הברייתא הזו\u0005]\u0006 \u0003באילו של אהרן, לוקמה\u0004 \u0005[שיעמיד,\u0006 שיסביר\u0005]\u0006 שמדובר כאן בקרבן ה\u0003פסח,\u0004 ש\u0003דוחה את השבת ואת הטומאה ועושה תמורה,\u0004 ש\u0003קרבן יחיד הוא\u0004 לכל הדיעות? ומשיבים: \u0003קסבר\u0004 \u0005[סבר]\u0006 רב ששת \u0003אין שוחטין הפסח על היחיד,\u0004 אלא נשחט רק בחבורה, ולכן קרבן הפסח לעולם אינו קרבן יחיד, אלא לפחות קרבן השותפין, ולכן אינו עושה תמורה.","ושואלים: \u0003ונוקמיה\u0004 \u0005[ושנעמיד אותו]\u0006 \u0003בפסח שני,\u0004 שנשחט על ידי יחיד! ומשיבים; \u0003מי דחי\u0004 \u0005[האם\u0006 פסח שני \u0005דוחה]\u0006 את ה\u0003טומאה?\u0004 וכיון שכך, אי אפשר לפרש שמדובר בקרבן זה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבא: ותנא\u0004 זה שהבאנו אותו קודם, \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 קרבן ה\u0003פסח דקרי ליה\u0004 \u0005[שהוא קורא לו]\u0006 \u0003קרבן יחיד, ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 קרבן \u0003חגיגה\u0004 הבאה עם הפסח \u0003דקרי\u0004 \u0005[שהוא קורא]\u0006 \u0003לה קרבן ציבור? אי\u0004 \u0005[אם]\u0006 \u0003משום דאתי בכנופיא\u0004 \u0005[שהיא באה בחבורה],\u0006 שכל העם מביאין אותה — קרבן \u0003פסח נמי אתי בכנופיא\u0004 \u0005[בא גם כן בחבורה]\u0006 ולא כקרבנו של יחיד לעצמו? ענה לו: \u0003איכא\u0004 \u0005[יש]\u0006 \u0003פסח שני\u0004 ש\u0003לא אתי בכנופיא\u0004 \u0005[בא בחבורה]\u0006 ולכן לא ראה את הפסח כדוגמה.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם כן\u0004 שדינו כקרבן ציבור \u0003יהא\u0004 פסח שני \u0003דוחה את השבת ואת הטומאה! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 אפשר לומר; \u0003כמאן דאמר דחי\u0004 \u0005[\u0006כשיטת \u0005מי שאומר שדוחה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003פסח שני דוחה את השבת,\u0004 אבל \u0003אינו דוחה את הטומאה. ר' יהודה אומר: אף דוחה את הטומאה.\u0004 ומסבירים: \u0003מאי טעמא דתנא קמא\u0004 \u0005[מה טעמו של התנא הראשון] —\u0006 \u0003אמר\u0004 (יכול היה לומר) \u0003לך\u0004 הלא כל עניינו של המקריב פסח שני שהרי אדם זה הבא להקריב פסח שני \u0003מפני טומאה דחיתו\u0004 שהרי בגלל הטומאה לא יכול היה להקריב פסח ראשון ועכשיו \u0003יעשה בטומאה?!\u0004","\u0003ור' יהודה אמר לך\u0004 (יכול היה לומר לך), משום כך \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפסח שני: \u0003\"ככל חקת הפסח יעשו אתו\"\u0004 (במדבר ט, יב), משמע: ככל חוקת הפסח \u0003ואפילו\u0004 שיבוא \u0003בטומאה\u0004 כפסח ראשון. ולגבי הטענה של התנא הראשון אפשר לענות: \u0003התורה החזירה עליו\u0004 כלומר חיפשה הזדמנות לאותו אדם שנטמא בפסח ראשון \u0003לעשותו בטהרה, לא זכה\u0004 לעשותו בטהרה — \u0003יעשנו\u0004 על כל פנים, ואפילו \u0003בטומאה.\u0004"],["וחוזרים לשאלתו של ר' אלעזר, אם הכהן הגדול יכול לעשות תמורה בפרו. ורוצים להוכיח כי אחיו הכהנים לא היו שותפים גמורים בקרבן זה, אלא בדרך אגב היו מתכפרים. \u0003ותיפוק\u0004 \u0005[ותצא]\u0006 \u0003לי\u0004 תשובה לבעיה זו מ\u0003\"\u0004והקריב אהרן את פר החטאת \u0003אשר לו\"\u0004 (ויקרא טז, יא), שהרי מכאן ברור כי \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]:\u0006 \u0003משלו הוא מביא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"אשר לו\"\u0004 כוונתו: \u0003משלו הוא מביא, ולא משל ציבור. יכול לא יביא\u0004 קרבן זה \u0003משל ציבור\u0004 לפי \u0003שאין הציבור\u0004 כולו \u0003מתכפרין בו, אבל יביא משל אחיו הכהנים, שהרי אחיו הכהנים מתכפרים בו — תלמוד לומר: \"אשר לו\"\u0004 — ולא של אחר.","\u0003יכול לא יביא\u0004 משל כהנים, \u0003ואם הביא\u0004 בכל זאת, \u0003כשר — תלמוד לומר שוב: \"\u0004ושחט את פר החטאת \u0003אשר לו\"\u0004 (ויקרא טז, יא) — \u0003שנה הכתוב עליו\u0004 בהדגשה זו \u0003לעכב,\u0004 שאם הביאו משל ציבור פסול.","את ההוכחה הזו דוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 הלא \u0003אחיו הכהנים אי לאו דקנו בגויה\u0004 \u0005[שיש להם קנין בו]\u0006 \u0003היכי מכפר להו\u0004 \u0005[כיצד מתכפר להם]?\u0006 וכיון שהם מתכפרים בו, משמע שיש להם צד קנין בו. אלא על כרחך יש לומר כי \u0003שאני בי גזא\u0004 \u0005[שונה אוצרו,\u0006 רכושו\u0005]\u0006, של \u0003אהרן\u0004 הכהן הגדול \u0003דאפקריה רחמנא\u0004 \u0005[שהפקירתו התורה]\u0006 \u0003לגבי אחיו הכהנים\u0004 לענין זה, שאף שהוא מביא משלו, מכל מקום נחשב כמקדישו עבור כל הכהנים. ואם כן \u0003הכא גבי תמורה נמי\u0004 \u0005[כאן לגבי התמורה גם כן]\u0006 יכולים אנו לומר: \u0003שאני בי גזא\u0004 \u0005[שונה אוצרו]\u0006 של \u0003אהרן דאפקריה רחמנא\u0004 \u0005[שהפקירתו התורה]\u0006 \u0003לגבי אחיו הכהנים,\u0004 ואין איפוא להוכיח מכאן.","\u0003היה הכהן הגדול מהלך בהיכל\u0004 לכיוון מערב \u0003עד שמגיע לבין שתי הפרוכת המבדילות בין הקדש ובין קדש הקדשים, וביניהן\u0004 היה ריוח של \u0003אמה\u0004 אחת. \u0003ר' יוסי אומר: לא היתה שם אלא פרוכת אחת בלבד, שנאמר: \"והבדילה הפרכת לכם בין הקדש ובין קדש הקדשים\"\u0004 (שמות כו, לג).","שואלים: \u0003שפיר קאמר להו\u0004 \u0005[יפה אמר להם]\u0006 \u0003ר' יוסי לרבנן\u0004 \u0005[לחכמים],\u0006 והלא מפורש בכתוב כדבריו! \u0003ורבנן אמרי\u0004 \u0005[וחכמים אומרים,\u0006 יכולים היו לומר\u0005]\u0006 \u0003לך: הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003במשכן\u0004 שהיתה בו פרוכת אחת, \u0003אבל במקדש שני כיון\u0004 ש\u0003לא הואי\u0004 \u0005[היתה]\u0006 בו \u0003אמה טרקסין,\u0004 שהיה קיר שעוביו אמה מפסיק בין הקודש וקודש הקדשים, ורק \u0003במקדש ראשון הוא דהואי\u0004 \u0005[שהיתה]\u0006 \u0003ואיסתפקא להו לרבנן בקדושתיה\u0004 \u0005[ונסתפק להם לחכמים בקדושתו]\u0006 של מקום קיר זה \u0003אי\u0004 \u0005[אם]\u0006 קדושתו \u0003כלפנים\u0004 כקודש הקדשים, \u0003אי\u0004 \u0005[אם]\u0006 קדושתו \u0003כלחוץ\u0004 כמו ההיכל, ומשום כך \u0003עבוד\u0004 \u0005[עשו]\u0006 \u0003שתי פרוכות\u0004 שתסגורנה את השטח המסופק הזה, שיהיה בפני עצמו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 כשהיה היה הכהן הגדול הולך בדרכו לקודש הקדשים — בצד דרום \u0003בין המזבח\u0004 הפנימי \u0003למנורה היה מהלך.\u0004 אלו \u0003דברי ר' יהודה. ר' מאיר אומר בין שלחן למזבח\u0004 בצד צפון היה מהלך. \u0003ויש אומרים: בין שלחן לכותל.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 בעל הדעה המכונה \u0003\"יש אומרים\"? אמר רב חסדא:\u0004 שיטת \u0003ר' יוסי\u0004 במשנתנו \u0003היא,\u0004 שלדעתו יש רק פרוכת אחת וכדעת הכל \u0003אמר\u0004 אף הוא הכניסה לקודש הקדשים צריכה להיות בצד צפון ומכיון שלא היתה לדעתו אלא פרוכת אחת, לכך ודאי כי \u0003פיתחא\u0004 \u0005[הפתח]\u0006 שלה \u0003בצפון קאי\u0004 \u0005[\u0006היה \u0005עומד]\u0006 ולכן הלך הכהן במישרין כלפי פתח זה, סמוך לצידו הצפוני של ההיכל.","\u0003ור' יהודה\u0004 סובר כי היו שתי פרוכות ולכן \u0003אמר לך\u0004 כי אף שהכניסה לקודש הקדשים צריכה בפועל להיות דרך צד צפון, מכל מקום כיון שהיו שתי פרוכות, זו לפנים מזו, לכך ודאי \u0003פיתחא\u0004 \u0005[הפתח]\u0006 של הפרוכת בתחילת כניסתו מצד \u0003דרום קאי\u0004 \u0005[\u0006היה \u0005עומד]\u0006 ורק לאחר מכן היה הולך בין הפרוכות ומגיע לצפון הפרוכת הפנימית ושם היתה כניסתו\u0005.\u0006 ושואלים: אם כן, \u0003ר' מאיר כמאן סבירא ליה\u0004 \u0005[\u0006כשיטת \u0005מי סבור הוא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יהודה סבירא ליה\u0004 \u0005[סבור הוא]\u0006 לענין הפתח — אם כן \u0003ניעול\u0004 \u0005[שיכנס\u0006 ויאמר\u0005]\u0006 כדברי \u0003ר' יהודה, אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יוסי סבירא ליה\u0004 \u0005[סבור הוא] —\u0006 \u0003ניעול\u0004 \u0005[שיכנס\u0006 ויאמר\u0005]\u0006 כדעת \u0003ר' יוסי!\u0004","ומשיבים: \u0003לעולם\u0004 תפרש שכדעת \u0003ר' יוסי סבירא ליה\u0004 \u0005[סבור הוא]\u0006 \u0003ואמר\u0004 (יכול היה לומר) \u0003לך: שולחנות\u0004 שולחן לחם הפנים והשולחנות שלידו, בצד \u0003צפון ודרום מונחין ומפסקא ליה\u0004 \u0005[\u0006והיה \u0005מפסיק לו]\u0006 ה\u0003שלחן\u0004 בצד צפון \u0003ולא מתעייל ליה\u0004 \u0005[יכול להיכנס בו\u0006 במישרין\u0005]\u0006 שהמקום דחוק מידי.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 תפרש כי בצד \u0003מזרח ומערב\u0004 היו \u0003מונחין\u0004 השולחנות, \u0003ומשום\u0004 כבוד ה\u0003שכינה לאו אורח ארעא\u0004 \u0005[אינו דרך ארץ]\u0006"],["\u0003למיעל להדיא\u0004 \u0005[להיכנס במישרין]\u0006 וראוי לכהן להקיף קצת, דרך כבוד. \u0003ור' יוסי אמר לך\u0004 כנגד טענה זו: \u0003חביבין ישראל\u0004 לפני המקום \u0003שלא הצריכן הכתוב לשליח\u0004 כגון מלאך וכיוצא בו, אלא הקדוש ברוך הוא עצמו שומע תפילת ישראל, ולכן חביב הכהן הגדול שליח ישראל שאינו צריך ללכת בדרך עקיפין.","ושואלים: ואם עקיפין הוא דרך כבוד, הרי לשיטת \u0003ר' יהודה נמי\u0004 \u0005[גם כן]\u0006 \u0003ניעול\u0004 \u0005[שיכנס]\u0006 הכהן הגדול בעקיפין, \u0003בין\u0004 ה\u0003מנורה לכותל!\u0004 ומשיבים: אם יעבור הכהן הגדול שם, יתכן כי \u0003משחרי מאניה\u0004 \u0005[יושחרו בגדיו],\u0006 מהשחרורית הדבוקה לכותל מעשן המנורה.","\u0003אמר ר' נתן: אמה טרקסין לא הכריעו בו חכמים\u0004 מה דינו מבחינת הקדושה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003כלפנים\u0004 כקודש הקדשים \u0003אי\u0004 \u0005[אם]\u0006 \u0003כלחוץ\u0004 כהיכל.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: מאי טעמא\u0004 \u0005[מה טעם]\u0006 הקושי שהיה בדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והבית אשר בנה המלך שלמה לה' ששים אמה ארכו ועשרים רחבו ושלשים אמה קומתו\"\u0004 (מלכים א' ו, ב) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וארבעים באמה היה הבית הוא ההיכל לפני\"\u0004 (מלכים א' ו, יז), ונאמר: \u0003\"ולפני הדביר עשרים אמה ארך ועשרים אמה רחב ועשרים אמה קומתו\"\u0004 (מלכים א' ו, כ) ומשום כך \u0003לא ידעינן\u0004 \u0005[אין אנו יודעים]\u0006 ב\u0003אמה טרקסין\u0004 זו \u0003אי מהני\u0004 \u0005[אם מאלו]\u0006 \u0003עשרים\u0004 אמה של קודש הקדשים (\"הדביר\"), \u0003ואי מהני\u0004 \u0005[אם מאלו]\u0006 \u0003ארבעים\u0004 אמה שנמנו בתוך מידת הקודש (\"ההיכל\").","אולם, הרי אפשר לפתור בפשטות: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 אינו \u0003לא מהני\u0004 \u0005[מאלה]\u0006 ה\u0003עשרין\u0004 אמה \u0003ולא מהני\u0004 \u0005[מאלה]\u0006 ה\u0003ארבעין\u0004 אמה, \u0003וחללא קא חשיב\u0004 \u0005[את החלל הוא מחשיב],\u0006 אבל את ה\u0003כותלים\u0004 עצמם \u0003לא קא חשיב\u0004 \u0005[אין הוא מחשיב]\u0006 בקביעת המידות, ואמה זו של כותל אינה נחשבת כלל בין המידות. \u0003תדע\u0004 שכן הוא, \u0003דכל היכא דקא חשיב\u0004 \u0005[שבכל מקום שמחשיב]\u0006 את ה\u0003כותלים\u0004 ולא רק את השטח בפנים \u0003חשיב ליה לדידיה\u0004 \u0005[מונה גם אותה,\u0006 את האמה טרקסין\u0005],\u0006","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ההיכל מאה\u0004 אמה \u0003על מאה\u0004 אמה \u0003ברום\u0004 \u0005[בגובה]\u0006 \u0003מאה;\u0004 וכך היה מתחלק ממזרח למערב: \u0003כותל אולם חמש\u0004 אמות, \u0003והאולם\u0004 עצמו \u0003אחת עשרה\u0004 אמות, \u0003כותל ההיכל שש\u0004 אמות, \u0003וארכו ארבעים אמה, ואמה טרקסין,\u0004 ועוד \u0003עשרים אמה בית קדשי הקדשים, כותל ההיכל\u0004 החיצוני \u0003שש, והתא\u0004 מאחוריו \u0003שש, וכותל התא חמש\u0004 אמות.","משמע שכאשר מונים גם הכתלים ולא רק החללים מונים גם אמה טרקסין! אלא, השאלה לא היתה בדבר מקומה של אמה טרקסין שהיא ודאי בין הקודש וקודש הקדשים \u0003אלא\u0004 על \u0003קדושתיה\u0004 \u0005[קדושתו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 הוא \u0003כלפנים\u0004 כקודש הקדשים או \u0003כלחוץ\u0004 לו, וכיון שבבית שני לא היה שם כותל בנוי, לא ידעו לאן לשייך את האמה היתירה הזו.","\u0003והיינו דאמר\u0004 \u0005[והוא שאמר]\u0006 \u0003ר' יוחנן, בעי\u0004 \u0005[שאל]\u0006 \u0003יוסף איש הוצל:\u0004 נאמר: \u0003\"ודביר בתוך הבית מפנימה הכין לתתן שם את ארון ברית ה'\"\u0004 (מלכים א' ו, יט). \u0003איבעיא להו\u0004 \u0005[\u0006כך \u0005נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003היכי קאמר קרא\u0004 \u0005[כיצד\u0006 בדיוק \u0005אמר הכתוב]\u0006 וכיצד משמעות דברי הפסוק; האם יש לקוראו ולהבינו כך:","\u0003\"ודביר בתוך הבית מפנימה הכין לתתן שם\",\u0004 שעשה מחיצה המפסקת בתוך הבית (\"ודביר בתוך הבית\"), ולפנים מאותה מחיצה הכין חלל למשכן ארון הקודש (\"מפנימה הכין לתתן שם\"), וממילא הדביר עצמו אינו קדוש בקדושת קודש הקדשים, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003\"ודביר בתוך הבית מפנימה\"\u0004 וכאן יש להפסיק, ולקרוא את המשך הפסוק כיחידה אחרת, ומשמעות הפסוק באופן כזה היא שמקום הדביר עצמו היה חלק מקודש הקדשים ואותו הכין למקום משכן לארון.","על ההסבר הזה תוהים: \u0003ומי מספקא ליה\u0004 \u0005[והאם מסופק לו]\u0006 כיצד יש להפסיק במקרא זה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003איסי בן יהודה אומר: חמש מקראות בתורה אין להן הכרע,\u0004 שלא ברור מן המקרא היכן יש להפסיק בתוך הפסוקים:"],["\u0003\"שאת\"\u0004 (בראשית ד, ז), כלומר: אם יש לך לקרוא כך: \"הלא אם תיטיב שאת\" ו\"שאת\" במובן זה היא לשון סליחה ומחילה, כלומר: ימחל לך, או: \"הלא אם תיטיב, שאת ואם לא תיטיב\" ו\"שאת\" במובן זה הוא לשון זכירה, כלומר: שאם לא תיטיב יזכר לך העוון.","וכן המילה \u0003\"משוקדים\"\u0004 (שמות כה, לד), האם יש לקרוא: \"ובמנורה ארבעה גביעים משוקדים\", או שמא יש לקרוא: \"משוקדים כפתוריה ופרחיה\".","וכן המילה \u0003\"מחר\"\u0004 (שמות יז, ט), האם יש לקרוא: \"וצא הלחם בעמלק מחר\", או שהכוונה היא שעליו לצאת למלחמה מיידית בעמלק ו\"מחר אנוכי ניצב על ראש הגבעה\", אבל היום אינך צריך לתפילתי.","וכן המילה \u0003\"ארור\"\u0004 (בראשית מט, ז), האם לקוראה: \"ארור אפם כי עז ועברתם כי קשתה\", או: \"וברצונם עקרו שור ארור\" (בראשית מט, ו-ז) ו\"שור ארור\" הכוונה לשור של שכם הבא מ\"ארור כנען\", \"או בשל מה שעשו שמעון ולוי לשכם שבשל כך נאמר עליהם \"ארור אפם כי עז\", וכן המילה","\u0003\"וקם\"\u0004 (דברים לא, טז) האם לקרוא: \"הנך שוכב עם אבותיך וקם\" בתחיית המתים, או: \"וקם העם הזה וזנה\".","\u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003הוא יוסף איש הוצל,\u0004 (הוצל היא עיר בבבל), \u0003הוא יוסף הבבלי, הוא\u0004 הקרוי \u0003איסי בן יהודה\u0004 (כי איסי הוא קיצור של יוסף), \u0003הוא איסי בן גור אריה\u0004 (שהוא כינוי ליהודה) \u0003הוא איסי בן גמליאל, הוא איסי בן מהללאל, ומה שמו\u0004 האמיתי שנקרא בו מתחילה — \u0003איסי בן עקיבא שמו.\u0004 ואם כן, הרי איסי בן יהודה שהוא יוסף איש הוצל אומר שיש רק חמישה מקראות שאין הפסקם ברור, וכאן מוסיף הוא מקרא נוסף? ומשיבים: \u0003בדאורייתא\u0004 \u0005[בתורה]\u0006 עצמה \u0005—\u0006 \u0003ליכא\u0004 \u0005[אין]\u0006 אכן יותר מחמישה פסוקים, אבל \u0003בדנביאי\u0004 \u0005[בנביאים] —\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 וזה אחד מהם.","ומקשים: \u0003ובדאורייתא ליכא\u0004 \u0005[ובתורה\u0006 עצמה האם \u0005אין]\u0006 יותר? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 בעיה זאת \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רב חסדא\u0004 בכתוב: \u0003\"וישלח את נערי בני ישראל ויעלו עלת ויזבחו זבחים שלמים לה' פרים\"\u0004 (שמות כד, ה), האם יש לפרש \"ויעלו עולות\", והכוונה היא — כבשים, וגם: \"ויזבחו זבחים שלמים לה'\" — פרים, שהשלמים היו רק פרים, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003אידי ואידי\u0004 \u0005[אלה ואלה]\u0006 \u0003פרים,\u0004 ויש לקרוא: \"ויעלו עולות כבשים ויזבחו זבחים שלמים\" וגם \"לה' פרים\" עולות ושלמים. ואם כן יש פסוק נוסף שלא ידוע היכן מפסיקים בו! ודוחים: זו אינה קושיה, אכן \u0003לרב חסדא מספקא ליה\u0004 \u0005[מסופק לו]\u0006 ואינו יודע היכן יש להפסיק, אולם \u0003לאיסי בן יהודה פשיטא ליה\u0004 \u0005[פשוט\u0006 היה \u0005לו]\u0006 היכן יש להפסיק וכיצד משמעותו של פסוק זה, ובו לא התקשה.","פרוכת \u0003החיצונה\u0004 של קודש הקדשים \u0003היתה פרופה\u0004 (פתוחה קצת על ידי פריפות = קרסים) \u0003מן הדרום,\u0004 ופרוכת ה\u0003פנימית\u0004 היתה פתוחה \u0003מן הצפון,\u0004 ולכן לא היה יכול ללכת ולהכנס לקודש הקדשים במישרין, אלא \u0003מהלך ביניהן,\u0004 בין הפרוכות, כשהוא נכנס בפריפת צד דרום והולך \u0003עד שמגיע לצפון, הגיע\u0004 לפריפת צד \u0003צפון\u0004 — נכנס לקודש הקדשים \u0003הופך פניו לדרום מהלך לשמאלו עם הפרוכת\u0004 בצמוד לה \u0003עד שהוא מגיע\u0004 מול \u0003לארון,\u0004","\u0003הגיע לארון — נותן את המחתה בין שני הבדים. צבר את הקטרת על גבי\u0004 ה\u0003גחלים, ונתמלא כל הבית כולו עשן. יצא ובא לו בדרך בית כניסתו\u0004 כלומר לא היה הופך פניו אלא צועד אחורנית כשפניו כלפי הארון וכשם שנכנס כך יוצא, \u0003ומתפלל תפלה קצרה בבית החיצון\u0004 (בהיכל). \u0003ולא היה מאריך בתפלתו\u0004 שם, כדי \u0003שלא להבעית את ישראל\u0004 שיחשבו שמא אירע בו דבר ומת בהיותו בקודש הקדשים.","שואלים: \u0003במאי עסקינן\u0004 \u0005[במה עוסקים אנו]\u0006 כאן; באיזו תקופה אנו מדברים? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 \u0003במקדש ראשון,\u0004 אולם אז \u0003מי הוו פרוכת\u0004 \u0005[האם היו פרוכות]?\u0006 הלא שמה היתה רק פרוכת אחת בתוך כותל אמה טרקסין. \u0003אלא\u0004 תאמר \u0003במקדש שני\u0004 אם כן \u0003מי הוה\u0004 \u0005[האם היה]\u0006 אז \u0003ארון?\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003משנגנז\u0004 ה\u0003ארון נגנזה עמו צנצנת המן\u0004 שהיתה בצידו \u0003וצלוחית שמן המשחה, ומקלו של אהרן ושקדיה ופרחיה, וארגז ששגרו פלשתים דורון לאלהי ישראל\u0004 לאחר ששבו את הארון וניגפו בכמה מגיפות, \u0003שנאמר: \"וכלי הזהב אשר השבתם לו אשם תשימו בארגז מצדו ושלחתם אתו והלך\"\u0004 (שמואל א' ו, ח).","\u0003ומי גנזו\u0004 את הארון — \u0003יאשיהו\u0004 מלך יהודה \u0003גנזו. ומה ראה שגנזו — ראה שכתוב: \"יולך ה' אתך ואת מלכך אשר תקים עליך\u0004 אל גוי אשר לא ידעת\u0003\"\u0004 (דברים כח, לו) וכיון שידע שסוף ישראל לגלות, אמר: מוטב שלא יתבזה הארון בגלות ולכן \u0003עמד וגנזו,\u0004","\u0003שנאמר: \"ויאמר ללוים המבינים לכל ישראל הקדושים לה' תנו את ארון הקדש בבית אשר בנה שלמה בן דויד מלך ישראל אין לכם משא בכתף עתה עבדו את ה' אלהיכם ואת עמו ישראל\"\u0004 (דברי הימים ב' לה, ג), כלומר: מעתה שוב אין על הלוים עבודת משא הארון בכתף, ועליהם לעסוק בעבודת השירה ונעילת השערים.","\u0003ואמר ר' אלעזר: אתיא\u0004 \u0005[בא,\u0006 נלמד הדבר\u0005]\u0006 בגזירה שוה שנאמר בארון: \u0003\"\u0004אשר על ארון העדות לפני הכפורת אשר על העדות אשר אועד לך \u0003שמה\"\u0004 (שמות ל, ו). ונאמר: \"קח צנצנת אחת ותן \u0003שמה\u0004 מלוא העומר מן והנח אותו לפני ה' למשמרת לדורותיכם\" (שמות טז, לג) \u0003ואתיא\u0004 \u0005[ונלמד]\u0006 בגזירה שוה \u0003\"דרת\"\u0004 הכתוב כאן מ\u0003\"דרת\"\u0004 שנאמר בשמן המשחה בכתוב: \"שמן משחת קודש יהיה זה לי לדורותיכם\" (שמות ל, לא)","\u0003ואתיא\u0004 \u0005[ונלמד]\u0006 בגזירה שוה \u0003\"משמרת\"\u0004 האמור כאן מ\u0003\"משמרת\"\u0004 האמור במקלו של אהרן, ככתוב: \"השב את מטה אהרן לפני העדות למשמרת\" (במדבר יז, כה), ללמד שלא רק הארון אלא גם אלה יגנזו עמו. ואם כן, עוד בסוף ימי הבית הראשון לא היה ארון בבית קודש הקדשים, וכיצד מדובר פה על ארון בבית שני?","ומשיבים: \u0003לעולם\u0004 מדובר פה \u0003במקדש שני, ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005],\u0006 \u0003הגיע לארון\u0004 שנאמר כאן — כוונתו ל\u0003מקום ארון.\u0004 ומקשים: \u0003והא קתני\u0004 \u0005[והרי שנינו]:\u0006 \u0003נתן את המחתה לבין שני הבדים,\u0004 משמע שהיו בדי הארון! ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003\"כבין שני הבדים\",\u0004 כלומר: במקום שהיו הבדים מצויים בשעה שהיה הארון.","שנינו במשנה: \u0003צבר את הקטרת על גבי גחלים.\u0004 ומעירים: \u0003תנן כמאן דאמר\u0004 \u0005[שנינו\u0006 במשנתנו זו \u0005כשיטת מי שאמר]\u0006 שהקטורת \u0003צוברה\u0004 על הגחלים ואינו מפזרה שם. \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003צוברה\u0004 את הקטורת בתוך המחתה \u0003פנימה\u0004 לצד הארון \u0003שהיא חוצה לו\u0004 לכהן, עד שמגיע לצידה השני של המחתה. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003צוברה חוצה\u0004 לארון \u0003שהיא פנימה לו\u0004 לעברו של הכהן.","\u0003אמר אביי תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בענין זה. \u0003ואמר אביי: מסתברא כמאן דאמר\u0004 \u0005[מסתבר כשיטת מי שאמר]\u0006 \u0003פנימה\u0004 לארון \u0003שהיא חוצה לו\u0004 לכהן. ומדוע — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 כי \u0003מלמדין אותו\u0004 את הכהן המקטיר קטורת: \u0003הזהר\u0004"],["\u0003שלא תתחיל\u0004 לצבור את הקטורת \u0003מפניך,\u0004 מן הצד הקרוב אליך, \u0003שמא תכוה.\u0004 כי אם מתחיל להניח את הקטורת בצד שלפניו וצריך להמשיך ולפזרה הלאה כלפי פנים, אל הארון, הרי ידיו עוברות במקום שבו כבר יש קטורת בוערת וקיים חשש שיכווה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: נאמר: \u0003\"ונתן את הקטרת על האש לפני ה'\"\u0004 (ויקרא טז, יג) — להדגיש: \u0003שלא יתקן,\u0004 כלומר: שלא יניח את הקטורת \u0003מבחוץ\u0004 בהיכל \u0003ויכניס\u0004 את המחתה עם הקטורת הבוערת לקודש הקדשים. ובאה הדגשה זו \u0003להוציא מלבן\u0004 (מדעתם) \u0003של צדוקים, שאומרים\u0004 שההלכה היא ש\u0003יתקן מבחוץ\u0004 ורק אחר כך \u0003יכניס.\u0004","ושואלים: \u0003מאי דרוש\u0004 \u0005[מה דרשו]\u0006 הצדוקים? מהיכן הביאו ראיה לדבריהם? — כך אמרו: נאמר: \u0003\"כי בענן אראה על הכפרת\"\u0004 (ויקרא טז, ב) ולדעתם הפסוק \u0003מלמד שיתקן מבחוץ\u0004 שיהא כבר ענן קטורת, ורק לאחר מכן \u0003יכניס\u0004 פנימה.","\u0003אמרו להם חכמים: והלא כבר נאמר\u0004 במפורש: \u0003\"ונתן את הקטרת על האש לפני ה'\"\u0004 (ויקרא טז, יג) משמע שבעמדו לפני ה', בקודש הקדשים, רק אז יתן את הקטורת. \u0003אם כן מה תלמוד לומר: \"כי בענן אראה על הכפרת\"\u0004 (ויקרא טז, ב) — אין הכוונה שכבר יהיה ענן קטורת טרם כניסתו, אלא בא הכתוב להדגיש על צורת עשן הקטורת והריהו","\u0003מלמד שנותן בה,\u0004 כלומר: בין שאר סממניה \u0003מעלה עשן\u0004 שהוא מין צמח הגורם לעשן לעלות זקוף כמקל. \u0003ומניין שנותן בה מעלה עשן? שנאמר: \"וכסה ענן הקטרת את הכפרת\"\u0004 (ויקרא טז, יג). \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא נתן בה מעלה עשן, או שחיסר אחת מכל סמניה\u0004 הכתובים בה — \u0003חייב מיתה.\u0004 על ההלכה האחרונה תוהים: מדוע צריך לומר שחייב מיתה אם חסר אחד מכל סממניה?","\u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 שהוא חייב מיתה מטעם אחר — \u0003דקא מעייל\u0004 \u0005[שהוא נכנס]\u0006 \u0003ביאה ריקנית,\u0004 שהרי אסור להכנס לקודש הקדשים, אלא לצורך מצוה, ואם הקטורת חסירה הרי שאינו עושה מצוה, אלא נכנס ללא צורך לקודש הקדשים, וחייב מיתה על ביאתו לשם, גם ללא הקטרה!","\u0003אמר רב ששת: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 \u0003כגון ששגג בביאה\u0004 ריקנית, שלא ידע שהבא לקודש הקודשים שלא לצורך חייב, או שלא התכוון לבוא כלל אל קודש הקדשים, \u0003והזיד בהקטרה\u0004 שידע שהמקטיר קטורת חסירה חייב מיתה, ולכן אינו חייב אלא על הקטרתו קטורת חסירה.","\u0003רב אשי אמר\u0004 הסבר אחר: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 \u0003שהזיד בזו ובזו\u0004 שהקטרת הקטורת החסירה וביאתו אל הקודש היו מתוך ידיעה ברורה והכרת חומרת האיסור, ו\u0003כגון דעייל\u0004 \u0005[שהכניס\u0006 איתו\u0005]\u0006 באותה ביאה לקודש הקדשים \u0003שתי הקטרות, אחת שלימה\u0004 שיש בה כל הסממנים \u0003ואחת חסירה\u0004 והקטיר את שתיהן. ואז, על עצם ה\u0003ביאה\u0004 לקודש הקדשים \u0003לא מיחייב\u0004 \u0005[מתחייב],\u0006 \u0003דהא עייל ליה\u0004 \u0005[שהרי הכניס לו,\u0006 לתוכו\u0005]\u0006 קטורת \u0003שלימה\u0004 ונמצא שקיים מצוה, אולם על ה\u0003הקטרה\u0004 של החסירה — הריהו \u0003מיחייב\u0004 \u0005[חייב],\u0006 \u0003דקא מקטר\u0004 \u0005[שהרי הוא מקטיר]\u0006 \u0003קטורת חסירה.\u0004","כיון שהוזכרה ברייתא זו, מבררים את הדברים שנאמרו בה. \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003ומניין שנותן בה\u0004 בקטורת בין שאר סממניה גם \u0003מעלה עשן — תלמוד לומר: \"וכסה\u0004 ענן הקטורת\u0003\".\u0004 ותוהים: \u0003קרא לקרא\u0004 \u0005[כתוב לכתוב]?\u0006 שהרי כבר הוכיח מן המקרא שנאמר: \"כי בענן אראה על הכפורת\", שצריך להביא מעלה עשן, ומה טעם להביא מקרא אחר לסייע למקרא ראשון?","\u0003אמר רב יוסף: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את הדברים: \u0003אין לי אלא\u0004 שמביא את \u0003עלה\u0004 הצמח \u0003מעלה עשן,\u0004 אבל את \u0003עיקר\u0004 (שורשו) של הצמח \u0003מעלה עשן מניין\u0004 שצריך להביא? \u0003תלמוד לומר: \"וכסה\"\u0004 ללמדנו שיש לדאוג לתוספת מעלה עשן.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: מדבריך משמע כי העלה טוב מן השורש, \u0003והא איפכא תניא\u0004 \u0005[והרי היפך\u0006 מזה \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נתן בה\u0004 בקטורת \u0003עיקר\u0004 (שורש) \u0003מעלה עשן,\u0004 ו\u0003היה\u0004 העשן \u0003מתמר ועולה כמקל עד שמגיע לשמי קורה\u0004 (לתקרת הבית) \u0003כיון שהגיע לשמי קורה,\u0004 ומתוך שאיננו יכול לצאת החוצה, הריהו \u0003ממשמש ויורד בכותלים\u0004 מעט מעט \u0003עד שנתמלא הבית\u0004 כולו \u0003עשן, שנאמר: \"והבית ימלא עשן\"\u0004 (ישעיה ו, ד), הרי משמע כי עיקר מעלה עשן טוב מן העלה!","\u0003אלא\u0004 יש לחזור מן הפירוש הראשון ו\u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אין לי אלא\u0004 שמכניס בו \u0003עיקר מעלה עשן, עלה מעלה עשן מניין\u0004 שמוסיפים בו? \u0003תלמוד לומר: \"וכסה\u0004 ענן הקטורת\".","\u0003רב ששת אמר\u0004 כך יש לפרש את שני הפסוקים; \u0003אין לי\u0004 שחייב לכלול בין סממני הקטורת גם מעלה עשן \u0003אלא\u0004 ב\u0003אהל מועד שבמדבר,\u0004 שחובה זו קיימת גם במשכן \u0003שילה ובית עולמים מניין? תלמוד לומר: \"וכסה\"\u0004 שבכל מקום שנכנס לקודש להקטיר מכניס גם מעלה עשן.","ותוהים: \u0003האי\u0004 \u0005[\u0006לימוד \u0005זה]\u0006 אין צורך בו, שהרי מ\u0003\"וכן יעשה לאהל מועד השכן אתם\"\u0004 (ויקרא טז, טז) \u0003נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005],\u0006 שהכתוב מלמדנו שדבר זה אינו נעשה רק בפעם ראשונה במדבר, אלא חייב להיעשות בכל מקום השראת השכינה!","\u0003אלא הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אין לי\u0004 חובה זו לכלול בין הסממנים גם מעלה עשן \u0003אלא\u0004 בקטורת הבאה \u0003ביום הכפורים\u0004 ומוקטרת בקודש הקודשים, בקטורת של \u0003שאר ימות השנה\u0004 המוקטרת בהיכל \u0003מניין? תלמוד לומר: \"וכסה\"\u0004 ללמד שבכל פעם שמקטירים קטורת צריך שיהא בה מעלה עשן.","\u0003רב אשי אמר:\u0004 פסוק \u0003חד\u0004 \u0005[אחד]\u0006 בא ללמדנו \u0003למצוה, וחד\u0004 \u0005[\u0006ופסוק \u0005אחד]\u0006 בא \u0003לעכב,\u0004 שאם לא עשה כן פסל. \u0003רבא אמר:\u0004 פסוק \u0003חד\u0004 \u0005[אחד]\u0006 בא ללמדנו שיש \u0003עונש\u0004 מיתה בדבר, \u0003וחד\u0004 \u0005[\u0006ופסוק \u0005אחד]\u0006 בא \u0003לאזהרה,\u0004 להודיע שדבר זה אסור, שהרי אין עונש בלא אזהרה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' אליעזר אומר:\u0004 נאמר: \u0003\"\u0004דבר אל אהרן אחיך ואל יבא בכל עת אל הקודש מבית לפרוכת אל פני הכפורת אשר על הארון \u0003ולא ימות\"\u0004 (ויקרא טז, ב) — הרי זה בא ללמד על \u0003עונש\u0004 המחסיר מעלה עשן מסממני הקטורת, \u0003\"כי בענן אראה\u0004 על הכפורת \u0003\"\u0004— הרי זו \u0003אזהרה,\u0004 שאם לא כלל בין הסממנים גם מעלה עשן שהוא הגורם לענן הקטורת — אסור הדבר.","\u0003יכול יהיו שניהם אמורין קודם מיתת בני אהרן\u0004 שמתו בבואם אל הקודש — \u0003תלמוד לומר: \"אחרי מות שני בני אהרן\"\u0004 (ויקרא טז, א). \u0003יכול יהיו שניהם,\u0004 גם העונש וגם האזהרה \u0003אמורים אחר מיתת שני בני אהרן — תלמוד לומר: \"כי בענן אראה על הכפרת\". הא כיצד? אזהרה\u0004 נאמרה \u0003קודם מיתה\u0004 של בני אהרן, \u0003ועונש\u0004 מיתה שיש בדבר נאמר \u0003אחר מיתת\u0004 בניו.","על דברי ר' אליעזר שואלים: \u0003מאי תלמודא?\u0004 כלומר: מה משמעו של לימוד זה, כיצד למד מן הלשון \"אראה\" שהדבר נאמר קודם? \u0003אמר רבא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי בענן אראה\"\u0004 — לשון עתיד, משמע: \u0003ועדיין לא נראה\u0004 הענן על הכפורת, לפי שעדיין לא נבנה המשכן. ודבר זה היה לפני שנכנסו בני אהרן ומתו. ושואלים: אם כן \u0003ואלא מאי טעמא איענוש\u0004 \u0005[מה טעם נענשו]\u0006 במיתה אם העונש לא נאמר עדיין? הרי אין עונשים אדם על חטא שלא ידע את עונשו!","ומשיבים: לא בשל הכניסה לקודש נענשו, אלא מטעם אחר, \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר אומר: לא מתו בני אהרן אלא על שהורו הלכה בפני משה רבן,\u0004 שהיה להם לשאול אותו ולא שאלו. ושואלים: \u0003מאי דרוש\u0004 \u0005[מה דרשו]\u0006 מן המקרא, עד שהעלו בדעתם להכנס ולהכניס אש זרה בקודש? נאמר: \u0003\"ונתנו בני אהרן הכהן אש על המזבח\"\u0004 (ויקרא א, ז) — לומר: \u0003אף על פי שהאש יורדת מן השמים — מצוה\u0004 מיוחדת היא \u0003להביא מן ההדיוט\u0004 (בשר ודם), ולקיום מצוה זו נכנסו להביא אש למזבח. ואף שהורו כדין, מתו כעונש על שלא שאלו את משה רבינו.","שנינו במשנה: \u0003יצא ובא לו כדרך כניסתו,\u0004 כלומר: שאין הכהן הגדול הופך פניו אלא חוזר לאחוריו כשפניו אל הארון, בכל דרך יציאתו. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה]?\u0006 מה מקורם במקרא? \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויבא שלמה לבמה אשר בגבעון ירושלים\"\u0004 (דברי הימים ב' א, יג), ולכאורה \u0003וכי מה ענין גבעון אצל ירושלים?\u0004 או שבא לגבעון, או שבא לירושלים!","\u0003אלא: מקיש יציאתו מגבעון לירושלים, לביאתו מירושלים לגבעון, מה ביאתו מירושלים לגבעון\u0004 בהכרח היו \u0003פניו כלפי במה, כדרך ביאתו\u0004 של אדם — \u0003אף יציאתו מגבעון לירושלים\u0004 היו עדיין \u0003פניו כלפי במה, כדרך ביאתו.\u0004 ומכאן למדים שאין מחזירין פנים מן הקודש, אלא חוזרים אחורנית.","\u0003וכן כהנים בעבודתן, ולוים בדוכנן\u0004 שהיו אומרים שירה במקדש \u0003וישראל במעמדן\u0004 שהיו צופים בהקרבת קרבנות היום \u0003כשהן נפטרין\u0004 מן הקודש \u0003לא היו מחזירין פניהן והולכין, אלא מצדדין פניהן\u0004 הצידה \u0003והולכין\u0004 כלפי הצד כדי שלא להפנות עורף לקודש.","\u0003וכן\u0004 דרך ארץ של \u0003תלמיד הנפטר מרבו — לא יחזיר פניו וילך, אלא מצדד פניו והולך.\u0004 ומספרים: \u0003כי הא\u0004 \u0005[כמו\u0006 שהיה נוהג\u0005]\u0006 \u0003ר' אלעזר כד הוה מיפטר מיניה\u0004 \u0005[כאשר היה נפרד מאת]\u0006 \u0003ר' יוחנן\u0004 רבו, \u0003כד הוה בעי\u0004 \u0005[כאשר היה רוצה]\u0006 \u0003ר' יוחנן לסגויי\u0004 \u0005[ללכת]\u0006 ממנו, \u0003הוה גחין קאי\u0004 \u0005[היה מתכופף ועומד]\u0006 \u0003ר' אלעזר אדוכתיה\u0004 \u0005[במקומו]\u0006 בדרך כבוד והכנעה \u0003עד דהוה מיכסי\u0004 \u0005[שהיה מתכסה]\u0006 \u0003ר' יוחנן מיניה\u0004 \u0005[ממנו]\u0006 כשהיה מתרחק ביותר, ורק אז היה ר' אלעזר פונה ללכת.","\u0003וכד הוה בעי\u0004 \u0005[וכאשר היה רוצה]\u0006 \u0003ר' אלעזר לסגויי\u0004 \u0005[ללכת],\u0006 \u0003הוה קא אזיל לאחוריה\u0004 \u0005[היה הולך לאחוריו]\u0006 \u0003עד דמכסי מיניה\u0004 \u0005[עד שהיה מתכסה ממנו]\u0006 מ\u0003ר' יוחנן\u0004 ואז היה הולך כסדרו, כדי שלא יחזיר פניו לרבו. ועוד מספרים: \u0003רבא כד הוה מיפטר מיניה\u0004 \u0005[כאשר היה נפטר]\u0006 מ\u0003רב יוסף, הוה אזיל לאחוריה\u0004 \u0005[היה הולך לאחוריו]\u0006 ולא היה שם ליבו למכשולים שבדרך \u0003עד דמנגפן כרעיה\u0004 \u0005[שהיו ניגפות,\u0006 נפצעות, \u0005רגליו]\u0006 \u0003ומתווסן אסקופתא דבי\u0004 \u0005[והיו מתמלאים מפתניו של בית]\u0006 \u0003רב יוסף דמא\u0004 \u0005[בדם]\u0006 מפצעיו של רבא."],["\u0003אמרו ליה\u0004 \u0005[אמרו לו]\u0006 \u0003לרב יוסף: הכי עביד\u0004 \u0005[כך עושה]\u0006 \u0003רבא,\u0004 מפני שרב יוסף עיוור היה ולא ראה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003יהא רעוא דתרום רישך אכולה כרכא\u0004 \u0005[יהי רצון שירום ראשך על כל העיר],\u0006 שכיון שכך אתה מכבד את רבך — ראוי אתה לכבוד זה.","כיון שעסקו בענין הצורך בהליכה לאחור בעת פרידת התלמיד מן הרב, מביאים נושא דומה. \u0003אמר ר' אלכסנדרי אמר ר' יהושע בן לוי: המתפלל\u0004 וסיים תפלתו \u0003צריך שיפסיע שלש פסיעות לאחוריו, ואחר כך יתן שלום\u0004 שהוא כיוצא מלפני הקדוש ברוך הוא, בדרך פרידה של כבוד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי\u0004 והוסיף: \u0003כיון שפסע שלש פסיעות לאחוריו — התם איבעיא ליה למיקם\u0004 \u0005[שם צריך הוא לעמוד]\u0006 ולא יחזור מיד. \u0003משל לתלמיד הנפטר מרבו, אם חוזר לאלתר\u0004 (מיד) למקום שעמד בו \u0003דומה לכלב ששב על קיאו,\u0004 ונמצא מקלקל כל מה שעשה קודם.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003המתפלל, צריך שיפסיע שלש פסיעות לאחוריו ואחר כך יתן שלום, ואם לא עשה כן — ראוי לו שלא התפלל,\u0004 שהרי הראה במעשיו שאינו מכבד את הקדוש ברוך הוא. \u0003ומשום\u0004 החכם \u0003שמעיה אמרו: שנותן שלום\u0004 ומשתחוה תחילה לצד \u0003ימין ואחר כך לשמאל,\u0004 שנאמר: \u0003\"מימינו אש דת למו\"\u0004 (דברים לג, ב) \u0003ואומר: \"יפל מצדך אלף ורבבה מימינך\"\u0004 (תהלים צא, ז).","ושואלים: \u0003מאי ואומר,\u0004 כלומר מדוע הוצרך להוסיף עוד ראיה אחרת? ומשיבים: \u0003וכי תימא אורחא דמילתא היא למיתב\u0004 \u0005[ואם תאמר\u0006 כי \u0005דרך רגילה היא לתת]\u0006 \u0003בימין,\u0004 שצד זה רגילים להשתמש בו, ולא משום החשיבות שיש בדבר, על כן \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה שנאמר: \u0003\"יפל מצדך אלף ורבבה מימינך\",\u0004 לומר שצד ימין הוא החשוב.","מסופר: \u0003רבא חזייה\u0004 \u0005[ראה את]\u0006 \u0003אביי דיהיב שלמא לימינא ברישא\u0004 \u0005[שהוא נותן שלום,\u0006 משתחווה בסוף התפלה, \u0005לצד ימין תחילה]\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 שצריך להשתחוות לצד \u0003ימין דידך\u0004 \u0005[שלך]?\u0006 לצד \u0003שמאל דידך קא אמינא\u0004 \u0005[שלך אני אומר]\u0006 שיש להשתחוות תחילה, משום \u0003דהוי\u0004 \u0005[שהיא]\u0006 \u0003ימינו של הקדוש ברוך הוא.\u0004 שהרי הוא, כביכול, עומד אליך פנים אל פנים. \u0003אמר רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא: חזינא להו\u0004 \u0005[ראיתי אותם]\u0006 את \u0003אביי ורבא דפסעי להו\u0004 \u0005[שהיו פוסעים]\u0006 אותן \u0003שלש פסיעות בכריעה אחת\u0004 ולא היו זוקפים קודם, שכל זה דרך הכנעה וקבלת מרות היא.","שנינו במשנה שהיה הכהן הגדול \u0003מתפלל תפלה קצרה בבית החיצון.\u0004 ושואלים: \u0003מאי מצלי\u0004 \u0005[מה\u0006 היה \u0005מתפלל]?\u0006 \u0003רבא בר רב אדא ורבין בר רב אדא תרוייהו משמיה\u0004 \u0005[שניהם משמו]\u0006 של \u0003רב אמרי\u0004 \u0005[\u0006היו \u0005אומרים]\u0006 כך היתה תפילתו: \u0003יהי רצון מלפניך ה' אלהינו שתהא שנה זו גשומה ושחונה\u0004 (חמה). ותוהים מיד: \u0003שחונה מעליותא\u0004 \u0005[מעלה]\u0006 \u0003היא?!\u0004 כלומר: לשם מה יש לבקש שתהא שנה חמה? \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003אם שחונה\u0004 היא השנה הבאה \u0003שתהא\u0004 גם \u0003גשומה\u0004 ולא יזיק החום ליבול.","\u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מסיים בה\u0004 בלשון תפילה זו \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יהודה: לא יעדי עביד שולטן מדבית\u0004 \u0005[יסור מעשה,\u0006 כח, \u0005שלטון מבית]\u0006 \u0003יהודה, ולא יהיו עמך ישראל צריכין לפרנס זה מזה\u0004 אלא יתפרנסו מתנובת הארץ, ולא יזדקקו לעזרת הבריות. \u0003ולא תכנס לפניך תפלת עוברי דרכים\u0004 ההולכים בשעת הגשם ומתפללים שיפסקו הגשמים.","מסופר: \u0003ר' חנינא בן דוסא הוה קא אזיל באורחא\u0004 \u0005[היה מהלך בדרך]\u0006 \u0003שדא מטרא עליה\u0004 \u0005[ירד המטר עליו]\u0006 \u0003אמר: רבונו של עולם! כל העולם כולו בנחת, וחנינא בצער. פסק מיטרא\u0004 \u0005[פסק המטר]\u0006 \u0003כי אתא לביתיה\u0004 \u0005[כאשר בא לביתו]\u0006 \u0003אמר: רבונו של עולם! כל העולם כולו בצער\u0004 שאין גשמים, \u0003וחנינא בנחת. אתא מיטרא\u0004 \u0005[בא הגשם\u0006 בחזרה\u0005].\u0006 \u0003אמר ר' יוסף: מאי אהניא ליה צלותיה\u0004 \u0005[מה הועילה לו תפילתו של]\u0006 ה\u0003כהן גדול לגבי ר' חנינא בן דוסא\u0004 שלמרות תפילת הכהן הגדול בקודש, גדולה קדושתו של ר' חנינא בן דוסא שהקדוש ברוך הוא עושה לו רצונו.","שנינו במשנה כי לא היה הכהן הגדול מאריך בתפילתו. ו\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003מעשה בכהן גדול אחד שהאריך בתפלתו, ונמנו\u0004 (החליטו) \u0003אחיו הכהנים ליכנס אחריו\u0004 שמא מת או התעלף ויש להוציאו. \u0003התחילו הם נכנסין והוא יוצא. אמרו לו: מפני מה הארכת בתפלתך? אמר להם:\u0004 ומדוע לא, וכי \u0003קשה בעיניכם שהתפללתי עליכם ועל בית המקדש שלא יחרב? אמרו לו: אל תהי רגיל לעשות כן, שהרי שנינו: לא היה מאריך בתפלתו כדי שלא להבעית\u0004 (להפחיד) \u0003את ישראל\u0004 שמא מת שם.","\u0003משניטל ארון\u0004 הקודש בגלות, \u0003אבן היתה שם\u0004 בקודש הקדשים \u0003מימות נביאים\u0004 ה\u0003ראשונים,\u0004 דוד ושמואל שיסדו את המקדש, ואבן זו \u0003\"שתייה\" היתה נקראת,\u0004 והיתה \u0003גבוה מן הארץ שלש אצבעות ועליה היה נותן\u0004 את הקטורת. לאחר שיצא הכהן הגדול מקודש הקדשים \u0003נטל את הדם\u0004 של פר החטאת \u0003ממי שהיה ממרס בו\u0004 שלא יקרוש, ו\u0003נכנס\u0004 שוב \u0003למקום שנכנס\u0004 בקודש הקדשים \u0003ועמד במקום שעמד\u0004 קודם בהקטרת הקטורת, בין הבדים, \u0003והזה ממנו\u0004 מן הדם, הזאה \u0003אחת למעלה ושבע\u0004 הזאות \u0003למטה.\u0004","\u0003ולא היה מתכוון להזות לא למעלה\u0004 ממש \u0003ולא למטה\u0004 ממש \u0003אלא כמצליף\u0004 בשורה אחת, זו מתחת לזו. \u0003וכך היה מונה\u0004 בהזאותיו, שלא יטעה: \u0003אחת, אחת ואחת, אחת ושתים, אחת ושלש, אחת וארבע, אחת וחמש, אחת ושש, אחת ושבע. יצא\u0004 משם \u0003והניחו\u0004 לדם שנשאר \u0003על כן הזהב שבהיכל.\u0004","\u0003הביאו לו את השעיר\u0004 החטאת לה', \u0003שחטו, וקבל במזרק את דמו, נכנס למקום שנכנס\u0004 בקודש הקדשים \u0003ועמד במקום שעמד, והזה ממנו אחת למעלה ושבע למטה, וכך היה מונה,\u0004 כדרך שמנה בדם הפר: \u0003אחת, אחת ואחת, אחת ושתים וכו' יצא והניחו\u0004 גם הוא \u0003על כן הזהב השני\u0004 שהיה \u0003בהיכל. ר' יהודה אומר: לא היה שם אלא כן אחד בלבד,\u0004 ועליו היו מניחים את שני הבזיכים, וכך היה עושה: \u0003נטל דם הפר\u0004 מן הכן \u0003והניח דם השעיר\u0004 במקומו","\u0003והזה ממנו\u0004 מדם הפר \u0003על הפרוכת שכנגד\u0004 (מול) \u0003הארון מבחוץ, אחת למעלה ושבע למטה ולא היה מתכוון וכו'. וכך היה מונה וכו'.\u0004 סיים \u0003נטל דם השעיר\u0004 מן הכן \u0003והניח דם הפר\u0004 במקומו על הכן \u0003והזה ממנו\u0004 מדם השעיר \u0003על הפרוכת שכנגד הארון מבחוץ\u0004 כדרך שעשה בדם הפר, \u0003אחת למעלה ושבע למטה וכו'.\u0004 לאחר מכן \u0003עירה דם הפר לתוך דם השעיר, ונתן\u0004 שוב \u0003את\u0004 הדם מן המזרק \u0003המלא\u0004 אל תוך המזרק ה\u0003ריקן\u0004 כדי לערב יפה את הדמים.","על לשון המשנה מעירים: \u0003\"משנגנז\u0004 הארון \u0003\"לא קתני\u0004 \u0005[שנינו],\u0006 \u0003אלא \"משניטל\",\u0004 ואם כן \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003כמאן דאמר\u0004 \u0005[כ\u0006שיטת \u0005מי שאמר]\u0006 כי \u0003ארון גלה לבבל\u0004 ולא נגנז במקומו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר אומר: ארון גלה לבבל, שנאמר: \"ולתשובת השנה שלח המלך נבוכדנאצר ויבאהו בבלה עם כלי חמדת בית ה'\"\u0004 (דברי הימים ב' לו, י), וכלי החמדה המיוחד הלא הוא ארון הברית.","וכן \u0003ר' שמעון בן יוחאי אומר: ארון גלה לבבל, שנאמר: \"\u0004הנה ימים באים ונישא כל אשר בביתך ואשר אצרו אבותיך עד היום הזה בבל \u0003לא יותר דבר אמר ה'\"\u0004 (ישעיה לט, ו) — \u0003אלו עשרת הדברות שבו,\u0004 שגם הם לא נותרו.","\u0003ור' יהודה בן לקיש אומר: ארון במקומו נגנז, שנאמר: \"ויראו ראשי הבדים מן הקדש על פני הדביר ולא יראו החוצה ויהיו שם עד היום הזה\"\u0004 (מלכים א' ח, ח) ובכל מקום שנאמר \"עד היום הזה\", נשאר כך לעולם, שהרי בכל זמן אפשר לקרוא כן. משמע שנגנז הארון במקומו.","ומעירים: ושיטה זו שארון גלה לבבל \u0003פליגא\u0004 \u0005[חלוקה]\u0006 על דעת \u0003עולא\u0004 ש\u0003אמר עולא, שאל ר' מתיא בן חרש את ר' שמעון בן יוחאי\u0004 כשהיה \u0003ברומי: וכי מאחר שר' אליעזר מלמדנו פעם ראשונה ושניה,\u0004 כלומר: בשני כתובים, כי \u0003ארון גלה לבבל,\u0004 פעם \u0003ראשונה\u0004 מלמדנו \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 שהביא מן הכתוב: \u0003\"ויבאהו בבלה עם כלי חמדת בית ה'\"\u0004 (דברי הימים ב' לו, י), פעם \u0003שניה מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004 — שאמר ר' אליעזר: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויצא מבת ציון\u0004"],["\u0003כל הדרה\"\u0004 (איכה א, ו). \u0003מאי\u0004 \u0005[מה]\u0006 פירוש: \u0003\"כל הדרה\" — חדרה,\u0004 כלומר דבר שהיה גנוז לפנים בחדרי חדרים, הוא ארון הברית. \u0003אתה\u0004 ר' שמעון בן יוחאי \u0003מאי\u0004 \u0005[מה]\u0006 \u0003אתה אומר\u0004 בענין זה? \u0003אמר לו: שאני אומר ארון במקומו נגנז\u0004 ולא גלה, \u0003שנאמר: \"ויארכו הבדים\u0004 ויראו ראשי הבדים מן הקודש על פני הדביר ולא יראו החוצה ויהיו שם עד היום הזה\u0003\"\u0004 (מלכים א' ח, ח).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה לעולא: מאי משמע\u0004 \u0005[מה המשמעות]\u0006 מה יסוד ההוכחה הזו? ענה לו: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שם: \u0003\"ויהיו שם עד היום הזה\"\u0004 ו\"היום הזה\" פירושו: כל יום שקוראים בו דבר זה, והוא לעולם. והקשה לו: \u0003וכל היכא דכתיב\u0004 \u0005[מקום שנאמר\u0006 בו\u0005]:\u0006 \u0003\"עד היום הזה\" לעולם הוא\u0004 ואינו מתכוון לזמן כתיבת הדברים? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ואת היבוסי ישב ירושלים לא הורישו בני בנימין וישב היבוסי את בני בנימין בירושלים עד היום הזה\"\u0004 (שופטים א, כא) \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003לא גלו\u0004 היבוסים מירושלים?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה אומר: חמשים ושתים שנה\u0004 מזמן חורבן הבית בימי נבוכדנצר \u0003לא עבר איש ביהודה, שנאמר: \"על ההרים אשא בכי ונהי ועל נאות מדבר קינה כי נצתו מבלי איש עבר ולא שמעו קול מקנה מעוף השמים ועד בהמה נדדו הלכו\"\u0004 (ירמיה ט, ט) ו\u0003\"בהמה\" בגימטריא חמשים ושתים הוו\u0004 \u0005[הם],\u0006 לרמז שחמישים ושתים שנה לא עבר אדם ביהודה, הרי שהכל גלו משם!","\u0003ותניא\u0004 \u0005[ושנוייה\u0006 עוד ברייתא\u0005]:\u0006 \u0003ר' יוסי אומר: שבע שנים נתקיימה\u0004 קללת \u0003גפרית ומלח בארץ ישראל,\u0004 שלא ישב אדם בה. \u0003ואמר ר' יוחנן: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יוסי,\u0004 מהיכן לומד הוא דבר זה — \u0003אתיא\u0004 \u0005[באה,\u0006 נלמד\u0005],\u0006 הדבר מגזירה שוה \u0003\"ברית\" \"ברית\"; כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"והגביר ברית לרבים שבוע אחד\"\u0004 (דניאל ט, כז) ושבוע זה משמעו שבע שנים, \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 שאחר הקללה שתהא הארץ גפרית ומלח: \u0003\"ואמרו על אשר עזבו את ברית ה' אלהי אבתם\"\u0004 (דברים כט, כד). הרי לך הוכחה נוספת כי כשאמר הכתוב \"עד היום הזה\", אין הכוונה לעולם!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 עולא: \u0003הכא\u0004 \u0005[כאן]\u0006 בכתוב על הארון \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"שם\"\u0004 (\"ויהיו שם\"), \u0003התם\u0004 \u0005[שם]\u0006 בפסוק על היבוסי \u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"שם\", וכל היכא\u0004 \u0005[היכן]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שם\"\u0004 — \u0003לעולם הוא. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: והרי נאמר: \u0003\"ומהם מן בני שמעון הלכו להר שעיר אנשים חמש מאות ופלטיה ונעריה ורפיה ועזיאל בני ישעי בראשם. ויכו את שארית הפלטה לעמלק וישבו שם עד היום הזה\"\u0004 (דברי הימים א' ד, מב-מג)","\u0003וכבר עלה סנחריב מלך אשור ובלבל\u0004 את \u0003כל הארצות, שנאמר\u0004 בדברי סנחריב: \u0003\"ואסיר גבולת עמים ועתודתיהם שושתי\"\u0004 (ישעיה י, יג), משמע שגם בני שמעון גלו, אף שכתוב בהם גם \"שם\" וגם \"עד היום הזה\" ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לדברי עולא.","\u0003אמר רב נחמן: תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003וחכמים אומרים: ארון\u0004 הברית \u0003בלשכת דיר העצים היה גנוז. אמר רב נחמן בר יצחק: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 מעין דבר זה במשנה: \u0003מעשה בכהן אחד שהיה מתעסק\u0004 בדברים שונים, ובתוך כדי כך \u0003ראה\u0004 בדיר העצים \u0003רצפה משונה מחברותיה,\u0004 שאחת ממרצפות השיש ששימשו לה כרצפה, היתה גבוהה מן האחרות, ודבר זה מהווה עדות לכך שניטלה ממקומה ולאחר מכן הושבה בחזרה \u0003ובא והודיע את חבירו\u0004 שיש שם רצפה מיוחדת, \u0003ולא הספיק לגמור\u0004 לספר \u0003את הדבר\u0004 היכן בדיוק ראה \u0003עד שיצתה נשמתו וידעו ביחוד\u0004 (בבירור) \u0003ששם ארון גנוז\u0004 ואין רוצים שיתגלה הדבר.","ושואלים: \u0003מאי הוה עביד\u0004 \u0005[מה היה עושה]\u0006 אותו כהן שגילה את הרצפה? \u0003אמר ר' חלבו: מתעסק בקרדומו היה\u0004 כלומר היה משתעשע ומקיש בקרדום על הרצפה, ובתוך כך גילה שמתחת לאותה מרצפת קיים חלל, המשמש בוודאי כפתח של מחילה. \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: שני כהנים בעלי מומין היו מתליעין בעצים,\u0004 שעבודת הכהנים בעלי המומים היתה, בין השאר, למיין את העצים וכל עץ שיש בו תולעים לא היו מעלים אותו למזבח, \u0003ונשמטה קרדומו של אחד מהם ונפלה שם\u0004 לאותו חור שהיה ברצפה \u0003ויצתה אש\u0004 משם \u0003ואכלתו\u0004 לאותו כהן, ושוב לא ידוע היכן בדיוק המקום.","כיון שהבאנו את הכתוב על הבדים, \u0003ר' יהודה רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בין שני כתובים; \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד: \u0003\"ויראו ראשי הבדים\"\u0004 (מלכים א' ח, ח) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 באותו פסוק: \u0003\"ולא יראו החוצה\"\u0004 (מלכים א' ח, ח) \u0003הא כיצד\u0004 מיישב אתה את הסתירה? — היו \u0003נראין ואין נראין,\u0004 כלומר: נראים מעט. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 כשיטה זו: נאמר: \u0003\"ויראו ראשי הבדים\", יכול לא יהו זזין ממקומן\u0004 ואינם בולטים כלל? — \u0003תלמוד לומר: \"ויארכו הבדים\". יכול יהו מקרעין בפרוכת ויוצאין\u0004 הרבה מאוד — \u0003תלמוד לומר: \"ולא יראו החוצה\",\u0004","\u0003הא כיצד\u0004 היה הדבר? — היו בדי הארון \u0003דוחקין ובולטין ויוצאין בפרוכת\u0004 כלפי חוץ, \u0003ונראין כשני דדי אשה\u0004 הבולטים בבגדה. והוא \u0003שנאמר: \"צרור המר דודי לי בין שדי ילין\"\u0004 (שיר השירים א, יג), שמשום כך דימו את ארון הברית, מקום לינת השכינה, כדדיה של אשה.","אגב דברים אלה \u0003אמר רב קטינא: בשעה שהיו ישראל עולין לרגל\u0004 היו \u0003מגללין\u0004 פותחין \u0003להם את הפרוכת ומראין להם את הכרובים שהיו מעורים\u0004 (דבוקים ומחובקים) \u0003זה בזה, ואומרים להן ראו חבתכם לפני המקום כחבת זכר ונקבה.\u0004 כי שני כרובים אלה מסמלים כיכול את הקדוש ברוך הוא ואת כנסת ישראל.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב חסדא:\u0004 כיצד יכלו לראות את הדבר? והלא נאמר: \u0003\"ולא יבאו לראות כבלע את הקדש\u0004 ומתו\u0003\"\u0004 (במדבר ד, כ), \u0003ואמר רב יהודה אמר רב: בשעת הכנסת כלים לנרתק שלהם\u0004 לצורך נשיאתם ממקום למקום אסור היה אפילו ללויים לראותם. ולכאורה, כל שכן כשהם נמצאים במקומם בקודש פנימה אסור לראותם, וכיצד איפוא הראום לרבים?","\u0003אמר רב נחמן\u0004 כתשובה לכך: \u0003משל לכלה, כל זמן שהיא בבית אביה\u0004 והיא עדיין ארוסה הרי היא \u0003צנועה מבעלה\u0004 ומסתתרת מפניו, ואין ראוי לראותה. \u0003כיון שבאתה לבית חמיה\u0004 שנישאה נישואין גמורים, והיא חיה בבית הבעל — שוב \u0003אינה צנועה מבעלה.\u0004 אף כאן, במדבר כיון שלא היתה השראת שכינה בישראל במקום קבוע — אסור היה לראות את הקודש, אולם במקדש במקום הקבע הורשו הכל לראותו.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב חנא בר רב קטינא\u0004 ממה ששנינו: \u0003מעשה בכהן אחד שהיה מתעסק\u0004 בקרדומו ובתוך כדי כך גילה את מקום גניזת הארון, וכשרצה לגלות דבר זה זה מת, כדי שלא יראה את ארון הברית, משמע שאף לאחר בנין המקדש אסור היה לראות בקודש! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אין להקשות, כי \u0003נתגרשה קא אמרת\u0004 שכיון שגלו ישראל לאחר חורבן מקדש ראשון הרי הם כגירושין של אשה מבעלה, \u0003וכשנתגרשה\u0004 האשה שוב \u0003חזרה לחיבתה הראשונה,\u0004 שהיא שוב צנועה, ואינה מראה את עצמה, עד שתחזור השכינה לכמו שהיתה בבית הראשון.","על הדבר שאמר רב קטינא שואלים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים],\u0006 כיצד היה ענין זה שהיו מגלגלים להם את הפרוכת להראות לכל את הכרובים? \u0003אי נימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003במקדש ראשון — מי הואי\u0004 \u0005[האם היתה]\u0006 בו \u0003פרוכת\u0004 כלל בין הקודש לקודש הקדשים? והלא כותל פנוי היה שם. אלא תאמר שמדובר \u0003במקדש שני\u0004 — אולם שם \u0003מי הוו\u0004 \u0005[האם היו]\u0006 \u0003כרובים?\u0004 שהרי לא היה ארון, וממילא לא היו כרובים עליו? ומשיבים: \u0003לעולם\u0004 יש לפרש שמדובר כאן \u0003במקדש ראשון, ומאי\u0004 \u0005[ומהי]\u0006 \u0003פרוכת\u0004 זו שהזכרנו — \u0003פרוכת דבבי\u0004 \u0005[של השערים]\u0006 שכדי שיראו כל ישראל היו צריכים להרים את כל פרוכות השערים.","ש\u0003אמר ר' זירא אמר רב: שלשה עשר פרוכות היו במקדש\u0004 השני: \u0003שבעה כנגד\u0004 (בתוך) \u0003שבעה שערים, שתים\u0004 נוספות בפנים \u0003אחת לפתחו של היכל, ואחת לפתחו של אולם. שתים\u0004 היו \u0003בדביר\u0004 שבקודש הקדשים, במקום האמה טרקסין, \u0003ושתים כנגדן\u0004 למעלה \u0003בעליה\u0004 שמעל קודש הקדשים היתה קומה נוספת, והיתה בנויה כתבנית הבנין שלמטה ואף בה עשו פרוכת, שלא עלו לעליית בית קודש הקדשים אלא לצורך גדול. ומן הסתם היו פרוכות אלה גם במקדש ראשון.","\u0003רב אחא בר יעקב אמר: לעולם\u0004 יש לפרש שמדובר \u0003במקדש שני,\u0004 ושם הרי היתה פרוכת בפתח קודש הקדשים, אולם ו\u0003כרובים דצורתא הוו קיימי\u0004 \u0005[שבציור היו קיימים]\u0006 שם, שציירו או חקקו בכתלים כרובים מעשה ציור, וכעין מה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לגבי מקדש ראשון: \u0003\"ואת כל קירות הבית מסב קלע\u0004 פיתוחי מקלעות \u0003כרובים ותמרת ופטרי ציצים\u0004 מלפנים ולחיצון\u0003\"\u0004 (מלכים א' ו, כט), ובהמשך נאמר: \u0003\"וצפה זהב מישר על המחקה\"\u0004 (מלכים א' ו, לה). משמע, שנוסף לכרובים שבקודש פנימה היו כרובים מצויירים על הקירות.","\u0003וכתיב\u0004 \u0005[ונאמר מלכים א' ו, לה]:\u0006 \u0003\"כמער איש וליות\"\u0004 (מלכים א' ז, לו) ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"כמער איש וליות\"? אמר רבה בר רב שילא:\u0004"],["\u0003כאיש המעורה\u0004 ודבוק \u0003בלוייה\u0004 (באשה) \u0003שלו,\u0004 שהיו הכרובים נראים מחובקים יחד. \u0003אמר ריש לקיש: בשעה שנכנסו גוים להיכל\u0004 בבית שני \u0003ראו\u0004 ציורים של \u0003כרובים המעורין זה בזה,\u0004 קלפום מן הקיר ו\u0003הוציאון לשוק ואמרו: ישראל הללו, שברכתן ברכה וקללתן קללה\u0004 שהם מלאים ביראת שמים \u0003יעסקו בדברים הללו\u0004 ויעשו שם דמויות כגון אלה? \u0003מיד הזילום\u0004 (התיכו אותם) והשמידום, \u0003שנאמר: \"כל מכבדיה הזילוה כי ראו ערותה\"\u0004 (איכה א, ח).","שנינו במשנה כי אבן היתה בקודש הקדשים \u0003ו\"שתיה\" היתה נקראת. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: מדוע נקראת שתיה — \u0003שממנה הושתת\u0004 \u0005[נברא]\u0006 \u0003העולם.\u0004 ומעירים: הרי \u0003תנן כמאן דאמר\u0004 \u0005[שנינו\u0006 במשנה כשיטת \u0005מי שאמר]:\u0006 \u0003מציון נברא העולם. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אליעזר אומר: עולם מאמצעיתו נברא, שנאמר: \"בצקת עפר למוצק ורגבים ידבקו\"\u0004 (איוב לח, לח), וכשם שעושים ברגבי עפר, שמתחילים מן האמצע תחילה, ומוסיפים רגבים מסביב, כך היתה גם בריאת העולם.","\u0003ר' יהושע אומר: עולם מן הצדדין נברא, שנאמר: \"כי לשלג יאמר הוא ארץ וגשם מטר וגשם מטרות עזו\"\u0004 (איוב לז, ו), כלומר: שמכל צד היו הגשמים יורדים, ומשם נבראת הארץ. \u0003ר' יצחק אמר: אבן ירה הקדוש ברוך הוא בים, וממנה נשתת העולם, שנאמר: \"על מה אדניה הטבעו או מי ירה אבן פנתה\"\u0004 (איוב לח, ו).","\u0003וחכמים אומרים: מציון נברא\u0004 העולם, \u0003שנאמר: \"מזמור לאסף אל אלהים ה'\u0004 דיבר ויקרא ארץ ממזרח שמש עד מבואו\u0003\"\u0004 (תהלים נ, א) \u0003ואומר: \"מציון מכלל יפי\u0004 אלהים הופיע\u0003\"\u0004 (תהלים נ, ב). כלומר: \u0003ממנו\u0004 מציון \u0003מוכלל\u0004 (נבנה) \u0003יפיו של עולם.\u0004 ומשנתנו כשיטה זו היא.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' אליעזר הגדול אומר:\u0004 נאמר: \u0003\"אלה תולדות השמים והארץ בהבראם ביום עשות ה' אלהים ארץ ושמים\"\u0004 (בראשית ב, ד), \u0003תולדות שמים,\u0004 כלומר: כל הנמצאים בשמים — \u0003משמים נבראו, תולדות הארץ — מארץ נבראו.\u0004","\u0003וחכמים אומרים: אלו ואלו מציון נבראו, שנאמר: \"מזמור לאסף אל אלהים ה' דבר ויקרא ארץ ממזרח שמש עד מבאו\"\u0004 (תהלים נ, א), משמע שמדבר הכתוב בבריאת העולם. \u0003ואומר \"מציון מכלל יפי אלהים הופיע\"\u0004 (תהלים נ, ב), כלומר: \u0003ממנו\u0004 מציון \u0003מוכלל יפיו של עולם,\u0004 בין בתולדות השמים ובין בתולדות הארץ.","שנינו במשנה ש\u0003נטל הכהן את הדם\u0004 של פר החטאת \u0003ממי\u0004 שהיה \u0003ממרס בו\u0004 שלא יקרוש, ומזה ממנו כמצליף. ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש המילה\u0005]\u0006 \u0003כמצליף?\u0004 היה \u0003מחוי\u0004 \u0005[מראה\u0006 בידו\u0005]\u0006 \u0003רב יהודה\u0004 כדי להסביר זאת"],["\u0003כמנגדנא\u0004 \u0005[כמי שמכה ברצועה]\u0006 על הגב, ומפעם לפעם מכה למטה יותר. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא, \u0003כשהוא מזה\u0004 מן הדם — \u0003אינו מזה על הכפורת\u0004 למעלה, בגגה, \u0003אלא כנגד עוביה של כפורת,\u0004 ו\u0003כשהוא מזה\u0004 אחת \u0003למעלה —\u0004 הריהו \u0003מצדד ידו\u0004 שיהא גב ידו מופנה \u0003למטה\u0004 ומזה כלפי מעלה. \u0003וכשהוא מזה\u0004 שבע \u0003למטה —\u0004 הריהו \u0003מצדד ידו\u0004 שיהא גבה \u0003למעלה.\u0004 אבל אינו מזה ממש על הכפורת או למטה ממנה ואין הדם נוגע בה ממש.","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלה],\u0006 שהזאות אלה אינן על גבי הכפורת ממש? \u0003אמר רב אחא בר יעקב, אמר ר' זירא: אמר קרא\u0004 \u0005[הכתוב]\u0006 בשעיר החטאת: \u0003\"\u0004ועשה את דמו כאשר עשה לדם הפר \u0003והזה אתו על הכפרת ולפני הכפרת\"\u0004 (ויקרא טז, טו), \u0003לא יאמר \"למטה\",\u0004 כלומר: \"לפני הכפורת\" \u0003בשעיר דלא\u0004 \u0005[שאינו]\u0006 \u0003צריך\u0004 לאמרו, משום \u0003דגמר\u0004 \u0005[שהוא לומד]\u0006 שיש לעשות זאת \u0003ממטה\u0004 שנאמר בהזאת דם ה\u0003פר,\u0004 שהרי נאמר שמעשה השעיר כמעשה הפר,","אם כן \u0003למה נאמר\u0004 דבר זה שנית \u0003— לאקושי\u0004 \u0005[להשוות]\u0006 \u0003\"על\u0004 הכפורת \u0003\"ל\"לפני\u0004 הכפורת\u0003\",\u0004 שכיון שכתבם בפסוק זה יחד, באו ללמוד זה מזה: \u0003מה \"לפני\"\u0004 משמעו \u0003דלאו\u0004 \u0005[שאינו]\u0006 \u0003על\u0004 הכפורת ממש אלא רק לפני הכפורת, \u0003אף \"על\"\u0004 משמעו \u0003דלאו\u0004 \u0005[שאינו]\u0006 \u0003על\u0004 ממש, אלא לפני הכפורת, ורק רק מצדד ידו כלפי מעלה.","ומקשים: \u0003אדרבה\u0004 (להיפך) נאמר כך: \u0003לא יאמר למעלה בפר\u0004 ש\u0003לא צריך,\u0004 שהרי \u0003גמר\u0004 \u0005[למד]\u0006 \u0003ממעלה\u0004 שנאמר ב\u0003שעיר\u0004 שהרי הכתוב השווה את שניהם, אם כן \u0003למה\u0004 בכל זאת \u0003נאמר? לאקושי\u0004 \u0005[להשוות]\u0006 \u0003\"לפני\"\u0004 האמור בפר \u0003ל\"על\"\u0004 האמור בשעיר, ונאמר כך: \u0003מה \"על\"\u0004 האמור בשעיר משמעו: \u0003על ממש,\u0004 כמשמעו, \u0003אף \"לפני\"\u0004 כוונתו — \u0003על ממש\u0004 שאף דמי השעיר יגעו בעובי הכפורת ממש!","על קושיה זו תוהים: \u0003האי מאי\u0004 \u0005[זו מה היא]?!\u0006 כלומר: מה מקום לשאלה זו? \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כפי שאמרנו כי \u0003למטה\u0004 האמור ב\u0003שעיר לאקושי\u0004 \u0005[להשוות]\u0006 \u0003למעלה\u0004 האמור ב\u0003פר,\u0004 אם כן \u0003מיבעי ליה\u0004 \u0005[צריכים אנו\u0006 לדבר זה\u0005]\u0006 \u0003לכדתנא דבי\u0004 \u0005[לכמו ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אליעזר בן יעקב. דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' אליעזר בן יעקב:\u0004 נאמר: \u0003\"על פני הכפרת קדמה\"\u0004 (ויקרא טז, יד) — \u0003זה בנה אב,\u0004 כלומר: יסוד ללמוד ממנו לכל התורה, ש\u0003כל מקום שנאמר: \"פני\" — אינו אלא קדים,\u0004 כלומר: בצד המזרח. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כפי הקושיה כי \u0003למעלה\u0004 האמור ב\u0003פר לאקושי\u0004 \u0005[להשוות]\u0006 מעלה של פר למעלה של שעיר, אם כן \u0003למטה\u0004 האמור ב\u0003שעיר למאי אתא\u0004 \u0005[למה הוא בא]!\u0006 מה למדים אנו ממנו? אלא על כרחך יש ללמוד מן המקרא כפי שאמרנו קודם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בענין זה: נאמר: \u0003\"והזה אתו על הכפרת ולפני הכפרת\"\u0004 (ויקרא טז, טו) — \u0003למדנו: כמה\u0004 מזה \u0003למעלה בשעיר\u0004 — הזאה \u0003אחת,\u0004 שהרי נאמר \"והזה\". אולם בהזאה ש\u0003למטה בשעיר\u0004 לפני הכפורת, \u0003איני יודע כמה\u0004 פעמים צריכים להזות!","\u0003— הריני דן\u0004 מן הכתובים, \u0003נאמרו דמים\u0004 שמזה \u0003למטה בפר, ונאמרו דמים למטה בשעיר,\u0004 מה דמים שמזה \u0003למטה\u0004 בדם ה\u0003פר — שבע\u0004 הזיות (\"ולפני הכפורת יזה שבע פעמים\". ויקרא טז, יד) \u0003אף\u0004 דמים שמזה \u0003למטה בשעיר — שבע.\u0004","ושואלים: \u0003או כלך\u0004 (לך) \u0003לדרך זו\u0004 ותדרוש כך: \u0003נאמרו דמים למעלה בשעיר, ונאמרו דמים למטה בשעיר. מה למעלה בשעיר\u0004 הזיה \u0003אחת — אף למטה בשעיר\u0004 הזאה \u0003אחת\u0004 בלבד? ומעירים: \u0003נראה למי דומה; דנין\u0004 ולמדין דבר שניתן ל\u0003מטה\u0004 מדבר שניתן ל\u0003מטה ואין דנין מטה מלמעלה.\u0004","אולם יש לטעון כנגד זה: \u0003אדרבה, דנין גופו מגופו\u0004 כלומר דנין מה שנאמר בגופו של שעיר מדבר שנאמר בגופו, \u0003ואין דנין גופו מעלמא\u0004 \u0005[מן העולם,\u0006 מדברים אחרים\u0005]!\u0006 \u0003תלמוד לומר: \"ועשה את דמו כאשר עשה לדם הפר\"\u0004 (ויקרא טז, טו), \u0003שאין תלמוד לומר \"כאשר עשה\",\u0004 שהרי לכאורה כל עשיותיו מפורשות שנית, \u0003ומה תלמוד לומר\u0004 בכל זאת \u0003\"כאשר עשה\" — שיהיו כל עשיותיו שוות,\u0004 אף בפרטי הדברים. ולכן \u0003כשם שלמטה בפר\u0004 מזה \u0003שבע, כך\u0004 הזאות \u0003למטה בשעיר — שבע.\u0004","\u0003למדנו\u0004 איפוא \u0003כמה למטה? בפר ובשעיר — שבע.\u0004 אולם \u0003למעלה בפר איני יודע כמה\u0004 מזים, \u0003והריני דן: נאמרו דמים למעלה בשעיר, ונאמרו דמים למעלה בפר, מה למעלה\u0004 שמזה \u0003בשעיר\u0004 הרי זו הזאה \u0003אחת\u0004 כמפורש, \u0003אף למעלה\u0004 שנאמרה \u0003בפר — אחת.\u0004","ודנים: \u0003או כלך לדרך זו: נאמרו דמים למטה בפר, ונאמרו דמים למעלה בפר. מה למטה בפר — שבע, אף למעלה בפר\u0004 יזה \u0003שבע\u0004 פעמים! ומעירים: \u0003נראה למי דומה? דנין\u0004 מתן \u0003מעלה\u0004 של פר ממתן \u0003מעלה\u0004 של השעיר, \u0003ואין דנין מעלה\u0004 של פר \u0003ממטה\u0004 שלו!","ודוחים: \u0003אדרבה\u0004 ההיפך מסתבר: \u0003דנין גופו\u0004 של פר \u0003מגופו\u0004 של פר, \u0003ואין דנין גופו מעלמא\u0004 (מן החוץ)! על כן \u0003תלמוד לומר\u0004 מן המקרא המפורש: \u0003\"ועשה את דמו כאשר עשה\u0004 לדם הפר\u0003\", שאין תלמוד לומר: \"כאשר עשה\",\u0004 שהרי אין הכתוב מלמד דברים חדשים, \u0003ומה תלמוד לומר: \"כאשר עשה\" — שיהיו כל עשיותיו שוות, כשם שלמטה בפר\u0004 מזה \u0003שבע\u0004 אף \u0003כך למטה בשעיר שבע. וכשם שלמעלה בשעיר — אחת, כך למעלה בפר\u0004 הזאה","נאמר במשנה שהיה מונה \u0003אחת, אחת ואחת ושתים. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: בשעת ההזאה היה הכהן מונה: \u0003אחת, אחת ואחת, אחת ושתים, אחת ושלש, אחת וארבע, אחת וחמש, אחת ושש, אחת ושבע,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 היה מונה \u0003אחת, אחת ואחת, שתים ואחת, שלש ואחת, ארבע ואחת, חמש ואחת, שש ואחת, שבע ואחת.\u0004","ומעירים: \u0003ולא פליגי\u0004 \u0005[נחלקו]\u0006 בענין זה לגוף הדבר, שמזה אחת למעלה ושבע למטה, אלא: \u0003מר כי אתריה ומר כי אתריה\u0004 \u0005[חכם זה כבמקומו, וחכם זה כבמקומו],\u0006 שבמקום אחד היו נוהגים למנות את המספר הקטן קודם, ובמקום אחר היו נוהגים לספור את המספר הגדול קודם.","ושואלים: \u0003דכולי עלמא מיהת\u0004 \u0005[לדעת הכל על כל פנים]\u0006 גם לר' מאיר וגם לר' יהודה \u0003הזאה ראשונה\u0004 שמזה אחת למעלה \u0003צריכה מנין עם כל אחת ואחת\u0004 מן ההזאות הבאות, שמונה אחת ואחת, אחת ושתים וכו', \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 מדוע אינו מונה את ההזאות למטה לעצמן? ודנו חכמים בדבר, \u0003ר' אלעזר אמר: שלא יטעה בהזאות,\u0004 שאם יספור למטה בלי לכלול את ההזאה הראשונה למעלה, יכול לחשוב בטעות שכלל את הראשונה ביניהן ויבוא להוסיף עוד אחת.","\u0003ר' יוחנן אמר: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004והזה באצבעו על פני הכפורת \u0003ולפני הכפרת יזה\"\u0004 (ויקרא טז, יד), \u0003שאין תלמוד לומר\u0004 פעם נוספת \u0003\"יזה\", ומה תלמוד לומר: \"יזה\" — לימד על הזאה ראשונה שצריכה מנין עם כל אחת ואחת\u0004 שצריך להזכיר את ההזאה שהזה כבר.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם]\u0006 בין שני ההסברים? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל כש\u0003לא מנה\u0004 את ההזאה הראשונה \u0003ולא טעה.\u0004 שלדעת ר' אלעזר אין בכך פגם, ולדעת ר' יוחנן לא יפה עשה, שהרי מצוה היא למנות את הראשונה.","שנינו במשנה ש\u0003יצא\u0004 הכהן \u0003והניחו\u0004 לדם הפר \u0003על כן הזהב שבהיכל\u0004 ודם השעיר על כן שני. ולדעת ר' יהודה היה רק כן אחד. ומעירים: \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת שקלים: \u0003ר' יהודה אומר: לא היו שופרות\u0004 (תיבות, קופות לכסף) \u0003לקיני חובה,\u0004 כלומר לזוג תורים או בני יונה שמביאים חטאת ועולה יחד לחובת היולדת ולאחרים, \u0003מפני\u0004 חשש \u0003התערובות.\u0004","ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 הכוונה\u0005]\u0006 במה שאמר \u0003מפני התערובות? אמר רב יוסף: מפני תערובת\u0004 קיני \u0003חובה\u0004 בקיני \u0003נדבה,\u0004 שיש לחשוש שמא יערבו את הכסף הניתן לקינים (אותו זוג יונים) של חובה שהם חטאת ועולה, באלה של קיני נדבה שהם זוג עולות ונמצאו פוסלים אותם במעשה הקרבן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ונעביד תרי\u0004 \u0005[ושנעשה שתי]\u0006 שופרות, שתי קופות, \u0003ונכתוב עלייהו\u0004 \u0005[ונכתוב עליהם]\u0006 \u0003הי\u0004 \u0005[איזו]\u0006 היא התיבה של קיני \u0003חובה והי\u0004 \u0005[ואיזו]\u0006 של \u0003נדבה?\u0004 ומשיבים: \u0003ר' יהודה\u0004"],["\u0003לית ליה\u0004 \u0005[אין לו]\u0006 \u0003כתיבה,\u0004 כלומר: לדעתו אין לסמוך על כתיבה שעל גבי דבר במקום שאפשר לטעות. \u0003דתנן\u0004 \u0005[\u0006שכן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' יהודה אומר: לא היה שם\u0004 בבית המקדש ביום הכיפורים \u0003אלא כן אחד בלבד\u0004 להנחת הדם. \u0003תרי מאי טעמא\u0004 \u0005[שני\u0006 כנים \u0005מה הטעם]\u0006 \u0003לא\u0004 היו עושים — \u0003משום דמחלפי\u0004 \u0005[שהם מתחלפים]\u0006 זה בזה, ושמא יקח דם השעיר במקום דם הפר. והרי אפשר \u0003ונעביד תרי\u0004 \u0005[ושנעשה שני\u0006 כנים\u0005]\u0006 \u0003וליכתוב עלייהו\u0004 \u0005[ושיכתוב עליהם]\u0006 \u0003הי\u0004 \u0005[איזה]\u0006 של \u0003פר והי\u0004 \u0005[ואיזה]\u0006 של \u0003שעיר. אלא,\u0004 על כרחך \u0003לר' יהודה לית ליה\u0004 \u0005[אין לו]\u0006 \u0003כתיבה,\u0004 שלדעתו אין כתיבה מועילה במקום שאפשר לטעות.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על מסקנא זו ממה ששנינו \u0003שלש עשרה שופרות\u0004 (קופות) \u0003היו במקדש, והיה כתוב עליהן:\u0004 על אחת \u0003תקלין חדתין\u0004 \u0005[שקלים חדשים],\u0006 שבהם היו נותנים את השקלים שהביאו בשנה זו כדינם. \u0003ותקלין עתיקין\u0004 \u0005[ושקלים ישנים]\u0006 של השנה שעברה, שמשום מה לא הגיעו לתעודתם בזמנן, \u0003וקינין\u0004 כלומר קרבנות חובה של זוג תורים או בני יונה, ועוד אחד של \u0003גוזלי עולה,\u0004 וקופה למי שרוצה להתנדב \u0003עצים,\u0004 וקופה למי שרוצה להתנדב \u0003לבונה,\u0004 וקופה של המתנדבים \u0003זהב לכפורת, וששה\u0004 נוספי שהיו מיועדים \u0003לנדבה\u0004 מכל הסוגים.","ומסבירים: \u0003תקלין חדתין\u0004 \u0005[שקלים חדשים]\u0006 \u0003— אלו שקלים של כל שנה ושנה\u0004 הבאים בזמנן, \u0003תקלין עתיקין\u0004 \u0005[ושקלים ישנים]\u0006 — \u0003מי שלא שקל אשתקד, ישקול לשנה הבאה. קינין — הן תורין\u0004 שמביאים לקרבן, \u0003גוזלי עולה — הן בני יונה, וכולן עולות, דברי ר' יהודה.\u0004 שהרי לדעתו לא היו עושים שופר לקיני חובה, שהם חטאת ועולה, מפני התערובות כאמור. על כל פנים משמע מכאן כי ר' יהודה סומך על הכתיבה שהיתה על כל קופה וקופה! ואם כן נשארו דברי ר' יהודה בחשש \"מפני התערובות\" צריכים לימוד.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]\u0006 מה שאמרו \"תערובות\" הוא \u0003גזירה משום חטאת שמתו בעליה.\u0004 שחטאת כזו דינה שהיא מתה, ויש לחשוש שמא מת בינתים אחד מן המנדבים לקופת קרבנות חטאת, ואם כן יש שם קרבן אחד שאינו ראוי. ושואלים: \u0003ומי חיישינן\u0004 \u0005[והאם חוששים אנו]\u0006 למותו של אדם שנדב? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003השולח חטאתו ממדינת הים\u0004 שמגיעה החטאת לאחר זמן \u0003— מקריבין אותה\u0004 חטאת עבורו \u0003בחזקת שהוא קיים\u0004 (חי) ואין חוששים שמא מת בינתיים. משמע שאין חוששים למיתה!","\u0003אלא\u0004 כך יש לומר: שחשש ר' יהודה \u0003משום חטאת שמתו בעליה ודאי.\u0004 שמא יתברר בודאות שאכן מת אחד מאלו שהכניסו כסף לחטאת העוף. ושואלים: והרי גם לזה יש תקנה: \u0003ונברור ארבעה זוזי\u0004 \u0005[זוזים]\u0006 שהם דמי קן אחד \u0003ונשדי במיא\u0004 \u0005[ונזרקם למים]\u0006 לאיבוד, ונאמר: שאותו כסף שהוצאנו הוא הוא הכסף שהיה של החטאת שמתו בעליה, \u0003והנך נישתרו\u0004 \u0005[וההם,\u0006 השאר, \u0005יותרו],\u0006 ונאמר שהתברר הדבר למפרע, שכסף זה היה המיועד לצורך זה. ומשיבים: \u0003ר' יהודה לית ליה\u0004 \u0005[אין לו]\u0006 דין זה של \u0003ברירה,\u0004 שלדעתו אין מקבלים את ההנחה שדבר שלא היה ברור בשעתו מתברר לאחר מעשה, ולכן אינו יכול לסמוך על תקנה זו.","ושואלים: \u0003מנא לן\u0004 \u0005[מניין לנו]\u0006 שזו אכן שיטת ר' יהודה? \u0003אילימא מהא\u0004 \u0005[אם תאמר מזו]\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הלוקח יין מבין הכותיים\u0004 (השומרונים) שאינם מעשרים כהלכה ויש לחשוש שהיין אינו מעושר, והיה זה \u0003ערב שבת עם חשכה\u0004 שאין לו זמן להפריש לפני השבת ולהניח כל חלק מופרש למקום הראוי לו — כך הוא עושה, אם היו אלה למשל מאה לוגין יין, \u0003עומד ואומר: שני לוגין שאני עתיד להפריש\u0004 לאחר השבת \u0003הרי הן\u0004 מעכשיו מוקדשין בקדושת \u0003תרומה\u0004 כי המידה הבינונית של תרומה היא אחד מחמישים, שני לוגין ממאה."],["\u0003עשרה\u0004 לוגין שאני עתיד להפריש יהיו \u0003מעשר ראשון,\u0004 ועוד עשירית מן השאר שהם \u0003תשעה\u0004 לוגין מתוך התשעים שנותרו יהיו \u0003מעשר שני. ומיחל\u0004 (ומחלל) מיד את המעשר השני על הכסף, שאותו הוא יעלה לאחר מכן לירושלים \u0003ושותה מיד.\u0004 ולאחר השבת כשיוציא מן התערובת את חלקי התרומה והמעשרות ויתנם לתוך כלי, אומרים אנו שכל מה שמוציא עכשיו וקורא לו שם תרומה או מעשר, הוברר למפרע שזהו היה החלק שהופרש מתחילה לצורך זה, ושאותו חלק ששתה היה חולין. אלו \u0003דברי ר' מאיר.\u0004"],["\u0003ר' יהודה ור' יוסי ור' שמעון אוסרין. אלמא\u0004 \u0005[מכאן]\u0006 שלדעת ר' יהודה \u0003אין ברירה.\u0004","ודוחים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מסיק אתה מסקנה זו? \u0003דילמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006 \u0003כדקתני טעמא\u0004 \u0005[כמו ששנוי\u0006 שם \u0005הטעם]\u0006 \u0003אמרו לו\u0004 חכמים אלו \u0003לר' מאיר: אי אתה מודה שמא יבקע הנוד\u0004 לפני שיוציא מן התערובת את חלקי התרומה והמעשרות וישפך הכל לפני הפרשה \u0003ונמצא שותה טבלים למפרע,\u0004 ואין איפוא לסמוך על הפרשה שעדיין לא נעשתה בפועל. \u0003ואמר להם:\u0004 אין אני חושש לכך, כי \u0003לכשיבקע\u0004 אכן תהיה בעיה, אולם אין אנו צריכים לחשוש לכגון זה. ואם כן, מכאן אין להוכיח שר' יהודה סבור שאין ברירה.","\u0003אלא\u0004 ממקום אחר נוכיח שלדעת ר' יהודה אין ברירה, \u0003מדתני\u0004 \u0005[מ\u0006מה \u0005ששנה\u0006 החכם\u0005]\u0006 \u0003איו. דתני\u0004 \u0005[ששנה\u0006 החכם\u0005]\u0006 \u0003איו: ר' יהודה אומר: אין אדם מתנה\u0004 בעירוב \u0003על שני דברים כאחד.\u0004 כלומר: אין אדם רשאי לעשות בערב שבת עירוב תחומין לשני כיוונים שונים, מתוך כוונה שלמחרת אם יגיעו שני חכמים לשני הכיוונים יחליט אז את דברי איזה חכם רצונו לשמוע ויברר לאיזה משני הכיוונים תחום שבת שלו.","\u0003אלא,\u0004 דבר זה הותר לו: שאם חושש לביאת חכם אחד, אלא שאינו יודע לאיזה צד יבוא, מערב לשני כיוונים ומתנה: \u0003אם בא חכם\u0004 זה \u0003למזרח — עירובו למזרח,\u0004 ואם יבוא החכם \u0003למערב — עירובו למערב. אבל לכאן ולכאן — לא.\u0004","\u0003והוינן בה\u0004 \u0005[והיינו עוסקים\u0006 ומתקשים \u0005בה]\u0006 במקומה בסוגיה זו: \u0003מאי שנא\u0004 \u0005[במה שנה]\u0006 \u0003לכאן ולכאן\u0004 ש\u0003לא,\u0004 מפני שהוא סבור ש\u0003אין ברירה,\u0004 ואין אומרים שהוברר הדבר לאחר מעשה שהמקום בו הלך הוא המקום שבחר מתחילה.","אולם אם כן \u0003למזרח ומערב נמי\u0004 \u0005[גם כן]\u0006 \u0003אין ברירה,\u0004 ומדוע אם חושש לביאת חכם אחד ומתנה שאם בא חכם זה למזרח יהיה עירובו למזרח — כשר עירובו למזרח, אפילו לדעת ר' יהודה?","\u0003ואמר ר' יוחנן: כשכבר בא חכם.\u0004 כלומר: כאן מדובר במקרה שהחכם כבר הגיע ביום שישי מבעוד יום לאחד מצידי העיר, אלא שהמניח את העירוב איננו יודע עדיין לאיזה צד הגיע, ולכן איננו יודע לאיזה צד לערב. ואם כן, אכן חל העירוב לצד אחד בלבד, ובשעת הנחת העירוב כבר היה צד זה מוחלט וקבוע, אלא שהמניח את העירוב לא ידע על כך, ובמקרה זה מודה ר' יהודה. הרי שבכלל לדעת ר' יהודה אין ברירה, ולפי זה אפשר להסביר את חששו מפני התערובת בשופרות של קיני חובה.","ושואלים: \u0003והשתא דאמרינן\u0004 \u0005[עכשיו שאמרנו]\u0006 והוכחנו כי \u0003לר' יהודה אין ברירה, הא\u0004 \u0005[הרי]\u0006 \u0003כתיבה\u0004 והסתמכות על הדברים הכתובים \u0003אית ליה\u0004 \u0005[יש לו]\u0006 כמו שהוכחנו מענין השופרות, אם כן \u0003יום הכפורים נמי\u0004 \u0005[גם כן]\u0006 \u0003נעביד תרי\u0004 \u0005[נעשה שני\u0006 כנים\u0005]\u0006 \u0003ונכתוב עלייהו\u0004 \u0005[עליהם]\u0006 איזהו לדם הפר ואיזהו לדם השעיר!","ומשיבים: \u0003משום חולשא\u0004 \u0005[חולשתו]\u0006 של ה\u0003כהן\u0004 ה\u0003גדול\u0004 שצם וכל עבודת היום עליו \u0003לאו אדעתיה\u0004 \u0005[אין דעתו\u0006 לכך\u0005]\u0006 והוא עשוי להתבלבל. \u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך]\u0006 שאנו חוששים כאן מפני חולשתו של הכהן הגדול, הלא \u0003בלא כתיבה נמי\u0004 \u0005[גם כן]\u0006 אין מקום לטעות, שכן \u0003האי\u0004 \u0005[\u0006מזרק \u0005זה]\u0006 שמקבל בו דם הפר הוא \u0003נפיש\u0004 \u0005[גדול]\u0006 \u0003והאי\u0004 \u0005[וזה]\u0006 של השעיר \u0003זוטר\u0004 \u0005[קטן].\u0006","\u0003וכי תימא לא מקביל ליה כוליה\u0004 \u0005[ואם תאמר\u0006 שמא \u0005אינו מקבל את\u0006 דם הפר \u0005כולו]\u0006 אלא רק מקצתו, ונמצא ששני המזרקים שווים בגודלם. אולם, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה: השוחט צריך שיקבל את כל דמו של\u0004 ה\u0003פר, שנאמר: \"ואת כל דם הפר ישפך אל יסוד מזבח העלה\"\u0004 (ויקרא ד, ז).","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003דילמא משתפיך מיניה\u0004 \u0005[שמא ישפך ממנו]\u0006 ועל ידי כך משתווה כמות הדם במזרקים, אולם גם אז אין לטעות \u0003האי חיור\u0004 \u0005[זה\u0006 דם השעיר, \u0005לבן,\u0006 בהיר\u0005]\u0006 ביחס לדם הפר, \u0003והאי סומק\u0004 \u0005[וזה\u0006 דם הפר \u0005אדום\u0006 וכהה ממנו\u0005].\u0006 \u0003אלא,\u0004 על כרחך אתה צריך לומר כי \u0003משום חולשא\u0004 \u0005[חולשתו]\u0006 של ה\u0003כהן גדול לאו אדעתיה\u0004 \u0005[אין דעתו\u0006 לכך\u0005].\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 גם אם יכתוב, לא יועיל הדבר, ש\u0003משום חולשתו דכהן גדול לאו אדעתיה\u0004 \u0005[אין דעתו\u0006 לכך\u0005].\u0006","מסופר: \u0003ההוא דנחית קמיה\u0004 \u0005[\u0006אדם \u0005אחד ירד\u0006 להתפלל לפני התיבה \u0005לפני]\u0006 \u0003רבא\u0004 ביום הכיפורים, והיה אומר בשעת התפילה את סדר עבודת הכהן הגדול ביום הכיפורים, ו\u0003אמר: יצא והניחו על כן שני שבהיכל, נטל דם הפר\u0004 ממקומו, \u0003והניח\u0004 במקומו \u0003דם השעיר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003וחדא\u0004 \u0005[ואחת]\u0006 כשיטת \u0003ר' יהודה?!\u0004 שכדברי חכמים היה כל אחד מאלה על כן מיוחד בהיכל, וכדברי ר' יהודה היה צריך ליטול קודם את דם הפר ואחר כך להניח את דם השעיר. אלא \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן שיהא הדבר כדברי חכמים לגמרי: \u0003הניח דם השעיר\u0004 על הכן המיוחד לו, \u0003ונטל דם הפר\u0004 מן הכן השני\u0003.\u0004","נאמר במשנה כי \u0003הזה\u0004 הכהן \u0003ממנו,\u0004 מן הדם \u0003על הפרכת כנגד ארון מבחוץ. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \"וכיפר על הקודש מטומאות בני ישראל ומפשעיהם לכל חטאתם \u0003וכן יעשה לאהל מועד\u0004 השוכן איתם בתוך טומאותם\" (ויקרא טז, טז), פסוק זה \u0003מה תלמוד לומר?\u0004 — \u0003כשם שמזה לפני לפנים\u0004 בקודש הקדשים \u0003כך מזה בהיכל\u0004 (\"אוהל מועד\") על הפרוכת.","ועוד: \u0003מה\u0004 בהזאתו \u0003לפני לפנים\u0004 הזאה \u0003אחת למעלה ושבע למטה מדם הפר — כך מזה בהיכל. וכשם שלפני לפנים\u0004 מזה \u0003אחת למעלה ושבע למטה מדם השעיר, כך מזה\u0004 גם \u0003בהיכל.\u0004 נאמר שם עוד: \u0003\"השכן אתם בתוך טמאתם\"\u0004 (ויקרא טז, טז) — דבר זה בא ללמדנו כי \u0003אפילו בשעה שהן טמאים — שכינה עמהם.\u0004","אגב הזכרת פסוק זה, מביאים מה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מינא\u0004 \u0005[מין אחד]\u0006 \u0003לר' חנינא:\u0004"],["\u0003השתא ברי טמאים אתון\u0004 \u0005[עכשיו בודאי טמאים אתם],\u0006 שנאמר על עם ישראל: \u0003\"טמאתה בשוליה\"\u0004 (איכה א, ט) ואין שכינה שרויה על ישראל כשהם טמאים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חנינא: \u0003תא חזי מה כתיב בהו\u0004 \u0005[בוא וראה מה נאמר בהם]\u0006 בישראל — \u0003\"השכן אתם בתוך טמאתם\"\u0004 (ויקרא טז, טז), ללמד: \u0003אפילו בזמן שהן טמאין שכינה שרויה ביניהן.\u0004","לגופה של ההלכה שהובאה קודם, שלמדים בהיקש הזאה אחת מדם הפר למעלה מן השעיר ושבע למטה של שעיר מן הפר וחוזרים ולומדים מהזאות אלו בהיקש אף את הזאת פרוכת בהיכל, ועל כך מקשים: \u0003וכי דבר הלמד בהיקש,\u0004 כלומר: דבר שאינו כתוב במקרא במפורש אלא נלמד בדרך ההיקש, האם הוא \u0003חוזר ומלמד בהיקש?\u0004 והרי כלל בידינו, שבהלכות קדשים דבר הלמד בהיקש, אינו חוזר ומלמד בהיקש!","ומשיבים: ההיקש הראשון לא היה היקש גמור כי \u0003האי\u0004 \u0005[זה]\u0006 לימוד זה שלמדנו לגבי אחת למעלה ושבע למטה, \u0003הימנו\u0004 מן ההיקש \u0003ודבר אחר הוא\u0004 נלמד, שהרי עיקר הדברים שיש מתן מעלה ומטה גם בפר וגם בשעיר נאמר בשניהם במפורש, ולא הוצרכנו ללמוד אלא לגבי מספר ההזאות, ולימוד כעין זה \u0003לא הוי\u0004 \u0005[איננו נחשב]\u0006 ל\u0003היקש\u0004 לענין זה שלא תוכל לחזור וללמוד ממנו בהיקש.","ומקשים עוד: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 כי היקש שלמדים גם מדבר אחר \u0003לא הוי\u0004 \u0005[איננו נחשב]\u0006 \u0003היקש\u0004 לענין זה. \u0003אלא למאן דאמר הוי\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006 שאף זה \u0005קרוי]\u0006 \u0003היקש, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003מקומות הוא דגמרי מהדדי.\u0004 כלומר: יש להבין את דרך הלימוד באופן זה: לא שלמדו דין הפר מדין השעיר, ודין מתן דם של פר מבחוץ מדין מתן דם של פר בפנים, אלא: ההיקש הראשון בא להשוות את מתן דם הפר ודם השעיר, וההיקש השני בא להשוות את המקומות — שמזה בחוץ כדרך שמזה בפנים, ואם כן אין ההיקשים למדים בעצם זה מזה.","\u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תירוץ אחר: הזאת \u0003חוץ\u0004 מהזאת \u0003פנים בחדא זימנא גמר\u0004 \u0005[בפעם אחת למד],\u0006 שהלימוד בהיקש כולל לא רק את דם הפר ואת דם השעיר, אלא את כל דרכי נתינת הדם בין בפנים בין בחוץ, ואין כאן שני היקשים הלמדים זה מזה אלא היקש אחד מורכב.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003כשהוא מזה\u0004 מן הדם \u0003אינו מזה על הפרוכת\u0004 ממש, \u0003אלא כנגד הפרוכת. אמר ר' אלעזר בר' יוסי: אני ראיתיה\u0004 את הפרוכת \u0003ברומי\u0004 שלאחר שנעשה לו נס וריפא את בת קיסר רומי, ניתנה לו רשות לראות את גנזי הקיסר וליטול מהם כפי רצונו והיו שם כלי המקדש שנטלו הרומאים וביניהם הפרוכת, \u0003והיו עליה\u0004 על הפרוכת \u0003כמה טיפי דמים של פר ושעיר של יום הכפורים.\u0004 הרי שהיו מזים ממש על הפרוכת!","ושואלים: מניין לו ששל פר ושעיר של יום הכיפורים היו המתנות? \u0003ודילמא\u0004 \u0005[ושמא]\u0006 מתנות אלה של \u0003פר העלם דבר של צבור\u0004 או של \u0003שעירי עבודה זרה הוו\u0004 \u0005[היו]\u0006 אותן טיפות, שהרי אף מדמם מזים על הפרוכת!","ומשיבים: \u0003דחזא דעבידי\u0004 \u0005[שראה שהיו\u0006 המתנות \u0005עשויות]\u0006 \u0003כסדרן\u0004 טיפה אחר טיפה וצורה זו של הזאה נעשית רק במתנות של יום הכיפורים. \u0003ותנן נמי\u0004 \u0005[ושנינו\u0006 במשנה \u0005גם כן]\u0006 \u0003גבי פר העלם דבר של צבור כי האי גוונא\u0004 \u0005[בדומה לזה]:\u0006 \u0003כשהוא מזה לא היו\u0004 הדמים \u0003נוגעין בפרוכת, ואם נגעו — נגעו.\u0004","\u0003אמר ר' אלעזר בר' יוסי: אני ראיתיה\u0004 את הפרוכת \u0003ברומי, והיו עליה כמה טיפי דמים של פר העלם דבר של צבור, ושעירי עבודה זרה.\u0004 ושואלים: ומניין לו שדמים אלה היו? \u0003ודילמא\u0004 \u0005[ושמא]\u0006 של \u0003פר ושעיר של יום הכפורים נינהו\u0004 \u0005[הם]?\u0006 ומשיבים: \u0003דחזנהו דעבידי\u0004 \u0005[שראה אותם שעשויים]\u0006 \u0003שלא כסדרן,\u0004 והבין שהם מן המתנות של חטאות הציבור, שאינן ניתנות כסדרן.","התעוררה הבעיה, אם \u0003נתערבו לו דמים בדמים,\u0004 דם הפר בדם השעיר, לפני שסיים בנתינת המתנות כולן, מה יעשה? \u0003אמר רבא: נותן\u0004 מן התערובת \u0003אחת למעלה ושבע למטה ועולה לו לכאן ולכאן,\u0004 שהרי נתן משניהם.","\u0003אמרוה קמיה\u0004 \u0005[אמרו\u0006 תשובה זו \u0005לפני]\u0006 \u0003ר' ירמיה\u0004 בארץ ישראל, \u0003אמר: בבלאי טפשאי\u0004 \u0005[בבליים טפשים],\u0006 \u0003משום דדיירי בארעא דחשוכא אמרי שמעתא דמחשכן\u0004 \u0005[שהם גרים בארץ חשוכה,\u0006 נמוכה, \u0005הם אומרים הלכות חשוכות]\u0006 ובלתי הגיוניות! \u0003הא\u0004 \u0005[הרי]\u0006 בנתינתו מן התערובת של דם הפר והשעיר \u0003קא יהיב\u0004 \u0005[הוא נותן]\u0006 לפי זה את המתנות \u0003למעלה\u0004 של ה\u0003שעיר מקמיה\u0004 \u0005[לפני]\u0006 שנותן מתנות \u0003מטה\u0004 של \u0003פר,\u0004 והרי \u0003התורה אמרה: \"וכלה מכפר את הקדש\"\u0004 (ויקרא טז, כ), כלומר: \u0003כלה דם הפר\u0004 בנתינת מעלה ומטה ורק \u0003אחר כך כלה דם השעיר!\u0004","\u0003אלא אמר ר' ירמיה:\u0004 כך הוא עושה: \u0003נותן אחת למעלה ושבע למטה לשם\u0004 מתן דם של \u0003הפר\u0004 שהרי דם הפר מעורב בדם זה, \u0003וחוזר ונותן אחת למעלה ושבע למטה לשם\u0004 מתן דם \u0003השעיר\u0004 ואפילו שהדמים מעורבים ובנתינתו לשם הפר הריהו נותן גם מדם השעיר — כיון שלא התכוין אלא לדם הפר, הרי זה כאילו לא נתן כלל מדם השעיר.","ועוד שאלו: אם \u0003נתערבו לו דמים\u0004 של הפר \u0003בדמים\u0004 של העיר \u0003במתנות האחרונות\u0004 שנותן בהיכל, מה יעשה? \u0003סבר\u0004 \u0005[חשב]\u0006 \u0003רב פפא\u0004 שישב \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא למימר\u0004 \u0005[לומר]:\u0006 \u0003נותן שבע למטה לשם פר ולשם שעיר, וחוזר ונותן אחת למעלה לשם שעיר.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: עד השתא קרו לן טפשאי\u0004 \u0005[עד עכשיו קראו לנו\u0006 בבליים \u0005טפשים]\u0006 \u0003והשתא טפשאי דטפשאי\u0004 \u0005[ועכשיו\u0006 יקראו לנו \u0005טפשים שבטפשים]\u0006 \u0003דקא מגמרינן להו ולא גמירי\u0004 \u0005[שמלמדים אותם ואינם לומדים],\u0006 שהרי כנגד דבריך אפשר לטעון מה שאמר כבר ר' ירמיה: \u0003והא קא יהיב\u0004 \u0005[והרי הוא נותן]\u0006 מתנות \u0003מטה\u0004 של \u0003שעיר מקמי\u0004 \u0005[מלפני]\u0006 מתנות \u0003מעלה\u0004 של \u0003שעיר, והתורה אמרה: תן למעלה, ואחר כך למטה!\u0004"],["\u0003אלא אמר רבא: נותן שבע למטה לשם פר, וחוזר ונותן אחת למעלה ושבע למטה לשם שעיר.\u0004","ועוד שאלו: אם \u0003נתערבו לו כוסות\u0004 המכילות את דם הפר \u0003בכוסות\u0004 המכילות את דם השעיר — \u0003נותן\u0004 מכוס אחת אחת למעלה ושבע למטה, \u0003וחוזר ונותן\u0004 מתנות אלו בפעם השניה,","\u0003וחוזר\u0004 שוב \u0003ונותן\u0004 מן הכוס הראשונה פעם נוספת, שהם בסך הכל \u0003שלשה פעמים,\u0004 ועל ידי כך יוצא ידי חובה. שהרי אם הכוס הראשונה של פר היתה והשניה של השעיר — יצא ידי חובה בנתינה ראשונה ושניה. ואם הכוס הראשונה של שעיר היתה, נמצא שהקדים מתן דם שעיר לפר, והרי זה כאילו לא עשה כלום. ולכן כשנותן מכוס שניה שהיא של פר, ונותן בשלישית שוב משל שעיר — יצא ידי חובה במתנה שניה ושלישית.","ועוד שואלים: אם \u0003מקצת\u0004 מן ה\u0003דמים נתערבו לו\u0004 אלו באלו, \u0003ומקצת דמים לא נתערבו לו,\u0004 כגון שנשפך ונתערב מקצת הדם בכלי שלישי, \u0003פשיטא\u0004 \u0005[פשוט]\u0006 ברור לנו: \u0003כי יהיב\u0004 \u0005[כאשר הוא נותן] —\u0006 \u0003מודאין יהיב\u0004 \u0005[\u0006מדמים \u0005הודאיים\u0006 הברורים \u0005הוא נותן],\u0006","\u0003מיהו\u0004 \u0005[מכל מקום]\u0006 יש לשאול שאלה זו: \u0003הנך\u0004 \u0005[אלו]\u0006 השאר, הכלי או הכלים בהם יש דם מעורב, מה דינם? האם יש לומר כי \u0003שירים הוו\u0004 \u0005[הם],\u0006 ושיירי הדם \u0003ליסוד\u0004 המזבח \u0003אזלי\u0004 \u0005[הולכים],\u0006 כדין שיירי דם החטאת, \u0003או דילמא\u0004 \u0005[שמא]\u0006 דמי תערובת זו \u0003דחויין הוו\u0004 \u0005[הם],\u0006 שהרי המתנות הראשונות לא נתנו מכלי זה \u0003ואזלו\u0004 \u0005[והולכים,\u0006 נשפכים\u0005]\u0006 \u0003לאמה\u0004 תעלת המים שבמקדש, שדרכה נשפך כל הלכלוך שבעזרה לנחל קדרון.","\u0003אמר רב פפא: אפילו למאן דאמר\u0004 \u0005[\u0006לשיטת \u0005מי שאומר]\u0006 \u0003כוס אחד עושה חבירו שירים.\u0004 כלומר, אם קיבל את הדם בשתי כוסות, הדם שבכוס השניה נחשב כשיריים לכוס הראשונה, הרי \u0003הני מילי היכא דאי בעי למיתב מצי יהיב\u0004 \u0005[דברים אלה\u0006 אמורים \u0005היכן שאם היה רוצה לתת\u0006 מן השני היה \u0005יכול לתת]\u0006 שהרי שתי הכוסות מלאות מדם הקרבן. \u0003אבל האי\u0004 \u0005[זה]\u0006 דם התערובת, \u0003דאי בעי למיתב לא מצי יהיב\u0004 \u0005[שאם היה רוצה לתת לא היה יכול לתת] —\u0006 \u0003לא,\u0004 ולכן בודאי דחוי הוא.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא: אדרבה\u0004 (להיפך) צריך לטעון: \u0003אפילו למאן דאמר\u0004 \u0005[\u0006לדעת \u0005מי שאומר]\u0006 כי כשקיבל את הדם בשתי כוסות הרי \u0003כוס אחד עושה\u0004 את \u0003חבירו דחוי — הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא, \u0003דדחיה\u0004 \u0005[שדחה]\u0006 את הכוס השניה \u0003בידים,\u0004 על ידי מעשה של ממש, \u0003אבל היכא\u0004 \u0005[היכן]\u0006 ש\u0003לא דחיה\u0004 \u0005[דחה אותם]\u0006 \u0003בידים,\u0004 שהרי לא נעשתה פעולה מיוחדת של דחיה אלא מעצמו התברר ששיריים הם — \u0003לא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003למעלה\u0004 במקרא \u0003הוא אומר:\u0004 \"ולקח הכהן מדם החטאת באצבעו ונתן על קרנות מזבח העולה \u0003ואת דמו ישפך\u0004 אל יסוד מזבח העולה\" (ויקרא ד, כה) \u0003ולמטה הוא אומר:\u0004 \"ולקח הכהן מדמה באצבעו ונתן על קרנות מזבח העולה \u0003ואת כל דמה ישפך\u0004 אל יסוד המזבח\" (ויקרא ד, ל), שמשינוי הלשון (עם או בלי המילה \"כל\") למדים:","\u0003מניין לחטאת שקבל את דמה בארבע כוסות, ונתן\u0004 מכל אחת מהן, \u0003מזה\u0004 הזאה \u0003אחת, ומזה אחת\u0004 וכך נתן ארבע מתנות מכולן, שכל הכוסות \u0003כולן נשפכין ליסוד\u0004 כדין שיריים \u0003— תלמוד לומר: \"ואת כל דמה ישפך\"\u0004 (ויקרא ד, ל).","\u0003יכול אפילו נתן ארבע מתנות\u0004 (הזאות) \u0003מאחת מהן\u0004 יישפכו כל השאר ליסוד כדין שיריים — \u0003תלמוד לומר: \"ואת דמו ישפך\"\u0004 משמע: ולא את כל הדם, אלא \u0003הוא,\u0004 אותה כוס שממנה נתן למזבח את השיריים — \u0003נשפך ליסוד\u0004 כשיריים, \u0003והן,\u0004 שאר הכוסות — \u0003נשפכין לאמה. ר' אליעזר בר' שמעון אומר: מניין לחטאת שקבל דמה בארבע כוסות ונתן ארבע מתנות מאחד מהן שכולן נשפכין ליסוד — תלמוד לומר: \"ואת כל דמה ישפך\".\u0004","ושואלים: \u0003ולר' אליעזר בר' שמעון, הא כתיב\u0004 \u0005[הרי נאמר]\u0006 גם כן: \u0003\"ואת דמו ישפך\"\u0004 וכיצד מבין הוא שינוי זה? \u0003אמר רב אשי:\u0004 מה שנאמר: \"את דמו\" בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שירים שבצואר\u0004 ה\u0003בהמה,\u0004 שאם לאחר קבלת הדם יצא עוד דם מן הצואר — דם זה ודאי אינו נשפך אל יסוד המזבח, אלא לתעלה (אמה) שבמקדש.","שנינו במשנה כי לאחר שנתן את המתנות על הפרוכת, \u0003עירה הכהן את דם הפר לתוך דם השעיר.\u0004 ומעירים: \u0003תנן כמאן דאמר\u0004 \u0005[שנינו\u0006 במשנתנו איפוא כשיטת \u0005מי שאמר]:\u0006 \u0003מערבין\u0004 את שני מיני הדם כדי לתת \u0003לקרנות\u0004 מזבח הפנימי, ואין נותנים כל אחד לחוד. \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו תנאים אחרונים בדבר: \u0003ר' יאשיה ור' יונתן; חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: מערבין\u0004 את הדם לצורך מתנה על קרנות המזבח, \u0003וחד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: אין מערבין.\u0004","ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 נוכיח כי \u0003ר' יאשיה הוא\u0004 התנא ש\u0003אמר\u0004 ש\u0003מערבין\u0004 את הדם, כי שיטתו בכלל היא: שבכל מקום שנזכרים שני דברים כאחד \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא כתיב\u0004 \u0005[נאמר]\u0006 בהם במפורש לשון \u0003\"יחדיו\"\u0004 — \u0003כמאן דכתיב\u0004 \u0005[כמו שנאמר]\u0006 \u0003\"יחדיו\" דמי\u0004 \u0005[נחשב]\u0006 והכוונה היא לשניהם יחד, עד שיפרש לך הכתוב שכל אחד מהם לחוד, ואילו ר' יונתן סבור להיפך, שבדברים הנאמרים יחד הכוונה היא לכל אחד לחוד עד שיהיה כתוב בהם במפורש לשון \"יחדיו\". ואם כן, ר' יאשיה לשיטתו, מאחר שנאמר: \"ולקח מדם הפר ומדם השעיר\", הרי שיש לתת יחד את דם הפר והשעיר.","ודוחים: מכאן אין להוכיח כי \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהתנא שאמר מערבן \u0003ר' יונתן הוא, שאני הכא\u0004 \u0005[שונה כאן]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אחת\"\u0004 משמע: מתנה אחת נותנים ולא שתים, ובהכרח שיש לערב את הדם כדי שלא תהיה יותר מנתינה אחת.","ומעירים: \u0003תניא דלא כשנויין\u0004 \u0005[שנויה\u0006 ברייתא \u0005שלא כתירוצנו],\u0006 אלא כפי שהנחנו מתחלה. ששנינו: נאמר: \"ויצא אל המזבח אשר לפני ה' וכפר עליו \u0003ולקח מדם הפר ומדם השעיר\u0004 ונתן על קרנות המזבח סביב\" (ויקרא טז, יח) ללמד: \u0003שיהיו\u0004 דם הפר והשעיר \u0003מעורבין,\u0004 אלו \u0003דברי ר' יאשיה,\u0004"],["\u0003ר' יונתן אומר:\u0004 נותן \u0003מזה,\u0004 מדם הפר, \u0003בפני עצמו\u0004 ונותן \u0003מזה,\u0004 מדם השעיר, \u0003בפני עצמו\u0004 ואינו מערבם. \u0003אמר לו ר' יאשיה: והלא כבר נאמר:\u0004 \"וכיפר אהרן על קרנותיו \u0003אחת\u0004 בשנה מדם חטאת הכיפורים\" (שמות ל, י), משמע: אין נותנים פעמיים!","\u0003אמר לו ר' יונתן: הלא כבר נאמר: \"מדם הפר ומדם השעיר\"\u0004 (ויקרא טז, יח) משמע: כל אחד לעצמו. \u0003אם כן למה נאמר \"אחת\" — לומר לך: אחת ולא שתים מדם הפר, אחת ולא שתים מדם השעיר,\u0004 שמכל אחד מהם נותן רק מתנה אחת. הרי שנחלקו בכך באמת ר' יאשיה ור' יונתן.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 נאמר: \u0003\"ולקח מדם הפר ומדם השעיר\"\u0004 (ויקרא טז, יח) — מלמד \u0003שיהיו\u0004 דמי הפר ודמי השעיר \u0003מעורבין זה בזה. אתה אומר שיהיו מעורבין זה בזה או אינו אלא מזה בפני עצמו ומזה בפני עצמו? תלמוד לומר: \"אחת\".\u0004 ומעירים: \u0003וסתמא\u0004 \u0005[וסתמה]\u0006 של ברייתא זו, שנאמרה סתם בלא שם חכם, \u0003כ\u0004שיטת \u0003ר' יאשיה\u0004 היא, שאמר מערבין, וכן משנתנו.","שנינו במשנה כי לאחר שעירה את דם הפר לתוך דם השעיר \u0003נתן\u0004 שוב \u0003את\u0004 הדם מן המזרק \u0003המלא\u0004 אל תוך המזרק ה\u0003ריקן\u0004 כדי לערב יפה את הדמים. אגב ענין זה מביאים מה ש\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רמי בר חמא מרב חסדא: הניח מזרק בתוך מזרק, וקבל בו\u0004 במזרק הפנימי \u0003את הדם, מהו?\u0004 האם לומר כי \u0003מן במינו חוצץ\u0004 ונמצא שהכהן לא קיבל בעצמו את הדם, שהרי היתה חציצה בינו לבין הכלי על ידי המזרק החיצוני, \u0003או\u0004 שמא מין במינו \u0003אינו חוצץ\u0004 ושניהם נחשבים כדבר אחד!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003תניתוה\u0004 \u0005[כבר שניתם אותה]\u0006 את התשובה לשאלה זו, שהרי שנינו במשנתנו: \u0003\"נתן את המלא בריקן\". מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה: ש\u0003הושיב מזרק מלא לתוך מזרק ריקן.\u0004","ודוחים: \u0003לא,\u0004 הכוונה היא ש\u0003עירה מזרק מלא לתוך מזרק ריקן.\u0004 אמר לו: אולם דבר זה אינו צריך, \u0003הא תנא ליה רישא\u0004 \u0005[הרי כבר שנה אותו בתחילה],\u0006 שהרי שנינו: \u0003עירה דם הפר לתוך דם השעיר,\u0004 ואם כן, מה ששנינו \"נתן את המלא בריקן\" — ודאי הכוונה לכלי בתוך כלי! ודוחים: אין הדבר כן, כי יש צורך לערות בשנית את המלא בריקן, \u0003כדי לערבן יפה יפה,\u0004 ששופך מכלי אחד לחבירו, וחוזר ושופך מן התערובת לכלי האחר, כדי שיתערבו על ידי כך יפה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 פתרון לשאלה זו, ממה ששנינו: \u0003היה עומד\u0004 הכהן בשעת העבודה \u0003על גבי כלי, או על גבי רגל חבירו — פסול,\u0004 לפי שהכהן צריך לעמוד על רצפת הבית עצמה בשעת עבודה. וכיון שנאמר שם שרגל חבירו חוצצת, משמע שמין במינו חוצץ! ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רגל דלא מצי מבטיל ליה\u0004 \u0005[שאינו יכול לבטל אותה]\u0006 שאין לומר שרגל חבירו בטלה לגבי רגלו שלו, אולם בכלי ניתן לומר כי כלי אחד בטל לגבי כלי אחר.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 \u0003הכי בעי מיניה\u0004 \u0005[כך שאל ממנו]\u0006 רמי בר חמא מרב חסדא, לא מבחינת חציצה, אלא מצד אחר: האם \u0003דרך שירות\u0004 בקודש \u0003בכך,\u0004 כאשר מניח כלי בתוך כלי, \u0003או אין דרך שירות בכך,\u0004 וכששירת בדרך זו — פסול הוא? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר: \u0003\"את כל כלי השרת אשר ישרתו בם בקדש\"\u0004 (במדבר ד, יב), ומכאן נדייק: \u0003שני כלים\u0004 (\"כלי\") \u0003ושירות אחת\u0004 (\"השרת\"), משמע שדרך שירות היא בכך.","ועוד שאלה \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רמי בר חמא מרב חסדא,\u0004 באותם נושאים: \u0003הניח סיב\u0004 ספוגי הגדל סביב הדקל \u0003בתוך המזרק, וקבל בו\u0004 דרך הסיב \u0003את הדם,\u0004 באופן שהדם מחלחל דרכו לתוך המזרק, \u0003מהו?\u0004 האם נאמר כי \u0003מין בשאינו מינו חוצץ\u0004 ולכן אין זו קבלה, \u0003או\u0004 שמא \u0003אינו חוצץ\u0004 והטעם — \u0003כיון\u0004 שהדם \u0003מחלחל\u0004 דרכו — \u0003לא חייץ\u0004 \u0005[אינו חוצץ],\u0006 \u0003או דילמא לא שנא\u0004 \u0005[שמא אינו שונה],\u0006 שכיון שיש דבר נוסף בכלי הרי הוא נחשב כחציצה, גם אם הדם עדיין מחלחל דרכו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא בתשובה: \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה לגבי קידוש מי חטאת (מים המעורבים באפר פרה אדומה), שאם היה ספוג מונח בתוך שוקת המים, הרי המים שבספוג פסולים להזות מהם, וכיצד יעשה? \u0003זולף\u0004 (מזה) מן המים \u0003והולך עד שמגיע לספוג.\u0004 על כל פנים למדים אנו מכאן כי עצם מציאותו של הספוג בשוקת אין בה חציצה לגבי המים שבשוקת, אף על פי שהוא עצמו אינו ראוי להזאה! ודוחים: מכאן אין להוכיח, כי \u0003שאני מיא דקלישי\u0004 \u0005[שונים מים שהם קלושים]\u0006 שבודאי מחלחלים היטב בתוך הספוג, אבל דם שהוא סמיך יותר, שמא אינו מחלחל כל צרכו בסיב.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 \u0003הכי פשט ליה\u0004 \u0005[כך פתר לו]\u0006 רב חסדא את הבעיה ביחס להנחת סיב במזרק: אם במזרק שמקבל בו \u0003דם\u0004 הניחו — \u0003כשר\u0004 כי הדם עובר, מחלחל, ואין הסיב חוצץ. אולם \u0003בקומץ\u0004 של מנחה שצריך לקדשו בכלי מיד לאחר מעשה הקמיצה ואם נתן סיב בכלי ועליו הניח את הקומץ — \u0003פסול.\u0004 כי קומץ המנחה הוא מבצק, ואינו עובר דרך הסיב, והריהו לפיכך חציצה של ממש."],["נאמר: \u0003\"ויצא אל המזבח אשר לפני ה'\u0004 וכיפר עליו, ולקח מדם הפר ומדם השעיר ונתן על קרנות המזבח סביב\u0003\"\u0004 (ויקרא טז, יח) מזבח זה \u0003זה מזבח הזהב,\u0004 שהרי המזבח החיצוני אינו \"לפני ה'\". \u0003התחיל מחטא\u0004 (מזה) מן הדם, \u0003ויורד, מהיכן הוא מתחיל — מקרן מזרחית צפונית,\u0004 ומשם הולך לקרן \u0003צפונית מערבית,\u0004 ולאחריה לקרן \u0003מערבית דרומית,\u0004 ואחר כך לקרן \u0003דרומית מזרחית.\u0004 וסימן לדבר: \u0003מקום\u0004 אותה קרן \u0003שהוא מתחיל\u0004 להזות בה \u0003בחטאת על מזבח החיצון,\u0004 שהיא קרן דרומית מזרחית — \u0003משם היה גומר על מזבח הפנימי.\u0004","\u0003ר' אליעזר אומר:\u0004 לא היה הכהן מסתובב סביבות המזבח, אלא \u0003במקומו היה עומד ומחטא\u0004 (מזה), שמידתו של מזבח זה היתה רק אמה על אמה ויכול איפוא להזות על קרנותיו בלא לזוז ממקומו.","\u0003ועל\u0004 כל הקרנות \u0003כולן, היה נותן\u0004 את הדם \u0003מלמטה למעלה, חוץ מזו\u0004 בקרן \u0003שהיתה לפניו,\u0004 שבה \u0003היה נותן\u0004 את הדם \u0003מלמעלה למטה. הזה על טהרו של מזבח שבע פעמים, ושירי הדם\u0004 שנשארו בתוך המזרק \u0003היה שופך על יסוד מערבי של מזבח החיצון,\u0004 ואגב כך הוא מלמדנו, כי שיירי הדם שהיו נשארים מן ההזאות \u0003של מזבח החיצון היה שופך אל יסוד דרומי\u0004 שלו. \u0003אלו ואלו,\u0004 כלומר: בין שיירי דם מזבח פנימי ובין שיירי דם מזבח חיצון היו לבסוף \u0003מתערבין באמה\u0004 (בתעלת המים) \u0003ויוצאין\u0004 עם מי השטיפה \u0003לנחל קדרון,\u0004 והיו מים אלה \u0003נמכרין לגננין לזבל\u0004 שהדם יפה לזיבול, והיו מקבלים מן הגננים בנחל קדרון את דמי השימוש במים מיוחדים אלה. וכיון שמים אלה רכוש הקדש הם — \u0003מועלין בהן\u0004 אם לא שילמו תמורתם.","תנו רבנן \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"ויצא אל המזבח\",\u0004 (ויקרא טז, יח) \u0003מה תלמוד לומר?\u0004 שהרי לכאורה בהכרח יוצא הכהן ומגיע לשם. \u0003אמר ר' נחמיה: לפי שמצינו בפר הבא על כל המצו‍ת,\u0004 שהוא פר החטאת שמביא הציבור אם שגגו כל העם בשאר המצוות (פר העלם דבר של ציבור) \u0003שכהן עומד חוץ למזבח ומזה על הפרוכת בשעה שהוא מזה\u0004 עליה, \u0003יכול אף זה\u0004 יהיה \u0003כן,\u0004","\u0003תלמוד לומר: \"ויצא אל המזבח\"\u0004 ללמד: \u0003היכן היה\u0004 קודם — \u0003לפנים מן המזבח\u0004 בצד מערב, סמוך אל הפרוכת ששם היה מזה.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 נאמר שם בפר הבא על כל המצוות: \"והזה שבע פעמים \u0003לפני ה'\u0004 את פני הפרוכת\" (ויקרא ד, יז), \u0003מה תלמוד לומר? אמר ר' נחמיה: לפי שמצינו בפר ושעיר של יום הכפורים שכהן עומד לפנים מן המזבח\u0004 קרוב אל הפרוכת \u0003ומזה על הפרוכת בשעה שהוא מזה, יכול אף זה,\u0004 פר העלם דבר של ציבור, יהיה דינו \u0003כן,\u0004","\u0003תלמוד לומר: \"\u0004ונתן הכהן מן הדם על קרנות \u0003מזבח קטרת הסמים לפני ה' אשר באהל מועד\"\u0004 (ויקרא ד, ז), והדגשת הכתוב \"מזבח קטורת הסמים לפני ה'\" באה ללמדנו כי על ה\u0003מזבח\u0004 להיות \u0003לפני ה', ואין כהן לפני ה'. הא כיצד? — עומד\u0004 הכהן \u0003חוץ למזבח ומזה.\u0004","שנינו במשנה: \u0003התחיל מחטא\u0004 (מזה) \u0003ויורד. תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003התחיל מחטא ויורד. מהיכן היה מתחיל — מקרן מזרחית דרומית,\u0004 ומשם פנה לקרן \u0003דרומית מערבית,\u0004 והלאה לקרן \u0003מערבית צפונית,\u0004 ואחר כך לקרן \u0003צפונית מזרחית\u0004 אלו \u0003דברי ר' עקיבא. ר' יוסי הגלילי אומר: מקרן מזרחית צפונית\u0004 היה מתחיל, ומשם פונה לקרן \u0003צפונית מערבית,\u0004 ומשם לקרן \u0003מערבית דרומית,\u0004 ומסיים בקרן \u0003דרומית מזרחית.\u0004","ומעירים: \u0003מקום\u0004 שלדעת \u0003ר' יוסי הגלילי\u0004 היה הכהן \u0003מתחיל,\u0004 שהיא קרן דרומית מזרחית, \u0003שם\u0004 באותה קרן לדעת \u0003ר' עקיבא\u0004 היה הכהן \u0003פוסק. מקום ש\u0004לדעת \u0003רבי עקיבא\u0004 היה הכהן \u0003 מתחיל שם\u0004 לדעת \u0003 רבי יוסי הגלילי\u0004 היה הכהן \u0003 פוסק.\u0004","ושואלים: \u0003דכולי עלמא מיהא\u0004 \u0005[לדעת הכל על כל פנים]\u0006 \u0003בההוא קרן דפגע ברישא לא עביד\u0004 \u0005[באותה קרן שהוא פוגש בה בראשונה אינו עושה],\u0006 שהרי מאחר והוא בא מצד מערב הריהו פוגע בראשונה בקרן הנמצאת בצד \u0003מערב. מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 \u0003אמר שמואל: דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \u0003\"ויצא אל המזבח\"\u0004 — ללמד: \u0003עד דנפיק מכוליה\u0004 \u0005[עד שהוא יוצא\u0006 מן הקודש מחוץ \u0005לכל]\u0006 מקום ה\u0003מזבח,\u0004 ואם כן, שוב אינו עומד בצד המערבי של המזבח, אלא בצד המזרחי שלו.","ושואלים: ולדעת \u0003ר' עקיבא,\u0004 מדוע לא \u0003נקיף\u0004 \u0005[יקיף]\u0006 \u0003דרך ימין,\u0004 שאם עומד הוא עכשיו במזרחו של המזבח, ופניו למערב, הרי הקרן שעומדת בצד ימינו היא קרן מזרחית צפונית. \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי בשיטת \u0003רמי בר יחזקאל קא מיפלגי\u0004 \u0005[הם חלוקים]\u0006","ש\u0003אמר רמי בר יחזקאל: ים שעשה שלמה\u0004 נאמר בו שהיה \u0003\"עומד על שנים עשר בקר שלשה פנים צפונה ושלושה פנים ימה ושלשה פנים נגבה ושלשה פנים מזרחה והים עליהם מלמעלה וכל אחריהם ביתה\"\u0004 (דברי הימים ב' ד, ד), \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת\u0004 מכאן, מן הכיוון שבו הוא מונה את קבוצות הבקר שמתחת לים, \u0003שכל פינות\u0004 (פניות) \u0003שאתה פונה לא יהו אלא דרך ימין,\u0004 ולצד \u0003מזרח.\u0004 האם נאמר כי \u0003מר\u0004 \u0005[חכם זה]\u0006 ר' יוסי הגלילי \u0003אית ליה\u0004 \u0005[יש לו]\u0006 מקבל את שיטת \u0003רמי בר יחזקאל, ומר\u0004 \u0005[וחכם זה]\u0006 ר' עקיבא \u0003לית ליה\u0004 \u0005[אין לו]\u0006 אינו מקבל את שיטת \u0003רמי בר יחזקאל?\u0004","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אית להו\u0004 \u0005[יש להם\u0006 הם מקבלים\u0005]\u0006 את דברי \u0003רמי בר יחזקאל. והכא בהא קא מיפלגי\u0004 \u0005[וכאן\u0006 בדבר \u0005זה נחלקו]:\u0006 \u0003מר\u0004 \u0005[חכם זה]\u0006 ר' יוסי הגלילי \u0003סבר: ילפינן\u0004 \u0005[לומדים אנו]\u0006 \u0003פנים מחוץ,\u0004 שכשם שמזים במזבח החיצון באותו כיוון כך הוא צריך להזות במזבח הפנימי, \u0003ומר\u0004 \u0005[וחכם זה]\u0006 ר' עקיבא \u0003סבר: לא ילפינן\u0004 \u0005[אין אנו למדים]\u0006 \u0003פנים מחוץ.\u0004","ושואלים: \u0003ור' עקיבא נהי דלא יליף\u0004 \u0005[אומנם אינו לומד]\u0006 \u0003פנים מחוץ,\u0004 אולם לשיטתו \u0003אי בעי\u0004 \u0005[אם רוצה] —\u0006 \u0003הכי נעביד\u0004 \u0005[כך יעשה],\u0006 \u0003אי בעי\u0004 \u0005[ואם רוצה] —\u0006 \u0003הכי נעביד\u0004 \u0005[כך יעשה],\u0006 ומשום מה מתחיל דווקא בקרן מזרחית דרומית? ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך ר' עקיבא:\u0004 אכן \u0003מדינא\u0004 \u0005[\u0006מעיקר \u0005הדין]\u0006 \u0003בההוא\u0004 \u0005[באותה]\u0006 \u0003קרן\u0004 המזבח \u0003דפגע ברישא\u0004 \u0005[ש\u0006בה \u0005הוא פוגש בתחילה] —\u0006 \u0003בההוא עביד ברישא\u0004 \u0005[בה\u0006 הוא \u0005צריך לעשות תחילה],\u0006 לפי ש\u0003אמר ריש לקיש: אין מעבירין על המצות,\u0004 שכל מצוה המזדמנת לו לאדם לעשותה אל ידחנה לזמן מאוחר יותר, אלא יעשנה מיד.","\u0003ואמאי לא עביד\u0004 \u0005[ומדוע לא עשה]\u0006 כן, ומדוע לא נתן על אחת הקרנות המערביות? — \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויצא אל המזבח\"\u0004 וכוונתו: \u0003עד דנפיק מכוליה\u0004 \u0005[שיוצא מכל]\u0006 מקום ה\u0003מזבח וכיון דיהיב בההוא\u0004 \u0005[שנותן באותה]\u0006 \u0003קרן\u0004 שהיא מחוץ למזבח — מיד \u0003הדר אתי לההוא קרן דאיחייב למיתב ברישא\u0004 \u0005[חוזר ובא לאותה קרן\u0006 בצד מערב \u0005שהיה חייב לתת מתחילה]\u0006 את הדם עליה."],["\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כך: \u0003אי סבירא לן\u0004 \u0005[אם סבורים אנו]\u0006 כי \u0003הקפה ברגל\u0004 שהיה הכהן מקיף ברגליו את המזבח הפנימי — \u0003דכולי עלמא לא פליגי\u0004 \u0005[לדעת הכל אינם חולקים]\u0006 \u0003דילפינן\u0004 \u0005[שאנו לומדים]\u0006 דרך הזאת \u0003פנים\u0004 מהזאת \u0003חוץ\u0004 לענין ימין. \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003בהא קא מיפלגי\u0004 \u0005[בדבר זה נחלקו]:\u0006 \u0003מר\u0004 \u0005[חכם זה]\u0006 ר' עקיבא \u0003סבר\u0004 כי עומד היה הכהן במקומו וממנו היה מקיף ומזה לכל הקרנות ו\u0003הקפה\u0004 זו \u0003ביד\u0004 היתה, \u0003ומר\u0004 \u0005[וחכם זה]\u0006 ר' יוסי \u0003סבר\u0004 כי \u0003הקפה\u0004 זו \u0003ברגל\u0004 היתה.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003הקפה ביד\u0004 היא, \u0003והכא בהא קא מיפלגי\u0004 \u0005[וכאן\u0006 בדבר \u0005זה נחלקו]\u0006 \u0003מר\u0004 \u0005[חכם זה]\u0006 ר' עקיבא \u0003סבר\u0004 כי \u0003ילפינן\u0004 \u0005[למדים אנו]\u0006 \u0003יד מרגל,\u0004 ולכן עושים במזבח הפנימי כמו בחיצון. \u0003ומר\u0004 \u0005[וחכם זה]\u0006 ר' יוסי \u0003סבר: לא ילפינן\u0004 \u0005[אין אנו למדים].\u0006","ושואלים: כיצד אפשר לומר הסבר אחרון זה? וכי \u0003סבר ר' יוסי הגלילי הקפה ביד? והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנינו בסופה\u0006 של המשנה\u0005]:\u0006 \u0003ר' אליעזר אומר: במקומו היה עומד ומחטא — מכלל\u0004 זה נבין כי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003לא סבירא ליה\u0004 \u0005[אינו סובר אותו],\u0006 שאינו חושב כך, והתנא הראשון הרי הוא כפי שהוכחנו ר' יוסי הגלילי. \u0003אלא מחוורתא כדשנינן מעיקרא\u0004 \u0005[מחוור,\u0006 ברור, \u0005כפי שיתרצנו מתחילה]\u0006 כי \u0003מר\u0004 \u0005[חכם זה]\u0006 ר' עקיבא \u0003סבר\u0004 כי \u0003הקפה\u0004 זו \u0003ביד\u0004 היתה, \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר\u0004 כי \u0003הקפה\u0004 זו \u0003ברגל\u0004 היתה.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 כך: \u0003בהא קא מיפלגי\u0004 \u0005[\u0006בדבר \u0005זה נחלקו]\u0006 \u0003מר\u0004 \u0005[חכם זה]\u0006 ר' עקיבא \u0003סבר: סביב\u0004 של \u0003מזבח\u0004 ה\u0003פנימי כסביב\u0004 של \u0003מזבח\u0004 ה\u0003חיצון, ומר\u0004 \u0005[וחכם זה]\u0006 ר' יוסי \u0003סבר: כוליה\u0004 \u0005[כל]\u0006 ה\u0003מזבח\u0004 ה\u0003פנימי במקום חדא קרן\u0004 \u0005[קרן אחת]\u0006 של \u0003מזבח החיצון קאי\u0004 \u0005[\u0006הוא \u0005עומד],\u0006 שהרי המזבח הפנימי היה כולו אמה על אמה, כמו קרן אחת של המזבח החיצון, ולכן דיני מזבח החיצון אינם שייכים איפוא במזבח הפנימי.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' ישמעאל: שני כהנים גדולים נשתיירו\u0004 עוד מימי \u0003מקדש ראשון, זה אומר: בידי הקפתי\u0004 והזיתי ולא הקפתי ברגלי סביב המזבח, \u0003וזה אומר: ברגלי הקפתי. זה נותן טעם לדבריו, וזה נותן טעם לדבריו.\u0004","\u0003זה\u0004 שאמר כי ברגליו הקיף, \u0003נותן טעם לדבריו\u0004 ואומר: כי \u0003סביב\u0004 של \u0003מזבח הפנימי\u0004 צריך לעשות אותו \u0003כסביב של מזבח החיצון\u0004 שמקיפו ברגליו לצורך ההזאה, \u0003וזה\u0004 שאמר כי הקיף בידיו \u0003נותן טעם לדבריו\u0004 ואומר: כי \u0003כוליה\u0004 \u0005[כל]\u0006 \u0003מזבח\u0004 ה\u0003פנימי במקום חדא קרן\u0004 \u0005[קרן אחת]\u0006 של מזבח ה\u0003חיצון קאי\u0004 \u0005[\u0006הוא \u0005עומד]\u0006 וכשם שבקרן המזבח החיצון מזים מן הדם רק ביד, אף במזבח הפנימי כך היו עושים.","שנינו במשנה כי \u0003ר' אליעזר אומר: במקומו היה עומד ומחטא.\u0004 ומעירים: \u0003מתניתין מני\u0004 \u0005[משנתנו כשיטת מי היא] —\u0006 כשיטת \u0003ר' יהודה היא\u0004 שלדעתו זוהי שיטת ר' אליעזר בענין זה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 שנחלקו תנאים אחרונים בשיטת ר' אליעזר. \u0003ר' מאיר אומר:\u0004 ש\u0003ר' אליעזר אומר\u0004 כך: \u0003במקומו עומד ומחטא,\u0004 אולם \u0003ועל כולן\u0004 על כל הקרנות \u0003היה נותן\u0004 מזה \u0003מלמעלה למטה,\u0004 כדי שלא יזל מן הדם לתוך שרוול בגדו, \u0003חוץ מאותה שבאלכסון\u0004 שהיתה בדיוק כנגדו, שטורח הוא להזות מלמעלה למטה ועליה היה \u0003נותן ממטה למעלה.\u0004","ואילו \u0003ר' יהודה אומר:\u0004 ש\u0003ר' אליעזר אומר: במקומו עומד ומחטא,\u0004 אולם \u0003ועל כולן הוא נותן מלמטה למעלה,\u0004 שנוח לו להזות כך, \u0003חוץ מזו שהיתה לפניו\u0004 וסמוכה לו \u0003ממש, שנותן\u0004 היה עליה \u0003ממעלה למטה.\u0004 וטעמו: \u0003כי היכי דלא נתווסן מאניה\u0004 \u0005[כדי שלא יתלכלכו בגדיו]\u0006 בדם. שאם יזה בקרן הסמוכה לו מלמטה למעלה קיים חשש שיפול הדם על בגדיו, ויצטרך להחליף בגדים, שבגדי כהונה מלוכלכים ומוכתמים פסולים לעבודה.","שנינו במשנה: \u0003הזה ממנו על טהרו של מזבח.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פרוש המילה\u0005]\u0006 \u0003\"טהרו\"? אמר רבה בר רב שילא: פלגיה\u0004 \u0005[חציו]\u0006 של ה\u0003מזבח, כדאמרי אינשי\u0004 \u0005[כמו שאנשים\u0006 רגילים \u0005לומר]:\u0006 \u0003\"טהר טיהרא\u0004 \u0005[צהרו הצהריים]\u0006 \u0003והוי פלגיה דיומא\u0004 \u0005[והרי זה חציו של יום]\u0006\u0003\".\u0004 אף כאן, \"טהרו של מזבח\" — חצי המזבח. כלומר:, היה מזה על דפנותיו במחציתו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003כשהוא מזה\u0004 על מזבח הפנימי — \u0003אינו מזה לא על גבי האפר ולא על גבי הגחלים, אלא חותה\u0004 ומסלק \u0003גחלים אילך ואילך, ומזה.\u0004 משמע שהזאה זו היתה על גבי המזבח, ולא בצידו! \u0003אלא\u0004 חזר בו \u0003רבה בר רב שילא\u0004 ואמר: \"על טהרו של מזבח\" הכוונה — \u0003על גלויה\u0004 \u0005[על גילויו,\u0006 עצמו\u0005]\u0006 של ה\u0003מזבח, כדכתיב\u0004 \u0005[וכמו שנאמר]:\u0006 \u0003\"וכעצם השמים לטהר\"\u0004 (שמות כד, י), הרי שטוהר הוא לשון נקיון.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חנניא אומר:\u0004 שבע ההזאות שהיה הכהן מזה על המזבח, \u0003בצד צפוני\u0004 של המזבח \u0003הוא נותן\u0004 אותם, ו\u0003ר' יוסי אומר: בצד דרומי הוא נותן.\u0004 ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 באיזה עקרון \u0005נחלקו]?\u0006 ומסבירים: \u0003מר\u0004 \u0005[חכם זה],\u0006 חנניא, \u0003סבר:\u0004 כי \u0003פיתחא\u0004 \u0005[הפתח]\u0006 \u0003בדרום קאי\u0004 \u0005[\u0006הוא \u0005עומד]\u0006 ולכן מתחיל את ההזאות מצד זה. \u0003ומר\u0004 \u0005[וחכם זה]\u0006 ר' יוסי \u0003סבר: פיתחא\u0004 \u0005[הפתח]\u0006 \u0003בצפון קאי\u0004 \u0005[\u0006הוא \u0005עומד]\u0006 ולכן מתחיל להזות במזבח מצד צפון.","ומעירים: \u0003דכולי עלמא מיהא\u0004 \u0005[לדעת הכל על כל פנים],\u0006 \u0003היכא דגמרן\u0004 \u0005[במקום שנסתיימו]\u0006 ה\u0003מתנות\u0004 של ה\u0003קרנות, התם יהיב\u0004 \u0005[שם\u0006 הוא \u0005נותן]\u0006 \u0003על גגו,\u0004 סמוך לקרן שבה סיים להזות. ולא נחלקו אלא באיזה צד סיום ההזאות, אם בצד דרומי או בצד צפוני. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[אמר הכתוב]:\u0006 \u0003\"\u0004והזה עליו מן הדם באצבעו שבע פעמים \u0003וטהרו וקדשו\"\u0004 (ויקרא טז, יט), לומר: קרן המזבח שהוא \u0003מקום שקדשו\u0004 בהזאת הדם, \u0003שם\u0004 גם \u0003טיהרו\u0004 מן הגחלים להזות על גבו.","שנינו במשנה: \u0003שירי הדם היה שופך על יסוד מערבי של מזבח החיצון.\u0004 ומסבירים: \u0003דאמר קרא\u0004 \u0005[שאמר הכתוב]\u0006 לגבי פר חטאת כהן גדול בשאר ימות השנה: \u0003\"ואת כל דם הפר ישפך\u0004 אל יסוד מזבח העולה אשר פתח אהל מועד\u0003\"\u0004 (ויקרא ד, ז) \u0003וכי נפיק\u0004 \u0005[וכאשר יוצא]\u0006 מן ההיכל לשפוך את שיירי הדם \u0003בההוא\u0004 \u0005[בזה],\u0006 ביסוד המזבח שלצד מערב הוא \u0003פגע ברישא\u0004 \u0005[פוגש תחילה].\u0006","שנינו עוד במשנה, כי שיירי הדם \u0003של מזבח החיצון היה שופך על יסוד דרומית\u0004 שלו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003יסוד המזבח\u0004 שנאמר לענין שפיכת שיירי הדם — \u0003זה יסוד דרומית. אתה אומר יסוד דרומית, או אינו אלא יסוד מערבית?\u0004","\u0003אמרת: ילמד ירידתו מן הכבש\u0004 של המזבח החיצון כשמסיים להזות עליו מדם חטאות החיצונות \u0003ליציאתו מן ההיכל\u0004 ושיריים הפנימיים בידו, \u0003מה\u0004 בשעת \u0003יציאתו מן ההיכל\u0004 הריהו שופך את שיירי הדם \u0003בסמוך לו, ואי זה — זה יסוד מערבי,\u0004 שהוא סמוך לו, \u0003אף\u0004 ב\u0003ירידתו מן הכבש\u0004 של המזבח החיצון לאחר שסיים להזות מדם החטאות, הריהו שופך את הדם \u0003בסמוך לו, ואי זה — זה יסוד דרומי,\u0004 שכאשר יורד מן הכבש, צריך לפנות לימין ולמזרח, ויסוד דרומי הוא הסמוך ביותר אליו.","ומעירים: \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' ישמעאל אומר: זה וזה\u0004 גם דם חטאת פנימית וגם חטאת חיצונה היה נשפכין ל\u0003יסוד מערבי. ר' שמעון בן יוחאי אומר: זה וזה\u0004 נשפכין ל\u0003יסוד דרומי.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 כי \u0003ר' ישמעאל קסבר\u0004 \u0005[סבר]:\u0006 \u0003ילמד\u0004 ענין חטאות החיצוניות שדינם \u0003סתום\u0004 במקרא מענין חטאות הפנימיות שדינם \u0003מפורש,\u0004 וכשם שמצאנו ששיירי דם המתנות שבפנים ניתנים על יסוד מערבי, אף מתן שיירי דם החיצוניות ליסוד, מקומם ביסוד מערבי.","\u0003אלא, ר' שמעון בן יוחאי\u0004 הסובר כי זה וזה נשפכים ליסוד דרומי, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 נתן לדבריו\u0005]?\u0006 \u0003אמר רב אשי: קסבר\u0004 \u0005[סבור הוא]\u0006 כי \u0003פתחא\u0004 \u0005[פתח]\u0006 ההיכל בצד \u0003דרום\u0004 למזבח \u0003קאי\u0004 \u0005[עומד\u0006 הוא\u0005],\u0006 שהמזבח נוטה כלפי צפון העזרה ולכן יסוד דרומי הוא היסוד הסמוך לו ביציאתו מן הקדש.","\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 בנוסחה שאותה למדו \u0003בדבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שמעון בן יוחאי,\u0004 ששם היו שונים בשמו נוסחה אחרת: \u0003זה וזה\u0004 היו נותן ב\u0003יסוד דרומית.\u0004 ולפי גירסה זו חזר בו ר' ישמעאל והודה לר' שמעון. ומעירים: \u0003וסימניך,\u0004 לזכור את שינוי הגירסה והדין: \u0003משכוה גברי לגברא\u0004 \u0005[משכו אנשים את האיש]\u0006 שהרי הרבים גוברים ומושכים את היחיד. וכאן תלמידי ר' שמעון הרבים \"משכו\" את ר' ישמעאל היחיד לומר כדבריהם.","שנינו: \u0003אלו ואלו\u0004 הדמים שנשפכו ליסוד היו בסוף יוצאים משם אל האמה (תעלה) \u0003מתערבין\u0004 במים ש\u0003באמה, ויוצאין\u0004 לנחל קדרון ושם היו נמכרים לגננים ואלו שלא פדאום מן ההקדש, היו מועלין בהם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מועלין בדמים\u0004 שהם מוקדשים לשמים והם רכוש המקדש, ואסורים בשימוש לצורך דבר חולין, והמשתמש בהם — מעל בקודש. אלו \u0003דברי ר' מאיר ור' שמעון. וחכמים אומרים: אין מועלין בהן.\u0004"],["ומעירים: \u0003עד כאן לא פליגי\u0004 \u0005[נחלקו]\u0006 חכמים אלה \u0003אלא\u0004 במעילה \u0005שהיא\u0006 \u0003מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 שגזרו חכמים מעילה בדמים, \u0003אבל מדאורייתא\u0004 \u0005[מן התורה]\u0006 לדעת הכל \u0003אין מועלין בהן,\u0004 שאם מדין תורה יש בהם מעילה בודאי לא היו נמכרין לגננים לכתחילה (תוספות).","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שאין מעילה בדם? \u0003אמר עולא: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"כי נפש הבשר בדם היא ואני נתתיו \u0003לכם\u0004 על המזבח לכפר על נפשותיכם\" (ויקרא יז, יא), \"לכם\" משמע: \u0003שלכם יהא\u0004, שאין הוא קנין ההקדש, אלא של כל ישראל הוא. \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שמעון תנא\u0004 \u0005[שנו]\u0006 בדומה לזה: מה שנאמר: \u0003\"לכפר\" —\u0004 הרי זה בא ללמד כי \u0003לכפרה נתתיו, ולא למעילה.\u0004","\u0003ור' יוחנן אמר:\u0004 שלמדים דבר זה מהדגשה אחרת בכתוב: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"כי הדם \u0003הוא\u0004 בנפש יכפר\" (ויקרא יז, יא), \"הוא\" משמעו בהוייתו יהא, שדינו אחד תמיד, ש\u0003לפני כפרה\u0004 דינו \u0003כלאחר כפרה; מה לאחר כפרה\u0004 לדעת הכל \u0003אין בו\u0004 עוד \u0003מעילה\u0004 שהרי נעשתה כבר מצותו — \u0003אף לפני כפרה אין בו מעילה.\u0004","ושואלים: אם יש להשוות, אם כן אולי על בסיס השוואה זו של לפני כפרה לזו שלאחר \u0003ואימא\u0004 \u0005[ואמור\u0006 כך\u0005]:\u0006 כי \u0003לאחר כפרה\u0004 יהיה דינו \u0003כלפני כפרה, מה לפני כפרה יש בו מעילה — אף לאחר כפרה יש בו מעילה!\u0004 ודוחים: דבר זה אינו מתקבל על הדעת, כי כלל בידינו: \u0003אין לך דבר שנעשית מצותו ומועלין בו\u0004 לאחר גמר עשיית המצוה. ושואלים: \u0003ולא?\u0004 וכי אין דבר כזה? \u0003והרי תרומת הדשן\u0004 שהיא אפר הקרבנות שנשרפו כבר על המזבח, וטעונה גניזה ואסורה בהנאה והנהנה ממנה — מעל וחייב!"],["\u0003משום דהוי\u0004 \u0005[שהם,\u0006 שנידונים\u0005]\u0006 \u0003תרומת הדשן ובגדי כהונה\u0004 (ארבעה בגדי לבן שלובש הכהן הגדול ביום הכיפורים), שבשניהם יש הלכה מיוחדת שמועלים בהם אף לאחר שנעשתה מצוותם, כ\u0003שני כתובין הבאין כאחד,\u0004 שיש בהם דין מסויים המיוחד להם, וכלל בידינו: \u0003כל שני כתובין הבאין כאחד\u0004 — \u0003אין מלמדין\u0004 לשאר הלכות שבתורה, אלא רואים אותם כמקרים יוצאי דופן, שאינם יכולים להיות בסיס לבנין אב למקרים אחרים.","ועדיין מקשים: \u0003הניחא לרבנן\u0004 \u0005[\u0006דבר \u0005זה נוח לשיטת חכמים]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 כי מה שנאמר: \u0003\"\u0004ופשט את בגדי הבד אשר לבש בבואו אל הקודש \u0003והניחם שם\"\u0004 (ויקרא טז, כג), \u0003מלמד\u0004 שארבעת בגדי לבן שלבש הכהן הגדול ביום הכיפורים, שוב אינם ראויים לשימוש אחר ו\u0003שטעונין גניזה.\u0004","\u0003אלא לר' דוסא,\u0004 ש\u0003אמר\u0004 כי \u0003בגדי כהונה\u0004 אלה \u0003ראוין הן לכהן הדיוט\u0004 ואינן טעונים גניזה, ואין מועלים בהם, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שלשיטתו נותרה רק תרומת הדשן שיש בה הלכה זו שנעשתה מצותה ומועלים בה, ואין כאן איפוא שני כתובים, ומדוע לא נלמד ממנה בבנין אב לכל התורה?","ודוחים: אף על פי כן, \u0003משום דהוי\u0004 \u0005[שהם]\u0006 \u0003תרומת הדשן ועגלה ערופה שני כתובין הבאין כאחד\u0004 שאסורין בהנאה גם לאחר גמר מצותן, \u0003וכל שני כתובין הבאין כאחד — אין מלמדין.\u0004","ומקשים מצד אחר: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006דבר זה \u0005נוח ל\u0006שיטת \u0005מי שאמר]\u0006 ששני כתובים הבאים כאחד \u0003אין מלמדין, אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאמר]\u0006 כי אף שני כתובין הבאין כאחד \u0003מלמדין,\u0004 אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003תרי מיעוטי כתיבי\u0004 \u0005[שני מיעוטים כתובים]\u0006 בשני דינים אלה, ללמדנו שהלכה זו נוהגת רק בהם. בתרומת הדשן נאמר: \u0003\"ושמו\"\u0004 (ויקרא ו, ג) משמע: אותו ולא אחר. ובעגלה ערופה נאמר: \u0003\"הערופה\"\u0004 (דברים כח, ז) לומר: בזו נוהג דין זה, ולא בדבר אחר.","ושואלים: \u0003והני תלתי קראי\u0004 \u0005[ואותם שלושה כתובים]\u0006 האמורים \u0003בדם\u0004 שמהם למדים שאין מעילה בשיירי הדם היוצאים דרך האמה לנחל קדרון, כיון שלמדנו הלכה זו ממקורות אחרים — כתובים אלה \u0003למה לי?\u0004","ומשיבים: \u0003חד\u0004 \u0005[\u0006כתוב \u0005אחד]\u0006 מהם בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 את הדם מאיסור \u0003נותר,\u0004 שאם אכל דם שנותר לאחר זמן הקרבת הקרבן אין באכילתו עונש כרת של אכילת נותר, אלא חייב משום אכילת דם בלבד, \u0003וחד\u0004 \u0005[ו\u0006כתוב \u0005אחד]\u0006 \u0003למעוטי\u0004 \u0005[למעט\u0006 אותו\u0005]\u0006 \u0003ממעילה,\u0004 שאין מועלין בו, \u0003וחד\u0004 \u0005[ו\u0006כתוב \u0005אחד]\u0006 \u0003למעוטי\u0004 \u0005[למעט\u0006 אותו\u0005]\u0006 \u0003מטומאה\u0004 שאם אכל מן הדם בטומאה, אינו חייב אלא משום אכילת דם, אבל לא משום אכילת קדשים בטומאה.","\u0003אבל\u0004 מדין \u0003פיגול לא צריך למעוטי קרא\u0004 \u0005[למעטו הכתוב],\u0006 שכבר יודעים אנו דבר זה ממקום אחר, \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל\u0004 קרבן \u0003שיש לו מתירין\u0004 על ידי פעולה כלשהי, כגון זריקת הדם, או שיש קרבן אחר המכשיר אותו, \u0003בין\u0004 שמתירין אותו על ידי זה לאכילת \u0003אדם, בין\u0004 שמתירין אותו להקרבה \u0003למזבח\u0004 קרבן כזה — \u0003חייבין עליו משום פיגול\u0004 ואם אכל ממנו לאחר שנתפגל — חייב כרת. אבל המתיר עצמו — אין בו משום פיגול, ולכן \u0003דם עצמו\u0004 שהרי \u0003מתיר הוא\u0004 את הקרבנות לאכילה או להקרבה — אין בו דין פיגול.","\u0003כל מעשה יום הכפורים האמור\u0004 במשנתנו, כבתורה — \u0003על הסדר\u0004 הוא. ו\u0003אם הקדים מעשה\u0004 מאלה \u0003לחבירו — לא עשה כלום. הקדים\u0004 והזה \u0003דם השעיר\u0004 קודם \u0003לדם הפר — יחזור ויזה מדם השעיר לאחר\u0004 שיזה מ\u0003דם הפר,\u0004 כדי שתהיה ההזאה כסדרה. \u0003ואם עד שלא גמר את המתנות שבפנים\u0004 בקודש הקדשים \u0003נשפך הדם\u0004 — ישחט פר או שעיר אחר ו\u0003יביא דם אחר, ויחזור בתחילה\u0004 ויעשה את כל העבודות \u0003מבפנים\u0004 (בקודש הקדשים).","\u0003וכן\u0004 אם נשפך הדם טרם סיימו את המתנות ש\u0003בהיכל\u0004 — יתחיל מחדש בעבודות ההיכל, \u0003וכן\u0004 במתן הדם על גבי \u0003מזבח הזהב.\u0004 לפי \u0003שכולן כפרה בפני עצמן,\u0004 ולכן אין צורך לחזור ולעשות את כל סדר העבודה כולו מתחילתו אלא רק אותו חלק שלא נגמר. ואילו \u0003ר' אלעזר ור' שמעון אומרים: ממקום שפסק\u0004 שבו נשפך הדם, \u0003משם הוא מתחיל,\u0004 שלדעתם כל מתנה בעבודות אלה היא דבר בפני עצמו, ואין צורך לחזור על מה שנעשה כבר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל מעשה יום הכפורים האמור\u0004 בתורה — על \u0003הסדר\u0004 הוא. ו\u0003אם הקדים מעשה לחבירו — לא עשה כלום. אמר ר' יהודה: אימתי\u0004 נאמרו דברים אלה — \u0003בדברים הנעשין בבגדי לבן מבפנים\u0004 כגון ההקטרה ומתן הדמים שהם עיקר עבודת היום, \u0003אבל דברים הנעשין בבגדי לבן מבחוץ\u0004 כגון ההגרלה והוידוי \u0003אם הקדים מעשה לחבירו — מה שעשה עשוי\u0004 ואינו צריך לחזור.","ואילו \u0003ר' נחמיה אומר: במה דברים אמורים\u0004 שהסדר מעכב — \u0003בדברים הנעשים בבגדי לבן, בין מבפנים בין מבחוץ. אבל בדברים הנעשים בבגדי זהב מבחוץ\u0004 שהם עבודת המקדש הרגילה ועבודת המוספים, אם שינה בהם את הסדר — \u0003מה שעשה עשוי. אמר ר' יוחנן: ושניהם מקרא אחד דרשו,\u0004 והוא האמור: \u0003\"והיתה זאת לכם לחקת עולם\u0004 לכפר על בני ישראל מכל חטאתם \u0003אחת בשנה\"\u0004 (ויקרא טז, לד)."],["\u0003ר' יהודה סבר:\u0004 כוונת הכתוב היא לומר שחוקה זו נאמרה לגבי \u0003מקום\u0004 (קודש הקדשים) \u0003שמתכפרין בו פעם אחת בשנה\u0004 משמע, שבעבודות הנעשות בו סדר העבודה מעכב. \u0003ור' נחמיה סבר: דברים המתכפרין בהן פעם אחת בשנה\u0004 משמע, והכוונה: בין למקום ובין לבגדים, ולכן כל העבודות הנעשות בבגדי לבן, מעכב בהן סדר העבודה.","ושואלים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003לר' יהודה מקום כתיב\u0004 \u0005[נאמר]?\u0006 הלא לא נאמר אלא \"אחת בשנה\", ולכאורה מדובר בסדר העבודה בכלל, ולא לענין מקום מסויים! \u0003אלא,\u0004 יש לחזור מההסבר הראשון, ולומר: \u0003היינו טעמיה\u0004 \u0005[זה טעמו]\u0006 של \u0003ר' יהודה: כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"זאת\"\u0004 (ויקרא טז, לד), שהוא לשון מיעוט וצימצום \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"אחת\u0004 בשנה\u0003\"\u0004 (ויקרא טז, לד) שהוא לשון מיעוט נוספת, \u0003חד\u0004 \u0005[\u0006מיעוט \u0005אחד]\u0006 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 דברים הנעשים \u0003בבגדי לבן מבחוץ\u0004 שאינם מעכבים, \u0003וחד\u0004 \u0005[ו\u0006מיעוט \u0005אחד]\u0006 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 דברים הנעשים \u0003בבגדי זהב.\u0004","\u0003ורבי נחמיה\u0004 כיצד מפרש הוא? — לדעתו \u0003חד\u0004 \u0005[אחד]\u0006 מן המיעוטים בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 את הדברים הנעשים ב\u0003בגדי זהב, וחד\u0004 \u0005[ו\u0006מיעוט \u0005אחד]\u0006 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שירים\u0004 הניתנים ליסוד המזבח \u0003דלא מעכבי\u0004 \u0005[שאינם מעכבים],\u0006 ואף אם הקדים לשפיכת השיריים עבודה האמורה להיות מאוחרת להם — אין הסדר מעכב, אף על פי ששפיכת הדם נעשית בבגדי לבן. ושואלים: \u0003ור' יהודה\u0004 מה סבור הוא בדין השיריים? ומשיבים: לדעתו \u0003אי מעכבי\u0004 \u0005[אם מעכבים]\u0006 שאר דברים הנעשים בחוץ — \u0003מעכבי\u0004 \u0005[\u0006אף אלה \u0005מעכבים]\u0006 \u0003ואי לא מעכבי\u0004 \u0005[ואם אין מעכבים]\u0006 הדברים הנעשים בחוץ — אף השיריים \u0003לא מעכבי\u0004 \u0005[אינם מעכבים].\u0006","וההוכחה לכך כי לדעת ר' יהודה שיריים מעכבים את הכפרה, \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"וכלה מכפר את הקדש\"\u0004 (ויקרא טז, כ) לומר: \u0003אם כפר — כלה,\u0004 שעל ידי כך סיים את סדר העבודה, \u0003ואם לא כפר — לא כלה, דברי ר' עקיבא. אמר לו ר' יהודה: מפני מה\u0004 אכן \u0003לא נאמר: אם כלה\u0004 לתת את כל מתנות הדמים — \u0003כפר, ואם לא כלה — לא כפר,\u0004 ללמדנו: \u0003שאם חיסר אחת מן המתנות — לא עשה ולא כלום.\u0004","\u0003ואמרינן\u0004 \u0005[ואמרנו]\u0006 כאשר דנו בשאלה זו: \u0003מאי בינייהו\u0004 \u0005[מה ההבדל ביניהם]?\u0006 ונחלקו בכך \u0003ר' יוחנן ור' יהושע בן לוי. חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: משמעות דורשין איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שאין ביניהם הבדל הלכה למעשה, אלא רק במדרש הפסוקים, כיצד יש לדרשם. \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר:\u0004 בשאלה האם מתן \u0003שירים\u0004 ליסוד המזבח \u0003מעכבי\u0004 \u0005[מעכבים]\u0006 את הכפרה \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005],\u0006 שלדעת ר' עקיבא אין מעכבים, ואילו לדעת ר' יהודה מעכבים. והוא כפי שהוסברה תחילה שיטת ר' יהודה.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך],\u0006 שלדעת ר' נחמיה אין שיריים מעכבים? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 עצמו במסכת זבחים (קיא, א): \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ר' נחמיה כדברי האומר שירים מעכבי\u0004 \u0005[מעכבים]!\u0006 ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה\u0006 הדבר\u0005].\u0006","\u0003אמר ר' חנינא: קטורת שחפנה קודם שחיטתו של פר לא עשה ולא כלום.\u0004 ומעירים: \u0003כמאן\u0004 \u0005[כשיטת מי]\u0006 אמר הלכה זו — \u0003דלא\u0004 \u0005[שלא]\u0006 כשיטת \u0003ר' יהודה: דאי\u0004 \u0005[שאם\u0006 תאמר\u0005]\u0006 כדברי \u0003ר' יהודה, האמר\u0004 \u0005[הרי אמר]\u0006 ר' יהודה \u0003כי כתיבא\u0004 \u0005[כאשר נאמר]:\u0006 \u0003\"חקה\"\u0004 שפירושה שאין לשנות בסדר ובשאר פרטים — הרי זה דווקא \u0003בדברים הנעשים בבגדי לבן מבפנים הוא דכתיבא\u0004 \u0005[שנאמרה],\u0006 וחפינת הקטורת הלא נעשית מבחוץ!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שר' חנינא אף לשיטת \u0003ר' יהודה\u0004 אמר. אולם אפשר לומר כי לדעתו \u0003צורך פנים\u0004 חפינת הקטורת הנועדת כדי להכניסה לפנים — כדבר הנעשה ב\u0003פנים דמי\u0004 \u0005[נחשב].\u0006 ומקשים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אם עד שלא גמר מתנות שבפנים נשפך הדם — יביא דם אחר, ויחזור ויזה בתחילה בפנים. ואם איתא\u0004 \u0005[יש\u0006 בסיס\u0005]\u0006 לדברי ר' חנינא, לא די בשחיטת פר וזריקת דמים מחדש, אלא \u0003אף יחזור ויחפון\u0004 את הקטורת מחדש \u0003מבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו\u0006 לומר\u0005],\u0006 ואם לא אמר כן — משמע שסדר חפינת הקטורת אינו מעכב!"],["ומשיבים: מכאן אין ראיה, כי \u0003בקטורת לא קא מיירי\u0004 \u0005[איננו עוסק],\u0006 ואכן על פי האמת צריך לחזור ולחפון ולהקטיר קטורת חדשה לאחר שחיטת הפר, ומה שלא הזכיר דבר זה במשנה משום שבמשנה זו עוסק בענין מתנות הדם ולא במעשה הקטורת.","\u0003אמר עולא: שעיר ששחטו קודם מתן דמו של פר — לא עשה ולא כלום.\u0004 ושואלים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003הקדים דם השעיר לדם הפר — יחזור\u0004 בשנית \u0003ויזה מדם השעיר אחר דם הפר. ואם איתא\u0004 \u0005[ואם יש\u0006 מקום\u0005]\u0006 לדברי עולא — אם כן \u0003יחזור וישחוט מבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! ומסבירים, \u0003תרגמא\u0004 \u0005[הסבירה]\u0006 \u0003עולא\u0004 עצמו, שבמשנה מדובר שהקדימו \u0003במתנות שבהיכל,\u0004 אבל מתנות שלפני ולפנים אם אכן הקדימו את שחיטתו — אכן מעכב. \u0003וכן אמר ר' אפס\u0004 ופירש שמדובר במשנה \u0003במתנות שבהיכל.\u0004","במשנתנו נאמר: \u0003וכן בהיכל וכן במזבח\u0004 אם נשפך הדם יחזור ויתחיל מתחילת אותו מחזור הזאות. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \"וכיפר את מקדש הקודש ואת אהל מועד ואת המזבח יכפר ועל הכהנים ועל כל עם הקהל יכפר\" (ויקרא טז, לג) ודורשים: \u0003\"וכפר את מקדש הקדש\" זה לפני ולפנים\u0004 קודש הקדשים, \u0003\"אהל מועד\" — זה היכל, \"מזבח\" — כמשמעו. \"יכפר\"\u0004 שכתוב שנית בכתוב, בא להוסיף: \u0003אלו עזרות.\u0004","\u0003\"הכהנים\" — כמשמען, \"עם הקהל\" — אלו ישראל, \"יכפר\"\u0004 שבא להוסיף: \u0003אלו הלוים\u0004 שגם הם מתכפרים. \u0003הושוו כולן לכפרה אחת\u0004 בפסוק זה, לומר: \u0003שכולן מתכפרין בשעיר המשתלח,\u0004 לגבי \u0003שאר עבירות,\u0004 שאין מתכפרין בהן בפר או בשעירים הנעשים בפנים, שהרי הפר מכפר רק על הכהנים והשעירים אינם מכפרים אלא על ישראל בלבד, ורק בשעיר המשתלח הושוו כולם לכפרה. אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' שמעון אומר: כשם שדם השעיר הנעשה בפנים מכפר על ישראל\u0004 על שחטאו \u0003בטומאת מקדש וקדשיו, כך דם הפר\u0004 של הכהן הגדול \u0003מכפר על הכהנים\u0004 שחטאו \u0003בטומאת מקדש וקדשיו, וכשם שוידוי של שעיר המשתלח מכפר על ישראל בשאר עבירות — כך וידוי של פר מכפר על הכהנים בשאר עבירות\u0004 ואין הכהנים צריכים כפרה בשעיר המשתלח.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת: נאמר: \"וכילה מכפר את הקודש ואת אהל מועד ואת המזבח והקריב את השעיר החי\" (ויקרא טז, כ). \u0003\"וכלה מכפר את הקדש\"\u0004 דורשים: \u0003זה\u0004 ההזאות ש\u0003לפני ולפנים,\u0004 קודש הקדשים, \u0003\"אהל מועד\" — זה\u0004 ההזאות שעל פרוכת ה\u0003היכל, \"מזבח\" — כמשמעו, מלמד שכולן כפרה, כפרה בפני עצמן,\u0004 שעל כל אחד מאלה צריך כפרה מיוחדת, ואם אירע פסול באחת הכפרות צריך לחזור ולכפר מתחילה.","\u0003מכאן אמרו: נתן מקצת מתנות שבפנים ונשפך הדם — יביא דם אחר ויתחיל בתחלה במתנות שבפנים. ר' אלעזר ור' שמעון אומרים:\u0004 אינו צריך לחזור מתחילת מחזור ההזאות ו\u0003אינו מתחיל אלא ממקום שפסק\u0004 באותה מתנה. \u0003גמר את המתנות שבפנים ונשפך הדם — יביא דם אחר ויתחיל בתחלה במתנות שבהיכל\u0004 מראשיתן, אבל לא יתחיל מחדש במתנות שבפנים, שהרי כבר נתן את כל המתנות שבפנים וכבר נסתיימה כפרתן.","\u0003נתן מקצת מתנות שבהיכל ונשפך הדם — יביא דם אחר ויתחיל בתחילה בהיכל,\u0004 שהרי נתן רק מקצת המתנות ועדיין לא נסתיימה כפרתן. ואילו \u0003ר' אלעזר ור' שמעון אומרים: אינו מתחיל אלא ממקום שפסק.\u0004","\u0003גמר מתנות שבהיכל ונשפך הדם — יביא דם אחר ויתחיל בתחילה במתנות המזבח\u0004 כי מה שכיפר — כיפר כבר. ואם \u0003נתן מקצת מתנות שבמזבח ונשפך הדם — יביא דם אחר ויתחיל בתחילה במתנות המזבח,\u0004 שעדיין לא נסתיימה כפרת המזבח. \u0003ר' אלעזר ור' שמעון אומרים\u0004 כשיטתם: \u0003ממקום שפסק —\u0004 משם \u0003הוא מתחיל. גמר מתנות שבמזבח ונשפך הדם\u0004 ולא הספיק לשפוך את שייריו ליסוד מזבח החיצון — \u0003דברי הכל\u0004 שיריים \u0003לא מעכבי\u0004 \u0005[אינם מעכבים]\u0006 ואינו צריך לשחוט קרבן נוסף כדי לקיים מצוה זו.","\u0003אמר ר' יוחנן: ושניהם\u0004 גם התנא הראשון (שהוא ר' מאיר, שסתם משנה כשיטתו) ור' אלעזר ור' שמעון \u0003מקרא אחד דרשו\u0004 שנאמר: \"וכיפר אהרן על קרנותיו אחת בשנה \u0003מדם חטאת הכפרים אחת בשנה\u0004 יכפר עליו לדורותיכם קודש קדשים הוא לה'\" (שמות ל, י)","\u0003ר' מאיר סבר: חטאת אחת אמרתי לך, ולא שתי חטאות.\u0004 לומר שלצורך הכפרה, אין להזות על מזבח הפנימי מדמם של שני קרבנות, ולכן אם נשפך דם חטאת אחת באמצע ההזיה, אין להשלים את המתנה מדמו של קרבן אחר אלא צריך לחזור ולשחוט קרבנות חדשים, כדי שאפשר יהא לתת על המזבח כל המתנות מדמה של חטאת אחת. \u0003ר' אלעזר ור' שמעון סברי\u0004 \u0005[סבורים]:\u0006 \u0003חטוי אחד אמרתי לך ולא שני חטויין,\u0004 שאם כבר חיטא (הזה) פעם אחת — אין חוזרים ומזים, ואם נשפך הדם באמצע משלימים על ידי קרבן אחר.","בקשר למחלוקת זו שנינו: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבי: לי חלק ר' יעקב בלוגין.\u0004 כלומר: כאשר שנה לי ר' יעקב, לימד אותי שאף שנחלקו ר' מאיר ור' שמעון לענין מתנות הדם ביום הכיפורים ואמרו כי ממקום שפסק שם הוא מתחיל, אולם אם נשפך מלוג השמן של טהרת המצורע באמצע המתנות שלו — לא נחלקו.","ותוהים: \u0003ולא?\u0004 וכי לא נחלקו אף בענין זה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 מפורשת: \u0003נתן\u0004 מן השמן \u0003מקצת מתנות שבפנים\u0004 שמזה במקדש \u0003ונשפך הלוג — יביא לוג אחר ויתחיל בתחילה במתנות שבהיכל,\u0004 ואילו \u0003ר' אלעזר ור' שמעון אומרים: ממקום שפסק —\u0004 משם \u0003הוא מתחיל.\u0004","וכן אם \u0003גמר מתנות שבהיכל ונשפך הלוג — יביא לוג אחר ויתחיל בתחילה במתנות\u0004 שהוא נותן על \u0003בהונות\u0004 המצורע. \u0003נתן מקצת מתנות בבהונות ונשפך הלוג — יביא לוג אחר ויתחיל בתחילה במתנות שבבהונות, ר' אלעזר ור' שמעון אומרים: ממקום שפסק —\u0004 משם \u0003הוא מתחיל. גמר מתנות שבבהונות ונשפך הלוג — דברי הכל מתנות הראש לא מעכבות.\u0004 ואם כן משמע שנחלקו ר' אלעזר ור' שמעון אף בענין השמן שבטהרת המצורע!","אלא צריך לתקן את גירסת דברי רבי ולומר \u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003לי שנה ר' יעקב בלוגין.\u0004 כלומר, כשם שיש מחלוקת בענין נשפך הדם במתנות יום הכיפורים, כך שנה ר' יעקב מחלוקת כזו גם בלוג שמן של מצורע. ומעתה דנים קצת בענין.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003מתנות\u0004 השמן הניתנות ב\u0003ראש\u0004 המצורע — \u0003אין מעכבות\u0004 לדעת הכל. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של דבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והנותר מן השמן\u0004 אשר על כף הכהן יתן על ראש המיטהר לכפר עליו לפני ה'\u0003\"\u0004 (ויקרא יד, כט), ללמדנו שנתינה זו אינה אלא מן הנותר שהוא בבחינת שיריים ואינה עיקר הכפרה, \u0003אלא מעתה\u0004 מה שנאמר: \u0003\"והנותרת מן המנחה\u0004 לאהרן ולבניו קודש קדשים מאישי ה'\u0003\"\u0004 (ויקרא ב, ג), \u0003הכי נמי דלא מעכבי\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאינם מעכבים]?\u0006 והרי יודעים אנו שאם אבדו שיירי המנחה לפני הקטרת הקומץ — אין הקומץ עולה למקריב, וצריך להביא מנחה נוספת!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בענין לוג השמן שבמצורע משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 קודם: \u0003\"ומיתר\u0004 השמן אשר על כפו יתן הכהן על תנוך אוזן המיטהר הימנית ועל בוהן ידו הימנית ועל בוהן רגלו הימנית\u0003\"\u0004 (ויקרא יד, יז) ונאמר גם: \u0003\"והנותר\u0004 בשמן אשר על כף הכהן יתן על ראש המיטהר\u0003\"\u0004 (ויקרא יד, יח), הרי שהנתינה שעל הראש היא רק שיירי שיריים וזה ודאי שאינו מעכב.","\u0003אמר ר' יוחנן:\u0004"],["\u0003אשם מצורע ששחטו שלא לשמו\u0004 אלא לשם קרבן אחר (עולה, או שלמים) — \u0003באנו למחלוקת ר' מאיר ור' אלעזר ור' שמעון.\u0004 כיצד? \u0003ר' מאיר\u0004 ש\u0003אמר\u0004 בענין עבודה שלא נגמרה \u0003יביא אחר ויתחיל בתחילה — הכא נמי\u0004 \u0005[כאן גם כן]\u0006 באשם המצורע \u0003יביא אחר וישחוט,\u0004 שהרי לדעתו עבודה שלא נגמרה כדינה כאילו לא נעשתה כלל.","\u0003ולר' אלעזר ור' שמעון שאומרים ממקום שפסק משם הוא מתחיל — הכא\u0004 \u0005[כאן]\u0006 שלשיטתם עבודה שלא נגמרה כתיקנה — עבודה היא, אף כאן מה ששחט שחט, ולהביא אשם שני אינו יכול, שלא אמר הכתוב אלא \"כבש אחד אשם\" — למעט שני אשמות, על כן \u0003אין לו תקנה.\u0004","\u0003מתקיף ליה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חסדא: והא\u0004 \u0005[והרי]\u0006 \"והקריב \u0003אתו\u0004 לאשם\" (ויקרא יד, יב) \u0003כתיב\u0004 \u0005[נאמר],\u0006 משמע: אותו אשם שהניף קודם אותו יקריב, ואם אינו עושה כן — פסול. ואם כן גם לדעת ר' מאיר אינו יכול להשלים בקרבן אחר והריהו מעכב. ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה].\u0006","אולם \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: אשם מצורע ששחטו שלא לשמו, או שלא נתן מדמו לגבי בהונות — הרי\u0004 אשם \u0003זה עולה\u0004 (מוקרב) \u0003לגבי מזבח, וטעון נסכים\u0004 כאילו היה כשר, אולם \u0003צריך\u0004 המצורע להביא \u0003אשם אחר להכשירו.\u0004 משמע שיש מי שסבור שיש לו תקנה בהבאת אשם אחר והרי זו אם כן לכאורה גם קושיה לרב חסדא! על כן אומרים: \u0003ורב חסדא אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"צריך\"\u0004 שנאמר כאן — \u0003צריך\u0004 לעשות כן אם אפשר היה, וכיון שאי אפשר \u0003אין לו תקנה.\u0004","ותוהים: \u0003ותני\u0004 \u0005[וכי שנה]\u0006 ה\u0003תנא\u0004 ביטוי כזה \u0003\"צריך\",\u0004 שפירושו \u0003ואין לו תקנה?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 \u0003והתניא\u0004 \u0005[וכן\u0006 אכן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003נזיר ממורט\u0004 שהוא קרח לגמרי ואין לו שערות כלל, ולפיכך איננו יכול לגלח בתער את שערו, כדין הראוי בנזיר. \u0003בית שמאי אומרים: צריך העברת תער\u0004 מכל מקום, \u0003ובית הלל אומרים: אין צריך העברת תער. ואמר ר' אבינא: כשאומרים בית שמאי\u0004 בענין זה \u0003\"צריך\",\u0004 כוונתם \u0003צריך\u0004 וכיון שאינו יכול — \u0003אין לו תקנה.\u0004","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעת ר' אבינא בפירוש הדברים הללו על דעת \u0003ר' פדת.\u0004 ש\u0003אמר ר' פדת: בית שמאי ור' אלעזר אמרו דבר אחד,\u0004 כלומר: יש להם אותה שיטה. \u0003בית שמאי — הא דאמרן\u0004 \u0005[זאת שאמרנו],\u0006 שלשיטתם נזיר ממורט צריך העברת תער. \u0003ר' אלעזר, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 מצורע ש\u0003אין לו בהן יד\u0004 או \u0003בהן רגל\u0004 להזות עליהן — \u0003אין לו טהרה עולמית.\u0004 ואילו \u0003ר' אלעזר אומר: נותן על מקומו\u0004 במקום ששם היה הבוהן \u0003ויוצא\u0004 בכך ידי חובה. \u0003ר' שמעון אומר: אם נתן על\u0004 יד או רגל \u0003של שמאל — יצא.\u0004 ואם כן הוא מפרש \"צריך\" אם אפשר, ואם אי אפשר — יצא אף בלא תקנה זו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"ולקח\u0004 הכהן \u0003מדם האשם\u0004 ונתן הכהן על תנוך אוזן המיטהר הימנית ועל בוהן ידו הימנית ועל בוהן רגלו הימנית\u0003\"\u0004 (ויקרא יד, יד). \u0003יכול\u0004 יקח \u0003בכלי — תלמוד לומר: \"ונתן\". מה נתינה\u0004 כוונתו \u0003בעצמו,\u0004 בגופו \u0003של כהן — אף לקיחה בעצמו של כהן.\u0004","\u0003יכול אף\u0004 בדם אשם המצורע שנותן \u0003למזבח\u0004 כדין שאר אשמות \u0003כן,\u0004 שיקבל הדם בידו ולא בכלי — \u0003תלמוד לומר: \"כי כחטאת האשם הוא\"\u0004 (ויקרא יד, יג), ללמד: \u0003מה חטאת טעונה כלי\u0004 בקבלת הדם — \u0003אף\u0004 דם ה\u0003אשם טעון\u0004 קבלה ב\u0003כלי.\u0004 ו\u0003נמצאת אתה אומר: אשם מצורע\u0004 טעון \u0003שני כהנים\u0004 ה\u0003מקבלים את דמו, אחד\u0004 מקבל \u0003ביד ואחד\u0004 מקבל \u0003בכלי. זה שקבל בכלי בא לו אצל מזבח\u0004 ומזה מן הדם על המזבח, \u0003וזה שקיבל ביד בא לו אצל מצורע\u0004 ומזה מן הדם עליו.","\u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 \u0003וכולן\u0004 כל הפרים והשעירים שנשחטו, אם נשפך דמו של אחד מהם לאחר סיום שלב כפרה אחד והוצרכו להביא אחרים כדי להשלים את מתנות הדם בשלב שלאחריו — צריכים כולם שריפה ו\u0003מטמאים בגדים\u0004 של כל העסוקים בשריפתן \u0003ונשרפין בבית הדשן\u0004 כדין חטאות הפנימיות, אלו \u0003דברי ר' אלעזר ור' שמעון, וחכמים אומרים: אין מטמאין בגדים ואין נשרפין אבית הדשן אלא האחרון\u0004 שבהם, \u0003הואיל וגמר בו\u0004 את ה\u0003כפרה.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן: כמה שעירים משלח?\u0004 כלומר, כיון שאם נשפך דם השעיר הנעשה בפנים יש צורך להביא זוג שעירים נוסף ולעשות גורל חדש שוב וכן יכול לקרות כמה פעמים. ואחד מן הזוג הוא שעיר לה', ונמצא שיש כמה שעירים שהם שעירים המשתלחים, מה עושה בהם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי עדרו משלח?\u0004 כלומר, התורה אמרה לשלח רק אחד ולא עדר שלם! \u0003אמר לו\u0004 רבא:"]]};
